/* EmberFx2Engine —— 写实特效管线（WebGL1，一张 canvas）。
 *
 * V2（2026-09-17，docs/design/BATTLE_PRESENTATION_V2.md §3.3）重构后的结构：
 *   · plan(kind, {from, targets, tier, aoe}) 纯函数：接触时刻与总时长，node 可测。
 *   · createSim()：与 GL 无关的一半 —— 实例、粒子、时钟、冲击队列、ctx。每个实例把
 *     真实时间分段映射到技能配方的"自然时间"（knotsFor），接触帧 = plan 的 hitAt、
 *     接触后 residueMaxMs 内画面全部收完，都是这张映射构造出来的。
 *   · 技能配方按层作画：caster（施法者处，按施法者卡缩放）/ path（施法者 → 目标，
 *     不缩放）/ contact（按目标卡包围盒与档位等比缩放，逐轴外包 ≤ contactBoxMax × w|h ×
 *     contactScale/1.2）/ ground（群体地面层，并集 + aoePad）。
 *   · impulse({at, tier, cinematic})：唯一的震屏 / 顿帧 / 边缘闪 / 推镜来源。技能配方里
 *     不再有 camera / hitStop / flashFrame / cutin / cardHit 轨道。
 *   · create()：把模拟器接到批渲染器与后期链上。没有自己的 rAF，draw(now) 由宿主驱动。
 *
 * pass 顺序（特效活动时）：
 *   1  scene     宿主世界画布 → sceneRT（只有折射要用时才跑）
 *   2  fx        所有特效元素 → fxRT（桶：ground / add / body / smoke）
 *   3  distort   需要折射背景的元素 → distortRT（低档关闭）
 *   4  bright    fxRT 亮度阈值 + 2×2 降采样 → bloom 1/4
 *   5  blur ×2   1/4 级横向、纵向高斯
 *   6  blur ×2   1/8 级（低档 / 高 DPR 跳过）
 *   7  composite 折射差值 + fxRT + 两级 bloom → compRT
 *   8  final     色调压缩 → 屏幕
 *
 * 空闲时整条链跳过：canvas 清空、0 个 draw call。
 * 复现：固定 1/60s 步长 + mulberry32 定种随机 + debugSeek(ms)。
 */
const EmberFx2Engine = (() => {
  "use strict";

  const STAGE_W = 1600;
  const STAGE_H = 940;
  const FIXED_DT = 1000 / 60;
  const MAX_DPR = 2;

  /** 贴地元素的 Y 压扁系数。量自底图中央徽记，沿用第一代的实测值（见 arena-fx README §3）。 */
  const GROUND_SQUASH = 0.8;

  // ---- 批渲染桶。前四个进 fxRT，最后一个进 distortRT。 ----------------------
  //
  // `body` 是第 6 轮加的：**不透明的赛璐璐火焰**。加性永远做不出不透明的火，
  // 颜色只会往背景上叠成一层半透明的膜（第 5 轮的爆炸就是这个毛病）。
  // 它画在 add 之后 —— 辉光垫底，实体火焰盖上去。
  const BUCKETS = ["ground", "add", "body", "smoke", "distort"];
  const BUCKET_CAP = { ground: 128, add: 3072, body: 512, smoke: 512, distort: 64 };
  // 第 12 轮 22 → 26：序列帧（mode 8）与带状渲染（mode 9）的参数塞不进 12 个
  // 槽（p2 整条被图集矩形占着），所以加了第四条 vec4 通道 aP3。
  // 代价实测：add 桶 3072×6×26×4 = 1.92MB（原 1.62MB），五个桶合计 2.6MB，
  // 顶点属性数到 8 —— **WebGL1 保证的下限就是 8，这是硬上限**，下一个参数
  // 只能靠位域塞进现有的 float 里，不能再加一条属性。
  const FLOATS_PER_VERT = 26; // pos2 uv2 color4 local2 p0:4 p1:4 p2:4 p3:4
  const VERTS_PER_QUAD = 6;

  // ---- 着色器模式（与 sprite.frag.glsl 顶部的表一一对应）--------------------
  const M = {
    SOFT: 0, DISSOLVE: 1, POLAR: 2, TRAIL: 3, SHAPE: 4, DISTORT: 5, SPRITE: 6,
    SPRITE_FLOW: 7, FLIPBOOK: 8, RIBBON: 9, EDGE: 10, SOLID: 11,
  };
  // 渐变表行号。0..4 是最早烘出来的五行（素材已不可再生，tools/fx2_gradients.py
  // 把它们原样拷过去）；5..9 是第 12 轮补的学派色，给渐变映射用。
  const G = {
    FIRE: 0, LIGHTNING: 1, ARCANE: 2, EMBER: 3, SLASH: 4,
    FROST: 5, HOLY: 6, NATURE: 7, VOID: 8, BLOOD: 9,
  };

  // 原子件拼装顺序。flow 必须在 dissolve 之前（dissolve 调用 flowUV）。
  const SPRITE_ATOMS = [
    "atom-common.glsl",
    "atom-flow.glsl",
    "atom-dissolve.glsl",
    "atom-polar.glsl",
    "atom-trail.glsl",
    "atom-distort.glsl",
    "atom-sprite.glsl",
    "atom-flipbook.glsl",
    "sprite.frag.glsl",
  ];

  // 纹理走 asset: 协议，构建时替换成内联 data URI（便携版不能发网络请求）。
  //
  // 表驱动：键的顺序 = 纹理单元号，`uniform` = 着色器里的 sampler 名，
  // `repeat` = REPEAT 包裹（噪声/流向图），`mipmap` = 生成 mip 链（只有 POT 的
  // 图集能开；它会被缩到十几像素画碎石，没有 mip 就是一片闪烁的噪点）。
  const TEXTURE_SRC = {
    noise: { src: "asset:fx2/noise-fbm.webp", uniform: "uNoise", repeat: true },
    worley: { src: "asset:fx2/noise-worley.webp", uniform: "uWorley", repeat: true },
    flow: { src: "asset:fx2/flow.webp", uniform: "uFlow", repeat: true },
    grad: { src: "asset:fx2/gradients.webp", uniform: "uGrad" },
    shapes: { src: "asset:fx2/flame-shapes.webp", uniform: "uShapes" },
    atlas2: { src: "asset:fx2/atlas-strike.webp", uniform: "uAtlas2", mipmap: true },
    atlas3: { src: "asset:fx2/atlas-fb.webp", uniform: "uAtlas3", mipmap: true },
    atlas4: { src: "asset:fx2/atlas-spell.webp", uniform: "uAtlas4", mipmap: true },
  };
  const TEXTURE_KEYS = Object.keys(TEXTURE_SRC);

  // 贴图图集的格子表（名字 → u0, v0, u1, v1, 图集号）。图集号 0 = atlas-slam、
  // 1 = atlas-strike，ctx.sprite 把它折进 kind 的高位传给着色器，所以技能配方里
  // 只要写格子名，不用管这一格在哪张图上。
  // 由 tools/fx2_atlas.py 打图集时一并写回，手改会在下次打包时被覆盖。
  // >>> ATLAS_CELLS (generated by tools/fx2_atlas.py) >>>
  const ATLAS_CELLS = Object.freeze({
    flash: [0.0, 0.0, 0.25, 0.25, 1],
    ringAnnulus: [0.25, 0.0, 0.5, 0.25, 1],
    shockwave: [0.5, 0.0, 0.75, 0.25, 1],
    clawTrail: [0.75, 0.0, 1.0, 0.25, 1],
    arrowTrail: [0.0, 0.25, 0.25, 0.5, 1],
    arrowHit: [0.25, 0.25, 0.5, 0.5, 1],
    dustwave: [0.5, 0.25, 0.75, 0.5, 1],
    spearHit: [0.75, 0.25, 1.0, 0.5, 1],
    embers: [0.0, 0.5, 0.25, 0.75, 1],
    rock0: [0.25, 0.5, 0.3125, 0.5625, 1],
    rock1: [0.3125, 0.5, 0.375, 0.5625, 1],
    rock2: [0.375, 0.5, 0.4375, 0.5625, 1],
    rock3: [0.4375, 0.5, 0.5, 0.5625, 1],
    breathStream: [0.5, 0.5, 0.75, 0.75, 1],
    rock4: [0.25, 0.5625, 0.3125, 0.625, 1],
    rock5: [0.3125, 0.5625, 0.375, 0.625, 1],
    breathScorch: [0.0, 0.75, 0.25, 1.0, 1],
    flashWhite: [0.25, 0.75, 0.375, 0.875, 1],
    embersCool: [0.375, 0.75, 0.5, 0.875, 1],
    breathTile: [0.5, 0.75, 0.75, 0.875, 1],
    slashSparks: [0.25, 0.875, 0.375, 1.0, 1],
    boltOrb: [0.375, 0.875, 0.5, 1.0, 1],
    impactFb: [0.0, 0.0, 0.5, 0.5, 2],
    slashArcFb: [0.5, 0.0, 1.0, 0.5, 2],
    smokeFb: [0.0, 0.5, 0.25, 0.75, 2],
    fireFb: [0.25, 0.5, 0.5, 0.75, 2],
    electricFb: [0.5, 0.5, 0.75, 0.75, 2],
    lightningFb: [0.75, 0.5, 1.0, 0.75, 2],
    swordRibbon: [0.0, 0.75, 0.5, 1.0, 2],
    groundCrack: [0.5, 0.75, 0.75, 1.0, 2],
    holyPillar: [0.0, 0.0, 0.5, 0.5, 3],
    lightningStrike: [0.5, 0.0, 1.0, 0.5, 3],
    frostBurst: [0.0, 0.5, 0.25, 0.75, 3],
    frostField: [0.25, 0.5, 0.5, 0.75, 3],
    healRise: [0.5, 0.5, 0.75, 0.75, 3],
    natureBurst: [0.0, 0.75, 0.25, 1.0, 3],
    voidImplode: [0.25, 0.75, 0.5, 1.0, 3],
    siphonOrbs: [0.5, 0.75, 0.75, 1.0, 3],
    arcaneBurst: [0.75, 0.75, 1.0, 1.0, 3],
  });
  // <<< ATLAS_CELLS <<<

  // ------------------------------------------------------------------ 工具

  function shader(name) {
    const src = EmberFx2Shaders[name];
    if (typeof src !== "string") throw new Error("缺少着色器 " + name);
    return src;
  }

  function loadImage(url) {
    return new Promise((done, fail) => {
      const img = new Image();
      img.onload = () => done(img);
      img.onerror = () => fail(new Error("图片加载失败 " + url));
      img.src = url;
    });
  }

  /** mulberry32：与第一代同一实现，同 seed 同时刻像素一致。 */
  function mulberry32(seed) {
    let a = seed >>> 0;
    return function () {
      a = (a + 0x6d2b79f5) >>> 0;
      let t = a;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
  const lerp = (a, b, t) => a + (b - a) * t;
  const smooth = (t) => t * t * (3 - 2 * t);
  const easeOut = (t) => 1 - Math.pow(1 - t, 3);
  const easeOutQuint = (t) => 1 - Math.pow(1 - t, 5);
  const easeIn = (t) => t * t * t;
  const easeOutBack = (t) => {
    const c = 1.70158;
    const u = t - 1;
    return 1 + (c + 1) * u * u * u + c * u * u;
  };
  /** 把主色推离灰轴（k > 1 加饱和）。卡面尺度下淡色会被插画吃掉。 */
  function saturate(col, k) {
    const l = col[0] * 0.299 + col[1] * 0.587 + col[2] * 0.114;
    return [
      clamp(l + (col[0] - l) * k, 0, 1),
      clamp(l + (col[1] - l) * k, 0, 1),
      clamp(l + (col[2] - l) * k, 0, 1),
    ];
  }

  /**
   * 往白里兑。贴图自带色（火是橙的、闪电是紫的），直接乘学派主色只会把两个
   * 色相压成一坨灰；兑掉一半之后主色还读得出来（冰系随从的刀光仍然偏冷），
   * 贴图自己的内外发光也还在。k = 兑白比例，0 = 纯主色、1 = 纯白。
   */
  function wash(c, k) {
    return [
      c[0] + (1 - c[0]) * k, c[1] + (1 - c[1]) * k, c[2] + (1 - c[2]) * k,
    ];
  }

  /** 数字或 [min, max] 区间 → 取值。ctx.spawn 的每个随机参数都过它。 */
  function rangeAt(rng, v, fallback) {
    if (v == null) return fallback;
    if (Array.isArray(v)) return v[0] + (v[1] - v[0]) * rng();
    return v;
  }

  // 新素材全是 4×4 / 16 帧，配方里不写 frames 就按它来
  const FB_DEFAULT_GRID = Object.freeze({ cols: 4, rows: 4, count: 16 });

  const EASES = { linear: (t) => t, smooth, out: easeOut, outQuint: easeOutQuint, in: easeIn, outBack: easeOutBack };

  // --------------------------------------------------------- 时间线取样

  /**
   * 关键帧轨道取样。track = [{t, v, ease}]，v 是数字或等长数组。
   * 区间两端之外取端点值（保持），所以轨道不必铺满整条时间线。
   */
  function sampleTrack(track, t, fallback) {
    if (!track || !track.length) return fallback;
    if (t <= track[0].t) return track[0].v;
    const last = track[track.length - 1];
    if (t >= last.t) return last.v;
    for (let i = 0; i < track.length - 1; i++) {
      const a = track[i];
      const b = track[i + 1];
      if (t >= a.t && t <= b.t) {
        const span = b.t - a.t;
        let u = span <= 0 ? 1 : (t - a.t) / span;
        u = (EASES[b.ease] || EASES.smooth)(u);
        if (Array.isArray(a.v)) {
          const out = new Array(a.v.length);
          for (let k = 0; k < a.v.length; k++) out[k] = lerp(a.v[k], b.v[k], u);
          return out;
        }
        return lerp(a.v, b.v, u);
      }
    }
    return fallback;
  }

  // ------------------------------------------------------------- 批渲染器

  function createBatcher(gl, program) {
    const attrib = {
      pos: gl.getAttribLocation(program, "aPos"),
      uv: gl.getAttribLocation(program, "aUV"),
      color: gl.getAttribLocation(program, "aColor"),
      local: gl.getAttribLocation(program, "aLocal"),
      p0: gl.getAttribLocation(program, "aP0"),
      p1: gl.getAttribLocation(program, "aP1"),
      p2: gl.getAttribLocation(program, "aP2"),
      p3: gl.getAttribLocation(program, "aP3"),
    };
    const stride = FLOATS_PER_VERT * 4;
    const buckets = {};
    BUCKETS.forEach((name) => {
      const floats = BUCKET_CAP[name] * VERTS_PER_QUAD * FLOATS_PER_VERT;
      const buf = gl.createBuffer();
      gl.bindBuffer(gl.ARRAY_BUFFER, buf);
      gl.bufferData(gl.ARRAY_BUFFER, floats * 4, gl.DYNAMIC_DRAW);
      buckets[name] = { name, data: new Float32Array(floats), n: 0, buffer: buf, overflow: 0 };
    });

    let drawCalls = 0;
    let quads = 0;

    function reset() {
      BUCKETS.forEach((k) => {
        buckets[k].n = 0;
        buckets[k].overflow = 0;
      });
      drawCalls = 0;
      quads = 0;
    }

    function vert(b, x, y, u, v, col, lu, lv, p0, p1, p2, p3) {
      const d = b.data;
      let i = b.n;
      if (i + FLOATS_PER_VERT > d.length) {
        b.overflow += 1;
        return;
      }
      d[i] = x; d[i + 1] = y;
      d[i + 2] = u; d[i + 3] = v;
      d[i + 4] = col[0]; d[i + 5] = col[1]; d[i + 6] = col[2]; d[i + 7] = col[3];
      d[i + 8] = lu; d[i + 9] = lv;
      d[i + 10] = p0[0]; d[i + 11] = p0[1]; d[i + 12] = p0[2]; d[i + 13] = p0[3];
      d[i + 14] = p1[0]; d[i + 15] = p1[1]; d[i + 16] = p1[2]; d[i + 17] = p1[3];
      d[i + 18] = p2[0]; d[i + 19] = p2[1]; d[i + 20] = p2[2]; d[i + 21] = p2[3];
      d[i + 22] = p3[0]; d[i + 23] = p3[1]; d[i + 24] = p3[2]; d[i + 25] = p3[3];
      b.n = i + FLOATS_PER_VERT;
    }

    /**
     * 旋转四边形。squash 作用在旋转之后（贴地元素：在地面坐标系里旋转再投影），
     * 这一条沿用第一代的结论——先压扁再旋转会让旋转中的元素忽胖忽瘦。
     */
    function quad(bucket, o) {
      const b = buckets[bucket];
      if (b.n + VERTS_PER_QUAD * FLOATS_PER_VERT > b.data.length) {
        b.overflow += 1;
        return;
      }
      const rot = o.rot || 0;
      const c = Math.cos(rot);
      const s = Math.sin(rot);
      const q = o.squash == null ? 1 : o.squash;
      const ax = o.ax == null ? 0.5 : o.ax;
      const ay = o.ay == null ? 0.5 : o.ay;
      const w = o.w;
      const h = o.h == null ? o.w : o.h;
      const lx = -ax * w;
      const rx = (1 - ax) * w;
      const ty = -ay * h;
      const by = (1 - ay) * h;
      const cx = o.x;
      const cy = o.y;
      const x0 = cx + lx * c - ty * s;
      const y0 = cy + (lx * s + ty * c) * q;
      const x1 = cx + rx * c - ty * s;
      const y1 = cy + (rx * s + ty * c) * q;
      const x2 = cx + rx * c - by * s;
      const y2 = cy + (rx * s + by * c) * q;
      const x3 = cx + lx * c - by * s;
      const y3 = cy + (lx * s + by * c) * q;
      const col = o.col;
      const p0 = o.p0;
      const p1 = o.p1 || ZERO4;
      const p2 = o.p2 || ZERO4;
      const p3 = o.p3 || ZERO4;
      const u0 = o.u0 == null ? 0 : o.u0;
      const v0 = o.v0 == null ? 0 : o.v0;
      const u1 = o.u1 == null ? 1 : o.u1;
      const v1 = o.v1 == null ? 1 : o.v1;
      vert(b, x0, y0, u0, v0, col, 0, 0, p0, p1, p2, p3);
      vert(b, x1, y1, u1, v0, col, 1, 0, p0, p1, p2, p3);
      vert(b, x2, y2, u1, v1, col, 1, 1, p0, p1, p2, p3);
      vert(b, x0, y0, u0, v0, col, 0, 0, p0, p1, p2, p3);
      vert(b, x2, y2, u1, v1, col, 1, 1, p0, p1, p2, p3);
      vert(b, x3, y3, u0, v1, col, 0, 1, p0, p1, p2, p3);
      quads += 1;
    }

    /**
     * 拖尾网格：折线扩成三角带。pts = [{x, y, hw, col}]。
     * UV：u 沿长度 0（尾）→1（头），v 横截面 0..1。几何部分照搬第一代的 strip()。
     */
    function strip(bucket, pts, p0, p1, p2o, p3o, closed) {
      const p2 = p2o || ZERO4;
      const p3 = p3o || ZERO4;
      if (pts.length < 2) return;
      const b = buckets[bucket];
      const nx = [];
      const ny = [];
      const last = pts.length - 1;
      for (let i = 0; i < pts.length; i++) {
        // 闭合路径（环）：首尾两点的法线绕回去算，否则接缝处的带宽会塌一半，
        // 环上就多一道亮缝。
        // 闭合路径的调用方把第 0 点又追加到了末尾（见 ctx.ring），所以取模的
        // 周期是 last 而不是 pts.length。
        const p = closed ? pts[(i - 1 + last) % last] : pts[Math.max(0, i - 1)];
        const q = closed ? pts[(i + 1) % last] : pts[Math.min(last, i + 1)];
        const dx = q.x - p.x;
        const dy = q.y - p.y;
        const len = Math.hypot(dx, dy) || 1;
        nx.push(-dy / len);
        ny.push(dx / len);
      }
      for (let i = 0; i < pts.length - 1; i++) {
        if (b.n + VERTS_PER_QUAD * FLOATS_PER_VERT > b.data.length) {
          b.overflow += 1;
          return;
        }
        const p = pts[i];
        const q = pts[i + 1];
        const ua = i / (pts.length - 1);
        const ub = (i + 1) / (pts.length - 1);
        const ax = p.x + nx[i] * p.hw;
        const ay = p.y + ny[i] * p.hw;
        const bx = p.x - nx[i] * p.hw;
        const by = p.y - ny[i] * p.hw;
        const cx = q.x + nx[i + 1] * q.hw;
        const cy = q.y + ny[i + 1] * q.hw;
        const dx2 = q.x - nx[i + 1] * q.hw;
        const dy2 = q.y - ny[i + 1] * q.hw;
        const pc = p.col;
        const qc = q.col;
        vert(b, ax, ay, ua, 0, pc, 0, 0, p0, p1, p2, p3);
        vert(b, bx, by, ua, 1, pc, 0, 1, p0, p1, p2, p3);
        vert(b, cx, cy, ub, 0, qc, 1, 0, p0, p1, p2, p3);
        vert(b, bx, by, ua, 1, pc, 0, 1, p0, p1, p2, p3);
        vert(b, dx2, dy2, ub, 1, qc, 1, 1, p0, p1, p2, p3);
        vert(b, cx, cy, ub, 0, qc, 1, 0, p0, p1, p2, p3);
        quads += 1;
      }
    }

    function bindAttribs() {
      gl.enableVertexAttribArray(attrib.pos);
      gl.vertexAttribPointer(attrib.pos, 2, gl.FLOAT, false, stride, 0);
      gl.enableVertexAttribArray(attrib.uv);
      gl.vertexAttribPointer(attrib.uv, 2, gl.FLOAT, false, stride, 8);
      gl.enableVertexAttribArray(attrib.color);
      gl.vertexAttribPointer(attrib.color, 4, gl.FLOAT, false, stride, 16);
      gl.enableVertexAttribArray(attrib.local);
      gl.vertexAttribPointer(attrib.local, 2, gl.FLOAT, false, stride, 32);
      gl.enableVertexAttribArray(attrib.p0);
      gl.vertexAttribPointer(attrib.p0, 4, gl.FLOAT, false, stride, 40);
      gl.enableVertexAttribArray(attrib.p1);
      gl.vertexAttribPointer(attrib.p1, 4, gl.FLOAT, false, stride, 56);
      gl.enableVertexAttribArray(attrib.p2);
      gl.vertexAttribPointer(attrib.p2, 4, gl.FLOAT, false, stride, 72);
      gl.enableVertexAttribArray(attrib.p3);
      gl.vertexAttribPointer(attrib.p3, 4, gl.FLOAT, false, stride, 88);
    }

    /** 画出指定桶（按名字），blend 由调用方在外面设好。 */
    function flushBucket(name) {
      const b = buckets[name];
      if (b.n === 0) return;
      gl.bindBuffer(gl.ARRAY_BUFFER, b.buffer);
      gl.bufferSubData(gl.ARRAY_BUFFER, 0, b.data.subarray(0, b.n));
      bindAttribs();
      gl.drawArrays(gl.TRIANGLES, 0, b.n / FLOATS_PER_VERT);
      drawCalls += 1;
    }

    return {
      reset, quad, strip, flushBucket,
      has: (name) => buckets[name].n > 0,
      get drawCalls() { return drawCalls; },
      get quads() { return quads; },
      get overflow() {
        let n = 0;
        BUCKETS.forEach((k) => (n += buckets[k].overflow));
        return n;
      },
      destroy() { BUCKETS.forEach((k) => gl.deleteBuffer(buckets[k].buffer)); },
    };
  }

  const ZERO4 = [0, 0, 0, 0];

  // ------------------------------------------------------------- 粒子系统
  // 与第一代同一套（池化 + orbit 螺旋汇聚），只加了 mode / p0 / p1 让粒子
  // 也能走溶解、剪影等着色器模式，而不是只能是柔光点。

  function createParticles(cap) {
    const pool = [];
    const live = [];

    function blank() {
      return {
        x: 0, y: 0, vx: 0, vy: 0, gx: 0, gy: 0, drag: 0,
        age: 0, life: 1, s0: 10, s1: 10, sExp: 1,
        c0: [1, 1, 1], c1: [1, 1, 1], a0: 1, a1: 0, aExp: 1, fadeIn: 0.08,
        rot: 0, rotVel: 0, alignVel: false, stretch: 1,
        bucket: "add", mode: M.SOFT, p0: null, p1: null, seed: 0,
        orbit: null, squash: null,
        // SPRITE 模式用：图集格子的 UV 矩形；sinkY = 落到这条线以下就溶解淡出
        cell: null, sinkY: null,
        // FLIPBOOK 模式用：见 emit 的注释。child = 死亡时在原地放的一级子节点。
        fb: null, child: null,
        // V2：发射时的作用域（接触层缩放）、时间映射速率、残留期限
        rate: 1, xf: null, maxAge: Infinity, clamped: false,
      };
    }

    function emit(o) {
      if (live.length >= cap) return null;
      const p = pool.pop() || blank();
      p.x = o.x; p.y = o.y;
      p.vx = o.vx || 0; p.vy = o.vy || 0;
      p.gx = o.gx || 0; p.gy = o.gy || 0;
      p.drag = o.drag || 0;
      p.age = 0; p.life = o.life || 400;
      p.s0 = o.s0; p.s1 = o.s1 == null ? o.s0 : o.s1;
      p.sExp = o.sExp || 1;
      p.c0 = o.c0; p.c1 = o.c1 || o.c0;
      p.a0 = o.a0 == null ? 1 : o.a0;
      p.a1 = o.a1 == null ? 0 : o.a1;
      p.aExp = o.aExp || 1;
      p.fadeIn = o.fadeIn == null ? 0.08 : o.fadeIn;
      p.rot = o.rot || 0; p.rotVel = o.rotVel || 0;
      p.alignVel = !!o.alignVel;
      p.stretch = o.stretch || 1;
      p.bucket = o.bucket || "add";
      p.mode = o.mode == null ? M.SOFT : o.mode;
      p.p0 = o.p0 || null;
      p.p1 = o.p1 || null;
      p.seed = o.seed || 0;
      p.orbit = o.orbit || null;
      p.squash = o.squash == null ? null : o.squash;
      p.cell = o.cell ? ATLAS_CELLS[o.cell] || null : null;
      p.sinkY = o.sinkY == null ? null : o.sinkY;
      /**
       * fb = 序列帧粒子（mode 会被强制成 M.FLIPBOOK）：
       *   {cell, frames?, loops?, grad?, gradLo?, lerp?, kind?, uvDistort?,
       *    hdr?, threshold?, edgeWidth?, soft?, frame0?}
       * 帧号由**寿命**推：frame = (frame0 + u * count * loops)，loops 默认 1。
       * 变体表（lerp:false）传 frame0 = 变体号、loops = 0 就钉在一张上。
       */
      p.fb = o.fb || null;
      if (p.fb) {
        p.cell = ATLAS_CELLS[p.fb.cell] || null;
        p.mode = M.FLIPBOOK;
      }
      // child：这个粒子寿命到头时在它**当时的位置**放 count 个子粒子。
      // {count, inherit?, make(o, rng)} —— 一级即可（子粒子的 child 被忽略）。
      p.child = o.child || null;
      p.rate = 1;
      p.xf = null;
      p.maxAge = Infinity;
      p.clamped = false;
      live.push(p);
      return p;
    }

    function update(dtReal) {
      for (let i = live.length - 1; i >= 0; i--) {
        const p = live[i];
        // 粒子按发射它的实例当时的时间映射速率走（接触后压缩到 residueMaxMs 内）
        const dt = dtReal * p.rate;
        const s = dt / 1000;
        p.age += dt;
        if (p.age >= p.life) {
          const ch = p.child;
          const cx = p.x, cy = p.y, cvx = p.vx, cvy = p.vy;
          const left = p.maxAge - p.age;
          const rate = p.rate, xf = p.xf;
          live[i] = live[live.length - 1];
          live.pop();
          if (pool.length < cap) pool.push(p);
          if (ch && ch.make && left > 8) {
            // 一级子节点：在父节点死亡的位置生成，可继承一部分父速度；
            // 残留期限从父节点继承，不会把画面拖过 residueMaxMs。
            const k = ch.inherit == null ? 0 : ch.inherit;
            for (let c = 0; c < (ch.count || 1); c++) {
              const e = { x: cx, y: cy, vx: cvx * k, vy: cvy * k };
              ch.make(e, Math.random);
              if (e.life > left) e.life = left;
              const kid = emit(e);
              if (!kid) continue;
              kid.child = null;
              kid.rate = rate;
              kid.xf = xf;
              kid.maxAge = left;
              kid.clamped = e.life >= left - 1e-6;
            }
          }
          continue;
        }
        if (p.orbit) {
          const u = p.age / p.life;
          const o = p.orbit;
          const r = lerp(o.r0, o.r1, easeIn(u));
          const ang = o.a0 + o.spin * u;
          p.x = o.ox + Math.cos(ang) * r;
          p.y = o.oy + Math.sin(ang) * r * o.squash;
          continue;
        }
        p.vx += p.gx * s;
        p.vy += p.gy * s;
        if (p.drag) {
          const k = Math.exp(-p.drag * s);
          p.vx *= k;
          p.vy *= k;
        }
        p.x += p.vx * s;
        p.y += p.vy * s;
        p.rot += p.rotVel * s;
      }
    }

    return {
      emit, update, live,
      get count() { return live.length; },
      clear() {
        while (live.length) {
          const p = live.pop();
          if (pool.length < cap) pool.push(p);
        }
      },
    };
  }

  // ------------------------------------------------------------------ 技能
  // 每个技能只声明：
  //   nat = {launch, impact, end}  配方的自然时刻（真实时间由 plan + knotsFor 映射过来）
  //   extent / castExtent          接触层 / 施法者层在 k = 1 时的自然外包（px，
  //                                由 tools/fx2-measure.cjs --calibrate 量出来）
  //   post = {bloom1, bloom2, distort}  后期轨道（自然时间）
  //   init / update / draw         用 ctx 的作用域（caster/path/contact/ground）与原子件作画

  const SKILLS = {};
  require_fireball();

  function require_fireball() {
    // 第 7 轮定下的彗星飞行（直线射出、白热头、螺旋火焰带、余烬尾）原样保留。
    //
    // V2（2026-09-17）：
    //   · 时间交给 plan()：自然时间 [0, launch] 的蓄力压进 castFlash（120ms），
    //     [launch, impact] 的飞行按距离 1400px/s，接触后的一切压进 residueMaxMs。
    //   · 施法者处的蓄力在 caster 层（按施法者卡缩放），彗星在 path 层（从施法者
    //     卡心出发、落在目标卡心），爆炸在 contact 层（按目标卡与档位缩放）。
    //   · 爆炸按单体尺寸约束缩小：冲击环 680 → 400、放射线 680 → 420、外圈辉光
    //     620 → 400，火花与碎火的初速减半 —— 否则它们决定了接触层的外包尺寸，
    //     缩放会把三层火焰本体一起压没。
    //   · 删掉：切入、顿帧、震屏、推镜、闪帧、聚光与暗角（统一由 impulse 接管）。
    const T = { antic: 260, launch: 260, flight: 240, impact: 500, release: 300 };

    /** 直线飞行。u = 0..1（时间进度）。起步慢再加速，加极小的垂直正弦抖动。 */
    function flightU(u) {
      return Math.pow(clamp(u, 0, 1), 1.35);
    }
    function flightPos(inst, u) {
      const k = flightU(u);
      const wob = Math.sin(k * 21.0 + inst.seed * 0.01) * 3.5 * k * inst.kp;
      return {
        x: lerp(inst.from.x, inst.to.x, k) - Math.sin(inst.aim) * wob,
        y: lerp(inst.from.y, inst.to.y, k) + Math.cos(inst.aim) * wob,
      };
    }
    /** 从当前头部沿飞行轴向后取一段路径点（尾→头），给彗尾用。尾端不越过施法者。 */
    function cometPath(inst, u, lengthPx, n) {
      const head = flightPos(inst, u);
      const dist = Math.hypot(inst.to.x - inst.from.x, inst.to.y - inst.from.y) || 1;
      const traveled = flightU(u) * dist;
      const L = Math.min(lengthPx, traveled);
      const pts = new Array(n);
      for (let i = 0; i < n; i++) {
        const s = 1 - i / (n - 1); // 1 = 尾端
        const back = L * s;
        const ub = clamp((traveled - back) / dist, 0, 1);
        const wob = Math.sin(ub * 21.0 + inst.seed * 0.01) * 3.5 * ub * inst.kp;
        pts[i] = {
          x: head.x - Math.cos(inst.aim) * back - Math.sin(inst.aim) * wob,
          y: head.y - Math.sin(inst.aim) * back + Math.cos(inst.aim) * wob,
        };
      }
      return pts;
    }

    SKILLS.fireball = {
      label: "火球",
      nat: { launch: T.launch, impact: T.impact, end: T.impact + T.release },
      extent: 375,
      castExtent: 240,

      post: {
        bloom1: [
          { t: 0, v: 0.30 }, { t: T.launch, v: 0.42 }, { t: T.impact - 10, v: 0.46 },
          { t: T.impact + 6, v: 0.66 }, { t: T.impact + 120, v: 0.50 },
          { t: T.impact + T.release, v: 0.30 },
        ],
        bloom2: [
          { t: 0, v: 0.14 }, { t: T.impact, v: 0.18 }, { t: T.impact + 6, v: 0.26 },
          { t: T.impact + 160, v: 0.16 }, { t: T.impact + T.release, v: 0.14 },
        ],
        distort: [
          { t: 0, v: 0 }, { t: T.launch, v: 6 }, { t: T.impact - 10, v: 8 },
          { t: T.impact + 4, v: 24 }, { t: T.impact + 150, v: 10 },
          { t: T.impact + T.release, v: 0 },
        ],
      },

      init(inst) {
        inst.emitAcc = 0;
        inst.smokeAcc = 0;
        inst.emberAcc = 0;
        inst.spiraled = 0;
        inst.aim = Math.atan2(inst.to.y - inst.from.y, inst.to.x - inst.from.x);
      },

      update(inst, ctx, dt) {
        const t = inst.t;
        const rng = inst.rng;
        const F = inst.from;
        const To = inst.to;
        const P = inst.kp;

        // ---- 预兆：少量余烬螺旋汇入（施法者层）------------------------------
        if (ctx.caster(inst)) {
          if (t > 40 && t < T.antic && inst.spiraled < 22) {
            inst.emitAcc += dt;
            while (inst.emitAcc >= 9 && inst.spiraled < 22) {
              inst.emitAcc -= 9;
              inst.spiraled += 1;
              const life = 160 + rng() * 90;
              ctx.particles.emit({
                x: F.x, y: F.y, life,
                s0: 14 + rng() * 10, s1: 4, sExp: 1.5,
                c0: [1.0, 0.62, 0.20], c1: [1.0, 0.94, 0.72],
                a0: 0.95, a1: 0.25, fadeIn: 0.2,
                mode: M.SOFT, p0: [M.SOFT, 1.9, 0, 0],
                orbit: {
                  ox: F.x, oy: F.y - 16, r0: 100 + rng() * 60, r1: 10,
                  a0: rng() * Math.PI * 2,
                  spin: (rng() < 0.5 ? -1 : 1) * (2.4 + rng() * 1.6),
                  squash: GROUND_SQUASH,
                },
              });
            }
          }
          // ---- 发射：炮口火花 ----------------------------------------------
          ctx.once(inst, "launch", T.launch, () => {
            for (let i = 0; i < 10; i++) {
              const a = inst.aim + (rng() - 0.5) * 0.9;
              const sp = 260 + rng() * 260;
              ctx.particles.emit({
                x: F.x, y: F.y - 16,
                vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
                drag: 3.2, life: 140 + rng() * 120,
                s0: 30 + rng() * 30, s1: 8, sExp: 1.5, stretch: 3.0,
                c0: [1.0, 0.95, 0.76], c1: [1.0, 0.5, 0.12],
                a0: 1, a1: 0, alignVel: true,
                mode: M.SOFT, p0: [M.SOFT, 1.25, 0, 0],
              });
            }
          });
        }

        // ---- 飞行：从彗尾甩出的余烬火花 + 沿途极小的烟团（路径层）-------------
        ctx.path(inst);
        if (t >= T.launch && t < T.impact) {
          const u = (t - T.launch) / T.flight;
          const p = flightPos(inst, u);
          const bx = -Math.cos(inst.aim);
          const by = -Math.sin(inst.aim);
          const traveled = flightU(u) * Math.hypot(To.x - F.x, To.y - F.y);
          inst.emberAcc += dt;
          while (inst.emberAcc >= 9) {
            inst.emberAcc -= 9;
            // 余烬只从已经飞过的那一段里甩出来，不会落到施法者身后
            const back = Math.min(traveled, (30 + rng() * 120) * P);
            const side = (rng() - 0.5) * 26 * P;
            ctx.particles.emit({
              x: p.x + bx * back - by * side, y: p.y + by * back + bx * side,
              vx: (bx * (120 + rng() * 160) + (rng() - 0.5) * 90) * P,
              vy: (by * (120 + rng() * 160) - 30 - rng() * 50) * P,
              drag: 2.2, life: 200 + rng() * 220,
              s0: (9 + rng() * 9) * P, s1: 2, sExp: 1.35,
              c0: [1.0, 0.72, 0.22], c1: [0.72, 0.14, 0.03],
              a0: 0.95, a1: 0, mode: M.SOFT, p0: [M.SOFT, 1.7, 0, 0],
            });
          }
          inst.smokeAcc += dt;
          while (inst.smokeAcc >= 70) {
            inst.smokeAcc -= 70;
            const back = Math.min(traveled, 90 * P);
            ctx.particles.emit({
              x: p.x + bx * back + (rng() - 0.5) * 14 * P, y: p.y + by * back + (rng() - 0.5) * 14 * P,
              vx: (bx * 20 + (rng() - 0.5) * 30) * P, vy: (by * 20 - 40 - rng() * 40) * P,
              drag: 1.2, life: 380 + rng() * 240,
              s0: 34 * P, s1: 96 * P, sExp: 0.6,
              c0: [0.55, 0.50, 0.52], c1: [0.20, 0.18, 0.20],
              a0: 0.26, a1: 0, aExp: 1.1, fadeIn: 0.25,
              rot: rng() * 6.28, rotVel: (rng() - 0.5) * 0.9,
              bucket: "smoke", mode: M.DISSOLVE,
              p0: [M.DISSOLVE, 0.20, 0.42, G.EMBER],
              p1: [1.5, 0, -1, 0.08],
            });
          }
        }

        // ---- 命中（接触层）--------------------------------------------------
        ctx.contact(inst);
        ctx.once(inst, "boom", T.impact, () => {
          const sparks = 24;
          for (let i = 0; i < sparks; i++) {
            const a = (i / sparks) * Math.PI * 2 + rng() * 0.3;
            const sp = 240 + rng() * 320;
            ctx.particles.emit({
              x: To.x, y: To.y,
              vx: Math.cos(a) * sp, vy: Math.sin(a) * sp * 0.7 - 60,
              gy: 900, drag: 3.4, life: 200 + rng() * 160,
              s0: 34 + rng() * 30, s1: 10, sExp: 1.5, stretch: 3.0,
              c0: [1.0, 0.95, 0.76], c1: [1.0, 0.44, 0.10],
              a0: 1, a1: 0, fadeIn: 0.02, alignVel: true, core: 0.4,
              mode: M.SOFT, p0: [M.SOFT, 1.25, 0, 0],
            });
          }
          for (let i = 0; i < 10; i++) {
            const a = rng() * Math.PI * 2;
            const sp = 120 + rng() * 200;
            ctx.particles.emit({
              x: To.x, y: To.y,
              vx: Math.cos(a) * sp, vy: Math.sin(a) * sp * 0.66 - 100,
              gy: 700, drag: 1.9, life: 300 + rng() * 200,
              s0: 26 + rng() * 22, s1: 10, sExp: 1.2,
              c0: [1, 1, 1], c1: [1, 1, 1], a0: 0.95, a1: 0,
              rot: rng() * 6.28, rotVel: (rng() - 0.5) * 5,
              mode: M.SHAPE,
              p0: [M.SHAPE, (i % 4), 0.12, G.FIRE],
              p1: [0.05, 0, 0.52, 0],
            });
          }
          for (let i = 0; i < 14; i++) {
            const a = rng() * Math.PI * 2;
            const sp = 50 + rng() * 150;
            ctx.particles.emit({
              x: To.x + Math.cos(a) * 26, y: To.y + Math.sin(a) * 18,
              vx: Math.cos(a) * sp, vy: Math.sin(a) * sp * 0.6 - 90,
              gy: 240, drag: 1.6, life: 300 + rng() * 200,
              s0: 11 + rng() * 10, s1: 3, sExp: 1.3,
              c0: [1.0, 0.66, 0.24], c1: [0.62, 0.10, 0.02],
              a0: 1, a1: 0, mode: M.SOFT, p0: [M.SOFT, 1.8, 0, 0],
            });
          }
        });

        // ---- 余韵：三团小卷烟 ----------------------------------------------
        if (t >= T.impact + 40 && t < T.impact + 200) {
          inst.smokeAcc += dt;
          while (inst.smokeAcc >= 60) {
            inst.smokeAcc -= 60;
            const a = rng() * Math.PI * 2;
            ctx.particles.emit({
              x: To.x + Math.cos(a) * (16 + rng() * 40),
              y: To.y + Math.sin(a) * (10 + rng() * 26),
              vx: Math.cos(a) * 30, vy: -80 - rng() * 60,
              drag: 1.0, life: 420 + rng() * 200,
              s0: 80, s1: 150, sExp: 0.6,
              c0: [0.62, 0.58, 0.60], c1: [0.20, 0.18, 0.20],
              a0: 0.5, a1: 0, aExp: 1.1, fadeIn: 0.22,
              rot: rng() * 6.28, rotVel: (rng() - 0.5) * 0.8,
              bucket: "smoke", mode: M.DISSOLVE,
              p0: [M.DISSOLVE, 0.20, 0.42, G.EMBER],
              p1: [1.5, 0, -1, 0.08],
            });
          }
        }
      },

      draw(inst, ctx) {
        const t = inst.t;
        const F = inst.from;
        const To = inst.to;
        const sec = t / 1000;
        const aim = inst.aim;
        const P = inst.kp;

        // ================= 预兆：手中凝聚（施法者层）============================
        if (t < T.launch + 70 && ctx.caster(inst)) {
          if (t < T.launch) {
            const u = clamp(t / T.antic, 0, 1);
            ctx.soft(F.x, F.y + 20, 150 + 90 * u, [1.0, 0.30, 0.05], 0.18 + 0.26 * u, {
              bucket: "ground", squash: GROUND_SQUASH, falloff: 2.7,
            });
            const thr = lerp(0.95, 0.20, easeOut(u));
            const size = 150 * (0.5 + 0.5 * easeOut(u));
            ctx.dissolve({
              x: F.x + 6, y: F.y - 62,
              w: size * 0.8, h: size,
              rot: Math.sin(sec * 2.4) * 0.12,
              cell: 0, threshold: thr, soft: 0.04,
              grad: G.FIRE, noiseScale: 1.9, seconds: sec, flow: 0.08, alpha: 0.95,
            });
            if (t > 60) {
              const k = clamp((t - 60) / (T.antic - 60), 0, 1);
              const cs = 26 + 62 * easeOut(k);
              ctx.dissolve({
                x: F.x, y: F.y - 16, w: cs, h: cs,
                cell: -1, threshold: lerp(0.5, 0.10, k), soft: 0.05,
                grad: G.FIRE, noiseScale: 2.6, seconds: sec * 1.5, flow: 0.10, alpha: 1,
              });
              ctx.soft(F.x, F.y - 16, cs * 2.2, [1.0, 0.50, 0.12], 0.22 + 0.26 * k, { falloff: 2.6 });
              ctx.soft(F.x, F.y - 16, cs * 0.7, [1.0, 0.96, 0.82], 0.5 + 0.5 * k, { falloff: 1.6 });
              ctx.distort({ x: F.x, y: F.y - 16, w: cs * 3.0, kind: 1, strength: 0.24 * k, seconds: sec });
            }
          }
          // ---- 发射：炮口闪光 ------------------------------------------------
          const km = (t - T.launch) / 70;
          if (km >= 0 && km <= 1) {
            const fade = Math.pow(1 - km, 1.6);
            ctx.soft(F.x, F.y - 16, 90 + 100 * easeOut(km), [1, 0.9, 0.7], 0.8 * fade, { falloff: 1.8 });
            ctx.polar({
              x: F.x, y: F.y - 16, w: 140 + 120 * easeOut(km),
              radius: -1, rays: 7, raySharp: 6.0, rotate: aim,
              grad: G.FIRE, col: [1, 0.85, 0.55], alpha: 0.7 * fade,
            });
          }
        }

        // ================= 飞行：彗星配方（路径层）==============================
        // 头小而极亮、沿速度拉伸；尾是锥形彗尾，噪声沿长度向后流；两条绕轴螺旋
        // 火焰带给体积。宽度按 kp（两张卡里较小那张）收窄。
        if (t >= T.launch && t < T.impact && ctx.path(inst)) {
          const u = (t - T.launch) / T.flight;
          const p = flightPos(inst, u);
          const cosA = Math.cos(aim);
          const sinA = Math.sin(aim);
          const nrmX = -sinA;
          const nrmY = cosA;
          const fu = flightU(u);
          const TAIL = 360 * P;
          const N = 18;

          ctx.soft(p.x, p.y + 60 * P, 230 * P, [1.0, 0.30, 0.05], 0.14, {
            bucket: "ground", squash: GROUND_SQUASH, falloff: 2.6,
          });

          const axis = cometPath(inst, u, TAIL, N);
          const tail = axis.map((q, i) => {
            const s = i / (N - 1);
            return { x: q.x, y: q.y, hw: (6 + 30 * Math.pow(s, 0.7)) * P };
          });
          ctx.trail(tail, { grad: G.FIRE, headBias: 1.15, edgeSoft: 0.55, noise: 0.6, seconds: -sec * 2.6, alpha: 0.95, comet: true });
          const core = axis.map((q, i) => {
            const s = i / (N - 1);
            return { x: q.x, y: q.y, hw: (2 + 11 * Math.pow(s, 0.8)) * P };
          });
          ctx.trail(core, { grad: G.FIRE, headBias: 2.2, edgeSoft: 0.9, noise: 0.35, seconds: -sec * 3.4, alpha: 0.95, comet: true });

          for (let k = 0; k < 2; k++) {
            const phase0 = k * Math.PI + sec * 18.0;
            const helix = axis.map((q, i) => {
              const s = i / (N - 1);
              const r = 30 * P * Math.pow(1 - s, 0.8) * (0.5 + 0.5 * fu);
              const off = Math.sin(phase0 + (1 - s) * 7.5) * r;
              return { x: q.x + nrmX * off, y: q.y + nrmY * off, hw: (3 + 8 * s) * P };
            });
            ctx.trail(helix, { grad: G.FIRE, headBias: 1.6, edgeSoft: 0.8, noise: 0.3, seconds: -sec * 2.0 + k, alpha: 0.85, comet: true });
          }

          ctx.soft(p.x, p.y, 170 * P, [1.0, 0.45, 0.10], 0.5, { falloff: 2.6 });
          ctx.dissolve({
            x: p.x - cosA * 8 * P, y: p.y - sinA * 8 * P, w: 96 * P, h: 62 * P,
            rot: aim, cell: -1, threshold: 0.06, soft: 0.03,
            grad: G.FIRE, gamma: 0.45, hdr: 1.8,
            noiseScale: 3.2, seconds: sec * 2.2, flow: 0.18, alpha: 1,
          });
          ctx.soft(p.x + cosA * 8 * P, p.y + sinA * 8 * P, 40 * P, [1, 1, 0.94], 0.95, { falloff: 1.5 });
          ctx.distort({ x: p.x - cosA * 40 * P, y: p.y - sinA * 40 * P, w: 220 * P, kind: 1, strength: 0.5, seconds: sec });
        }

        // ================= 爆发（接触层）========================================
        if (t >= T.impact && ctx.contact(inst)) {
          const dt2 = t - T.impact;

          // 一道冲击环：细、脆、贴地
          const kr = dt2 / 220;
          if (kr <= 1) {
            const size = 120 + 280 * easeOutQuint(kr);
            const fade = Math.pow(1 - kr, 1.6);
            ctx.polar({
              x: To.x, y: To.y, w: size, squash: GROUND_SQUASH,
              radius: 0.76, width: 0.028 + 0.016 * kr, break: 0.30 + 0.30 * kr,
              rotate: 0.05 * kr, grad: G.FIRE,
              col: [1, 0.66, 0.24], alpha: fade, core: 0.4,
            });
            ctx.distort({
              x: To.x, y: To.y, w: size * 1.05, squash: GROUND_SQUASH,
              kind: 0, strength: 0.8 * fade, ringRadius: 0.76, ringWidth: 0.10,
            });
          }
          // 少量短放射线
          const kray = dt2 / 150;
          if (kray <= 1) {
            ctx.polar({
              x: To.x, y: To.y, w: 200 + 220 * easeOut(kray),
              radius: -1, rays: 9, raySharp: 6.5, rotate: 0.3 + 0.02 * kray,
              grad: G.FIRE, col: [1, 0.82, 0.52], alpha: Math.pow(1 - kray, 2.2) * 0.7, core: 0.25,
            });
          }
          // 三层硬边火焰，长出再溶解
          const EXPLO_BASE = 250;
          const LAYER_SCALE = [0.62, 0.9, 1.2];
          const LAYER_CELL = [1, 3, 2];
          const LAYER_FLIP = [0, 3, 1];
          const LAYER_QUARTER = [0, 1, 0];
          const LAYER_START = [0, 0.04, 0.09];
          const kb = dt2 / 300;
          if (kb <= 1) {
            for (let i = 0; i < 3; i++) {
              const li = i / 2;
              const kl = clamp((kb - LAYER_START[i]) / (1 - LAYER_START[i]), 0, 1);
              if (kl <= 0) continue;
              const grow = easeOutQuint(clamp(kl * 3.4, 0, 1));
              const size = EXPLO_BASE * LAYER_SCALE[i] * (0.3 + 0.7 * grow);
              const a = (i * 2.1 + inst.seed * 0.0013) % 6.28;
              const spread = 26 * li * grow;
              const quarter = LAYER_QUARTER[i] * (Math.PI / 2);
              const swap = LAYER_QUARTER[i] === 1;
              ctx.dissolve({
                bucket: "body",
                x: To.x + Math.cos(a) * spread,
                y: To.y + Math.sin(a) * spread * 0.7 - 12 * li * grow,
                w: swap ? size : size * 1.1,
                h: swap ? size * 1.1 : size,
                rot: quarter + a * 0.3 + kl * 0.22 * (i % 2 ? 1 : -1),
                cell: LAYER_CELL[i], flip: LAYER_FLIP[i],
                threshold: lerp(0.03, 1.0, Math.pow(kl, 0.80 + li * 0.2)),
                soft: 0.012 + 0.008 * li,
                // 火焰本体保持不透明的轮廓，只把最热那一段的推高降下来（卡面中央不打白）
                grad: G.FIRE, gamma: 1.3, steps: 4, hdr: 1.0,
                noiseScale: 1.4 + li * 1.5,
                seconds: sec * (1.2 + li * 0.5) + i * 4.7,
                flow: 0.09 + 0.06 * li,
                alpha: 1,
              });
            }
          }
          // 白热核心：4 帧
          const kcore = dt2 / 50;
          if (kcore <= 1) {
            const cs = 48 + 36 * easeOutQuint(clamp(kcore * 2.8, 0, 1));
            ctx.dissolve({
              bucket: "body",
              x: To.x, y: To.y, w: cs * 1.08, h: cs,
              rot: kcore * 0.5, cell: -1,
              threshold: lerp(0.02, 0.92, Math.pow(kcore, 1.5)),
              soft: 0.0, grad: G.FIRE, gamma: 0.30, steps: 2, hdr: 2.6,
              col: [1.0, 0.97, 0.88],
              noiseScale: 2.2, seconds: sec * 2.0, flow: 0.16, alpha: 1, core: 0.2,
            });
          }
          const kh = dt2 / 240;
          if (kh <= 1) {
            ctx.soft(To.x, To.y, 240 + 160 * easeOut(kh), [1, 0.40, 0.10], Math.pow(1 - kh, 1.6) * 0.16, { falloff: 2.8, core: 0.3 });
            ctx.distort({ x: To.x, y: To.y, w: 400, kind: 1, strength: 0.9 * Math.pow(1 - kh, 1.2), seconds: sec });
          }

          // 地面余烬暖光，快速收
          const ke = clamp(dt2 / T.release, 0, 1);
          if (ke < 1) {
            const fade = dt2 < 80 ? dt2 / 80 : Math.pow(1 - (dt2 - 80) / (T.release - 80), 1.4);
            ctx.soft(To.x, To.y + 10, 260, [1.0, 0.34, 0.07], 0.40 * clamp(fade, 0, 1), {
              bucket: "ground", squash: GROUND_SQUASH, falloff: 2.4,
            });
          }
        }
      },
    };
  }


  // ============================================================ 闪电
  require_lightning();


  // 第 13 轮：boltPath()（中点位移折线）与 widen()（给折线套恒定半宽）一起
  // 删掉了 —— 它们只有闪电的主雷/分叉/地面电弧三处用户，那三处现在走
  // lightning-strike 序列帧，仓库里再没有"算出来的折线"这种形状语言。

  function require_lightning() {
    // V2（2026-09-17）：闪电不再"从天而降"。
    //   蓄力 0 → 240     施法者卡上方一小团电（caster 层，electric-impact 前 6 帧循环）
    //   电弧 240 → 380   lightning-flipbook 的 16 条路径变体，从施法者卡心伸到目标卡心
    //                    （path 层；每 2 帧换一条路径，两层错开变体号）
    //   接触 380         lightning-strike 序列帧**顺着电弧方向**打在目标上，只作接触点；
    //                    electric-impact 16 帧 + 放射电火花（contact 层）
    // 删掉：竖直落雷、落点地面长残光（420ms）、上升电火花的长尾、切入、震屏、顿帧、推镜、闪帧。
    const T = { antic: 240, link: 140, impact: 380, release: 300 };
    const STRIKE_MS = 300;      // lightning-strike 16 帧
    const STRIKE_H = 260;       // 接触点的落雷长度（自然尺寸，接触层再按目标卡缩放）
    const ORB_D = 210;          // 蓄力：手上那团电
    const ORB_LIFT = 0.25;      // 电球浮在施法者卡心上方（施法者卡高的比例）
    const HIT_MS = 300;         // electric-impact
    const HIT_D = 320;
    const ARC_TAIL = 90;        // 电弧接触后再挂多久
    const VARIANTS = 16;

    SKILLS.lightning = {
      label: "闪电",
      nat: { launch: T.antic, impact: T.impact, end: T.impact + T.release },
      extent: 375,
      castExtent: 220,

      post: {
        bloom1: [
          { t: 0, v: 0.30 }, { t: T.antic - 60, v: 0.40 },
          { t: T.impact + 6, v: 0.56 }, { t: T.impact + 90, v: 0.30 },
        ],
        bloom2: [
          { t: 0, v: 0.14 }, { t: T.impact + 6, v: 0.16 },
          { t: T.impact + 70, v: 0.14 },
        ],
        distort: [
          { t: 0, v: 0 }, { t: T.impact - 10, v: 4 },
          { t: T.impact + 4, v: 22 }, { t: T.impact + 160, v: 8 },
          { t: T.impact + T.release, v: 0 },
        ],
      },

      init(inst) {
        inst.aim = Math.atan2(inst.to.y - inst.from.y, inst.to.x - inst.from.x);
        inst.emitAcc = 0;
        inst.hitRot = inst.rng() * Math.PI * 2;
      },

      update(inst, ctx, dt) {
        const t = inst.t;
        const rng = inst.rng;
        const To = inst.to;

        ctx.contact(inst);
        ctx.once(inst, "boom", T.impact, () => {
          for (let i = 0; i < 18; i++) {
            const a = (i / 18) * Math.PI * 2 + rng() * 0.28;
            const sp = 260 + rng() * 320;
            ctx.particles.emit({
              x: To.x, y: To.y,
              vx: Math.cos(a) * sp, vy: Math.sin(a) * sp * 0.62 - 90,
              gy: 1000, drag: 3.4, life: 180 + rng() * 140,
              s0: 18 + rng() * 16, s1: 5, sExp: 1.5, stretch: 5.0,
              c0: [0.92, 0.98, 1.0],
              c1: inst.tint || [0.28, 0.56, 1.0],
              a0: 1, a1: 0, fadeIn: 0.02, alignVel: true,
              mode: M.SOFT, p0: [M.SOFT, 3.2, 0, 0],
            });
          }
        });

        // 余韵：少量竖直上升的电火花（只在接触后 200ms 内发）
        if (t >= T.impact + 30 && t < T.impact + 200) {
          inst.emitAcc += dt;
          while (inst.emitAcc >= 24) {
            inst.emitAcc -= 24;
            const a = rng() * Math.PI * 2;
            const r = 20 + rng() * 90;
            ctx.particles.emit({
              x: To.x + Math.cos(a) * r, y: To.y + Math.sin(a) * r * GROUND_SQUASH,
              vx: (rng() - 0.5) * 40, vy: -120 - rng() * 140,
              gy: 90, drag: 1.4, life: 220 + rng() * 160,
              s0: 20 + rng() * 14, s1: 4, sExp: 1.3, stretch: 2.6,
              c0: [0.86, 0.95, 1.0],
              c1: inst.tint || [0.20, 0.44, 0.96],
              a0: 0.95, a1: 0, alignVel: true,
              mode: M.SOFT, p0: [M.SOFT, 1.7, 0, 0],
            });
          }
        }
      },

      draw(inst, ctx) {
        const TINT = inst.tint || [0.72, 0.86, 1.0];
        const SAT = saturate(TINT, 1.3);
        const HOT = wash(SAT, 0.5);
        const GRAD = inst.tintGrad == null ? G.LIGHTNING : inst.tintGrad;
        const F = inst.from;
        const To = inst.to;
        const t = inst.t;
        const sec = t / 1000;
        const aim = inst.aim;
        const dist = Math.hypot(To.x - F.x, To.y - F.y);
        const dt2 = t - T.impact;

        // ---- 蓄力：施法者卡上方一小团电（caster 层）-------------------------
        if (t < T.antic + 60 && ctx.caster(inst)) {
          const a = Math.min(1, t / 70) *
            Math.pow(clamp(1 - (t - (T.antic - 40)) / 100, 0, 1), 1.0);
          if (a > 0.02) {
            const d = ORB_D * (0.5 + 0.5 * clamp(t / T.antic, 0, 1));
            ctx.flipbook({
              cell: "electricFb", x: F.x, y: F.y - ORB_LIFT * inst.fromBox.h,
              w: d, h: d, rot: sec * 1.3,
              frame: (t % 180) / 180 * 6,
              grad: GRAD, gradLo: 0.06, alpha: a, hdr: 1.6,
              uvDistort: 0.02, seconds: sec, bucket: "add",
            });
          }
        }

        // ---- 电弧：施法者 → 目标（path 层）----------------------------------
        // lightning-flipbook 的每一帧是左上 → 右下的对角线：边长 L/√2 的正方形
        // 旋转 aim − 45° 后，对角线正好落在 from→to 上、长度正好是 L。
        if (t >= T.antic && t <= T.impact + ARC_TAIL && dist > 1 && ctx.path(inst)) {
          const front = easeOut(clamp((t - T.antic) / T.link, 0, 1));
          const after = clamp((t - T.impact) / ARC_TAIL, 0, 1);
          const frame = Math.floor(t / FIXED_DT);
          const jitter = 0.72 + 0.28 * Math.abs(Math.sin(frame * 2.399 + inst.seed));
          const step = Math.floor(frame / 2);
          const L = dist * front;
          const mx = F.x + Math.cos(aim) * L * 0.5;
          const my = F.y + Math.sin(aim) * L * 0.5;
          const a2 = jitter * Math.pow(1 - after, 1.3);
          ctx.mark(F.x, F.y, F.x + Math.cos(aim) * L, F.y + Math.sin(aim) * L);
          for (let i = 0; i < 2; i++) {
            const v = Math.floor(
              Math.abs(Math.sin(step * 12.9898 + inst.seed * 0.137 + i * 3.1)) *
              VARIANTS) % VARIANTS;
            ctx.flipbook({
              // 四边形压成 cos φ : sin φ 的长方形：对角线仍是 from→头部、长度仍是 L，
              // 但电弧的横向摆幅只剩 tan φ ≈ 0.55 倍（正方形时电弧能甩出路径两侧几百像素）
              cell: "lightningFb", x: mx, y: my, w: L * ARC_COS, h: L * ARC_SIN,
              rot: aim - ARC_PHI,
              frame: v, lerp: false,
              grad: GRAD, gradLo: 0.08,
              alpha: a2 * (i ? 0.7 : 1), hdr: 1.7,
              uvDistort: 0.02, seconds: sec, bucket: "add",
            });
          }
          // 电弧头：一点冷白，让"电走到哪了"读得出来
          if (after <= 0) {
            ctx.soft(F.x + Math.cos(aim) * L, F.y + Math.sin(aim) * L,
              70 * inst.kp, HOT, 0.8 * jitter, { falloff: 3.2 });
          }
        }

        if (dt2 < 0) return;
        ctx.contact(inst);

        // ---- 接触点：lightning-strike 顺着电弧方向打进目标 -------------------
        const ku = dt2 / STRIKE_MS;
        if (ku < 1) {
          ctx.flipbook({
            cell: "lightningStrike", x: To.x, y: To.y,
            w: STRIKE_H, h: STRIKE_H, ay: 0.72,
            // 素材里雷是竖直朝下的（+y），转到 aim 方向
            rot: aim - Math.PI / 2,
            frame: ku * 16, grad: GRAD, gradLo: 0.05,
            alpha: ku < 0.6 ? 1 : Math.pow(1 - (ku - 0.6) / 0.4, 1.3),
            hdr: 1.8, uvDistort: 0.012, seconds: sec, bucket: "add", core: 0.6,
          });
        }

        // ---- 命中：electric-impact 16 帧 -----------------------------------
        strikeImpact(ctx, To.x, To.y, dt2, {
          cell: "electricFb", ms: HIT_MS, d: HIT_D,
          grad: GRAD, col: HOT, rot: inst.hitRot,
          hdr: 1.7, uvDistort: 0.015, seconds: sec,
        });

        const kg = dt2 / T.release;
        if (kg <= 1)
          ctx.soft(To.x, To.y + 20, 200, SAT,
            Math.pow(1 - kg, 1.7) * 0.3, {
              bucket: "ground", squash: GROUND_SQUASH, falloff: 3.0,
            });
      },
    };
  }

  // ============================================================ 剑劈
  // 接入版：剑风整体缩到原型的 70%（弧半径、曲率中心、刃宽同比）。必须声明在
  // require_slash() 之前 —— 它在函数体里就要用到（const 的 TDZ）。
  const SLASH_SCALE = 0.7;

  // ======================================================== 平砍六族的共用件
  //
  // 第 9 轮：slash / claw / arrow / spear / bolt / breath 六族照 slam 的模板改成
  // **贴图驱动**（assets/fx2/atlas-strike.webp）。矢量原语画的主体（拖尾三层、
  // 弧、束、锥）全部删掉，只留下"喂 bloom 的火花"和演出轨道。
  //
  // 素材的方向约定：所有条状贴图都是**左 = 攻击者端、右 = 目标端**，运行时用
  // rot = aim（from→to 的角度）旋转，锚点 ax 传 0 就把左端钉在攻击者身上。
  // 打包时每张都裁到自己的内容 bbox（见 tools/fx2_atlas.py），所以"左端"就是
  // 素材真正开始的地方，不用在配方里猜一个偏移量。
  // lightning-flipbook 的每一帧是左上 → 右下的对角线电弧。画成 cos φ × sin φ 的长方形、
  // 旋转 aim − φ，对角线正好落在 from→to 上（闪电电弧与魔法弹电束共用）。
  const ARC_PHI = 0.5;
  const ARC_COS = Math.cos(ARC_PHI);
  const ARC_SIN = Math.sin(ARC_PHI);
  const STRIKE_CARD_W = 116;   // 卡宽（爪痕这类"贴在卡面上"的元素按它定尺寸）

  // ---- 第 12 轮：七族共用的"命中"与"烟尘"（序列帧版）------------------------
  //
  // 旧版的命中是**一张 flashWhite 星芒在缩放**：形状恒定、只有大小和 alpha 在
  // 变，慢放就是一张贴纸在放大。现在换成 impact-flipbook 的 16 帧（4×4 网格）
  // 按 260ms 播完、相邻帧插值 —— 芒刺是一帧比一帧长出来的。flashWhite 只留
  // 最前面两帧当"接触白闪"，不再负责整段命中。
  const IMPACT_MS = 260;   // 16 帧 / 260ms ≈ 61fps，正好一帧一格
  const IMPACT_D = 320;    // 序列帧命中的基准直径

  /**
   * 七族共用的命中序列帧。
   *
   *   dt    距命中时刻的毫秒数（<0 或 ≥ms 时什么都不画）
   *   o.cell   默认 "impactFb"；电系传 "electricFb"，斩击传 "slashArcFb"
   *   o.mul    直径倍率（各族按力度给）
   *   o.grad   渐变表行号；给了就走**渐变映射**（色相完全由这一行决定，
   *            col 恒为白）—— 这就是"学派换色靠换 row"。没给就退回老办法：
   *            灰度贴图 × col。接入层没配 tintGrad 的族（银白剑风）走这一支。
   *   o.col    没有 grad 时的染色
   */
  function strikeImpact(ctx, x, y, dt, o) {
    const ms = o.ms || IMPACT_MS;
    if (dt < 0 || dt >= ms) return;
    const u = dt / ms;
    const d = (o.mul == null ? 1 : o.mul) * (o.d || IMPACT_D);
    ctx.flipbook({
      cell: o.cell || "impactFb", x, y, w: d, h: d, rot: o.rot || 0,
      squash: o.squash,
      // 帧号走满整条序列；末尾那一帧本身就已经淡到几乎没有，所以 alpha
      // 只在最后 25% 收一把尾，不用整段压。
      frame: u * 16,
      grad: o.grad, gradLo: o.gradLo == null ? 0.08 : o.gradLo,
      col: o.grad == null ? o.col : null,
      alpha: (o.alpha == null ? 1 : o.alpha) *
        (u < 0.75 ? 1 : Math.pow(1 - (u - 0.75) / 0.25, 1.4)),
      hdr: o.hdr == null ? 1.4 : o.hdr,
      uvDistort: o.uvDistort || 0,
      seconds: o.seconds || 0,
      bucket: "add",
      core: o.core == null ? true : o.core,
    });
  }

  /**
   * 攻击者 → 目标的**弧线**路径，给 Ribbon 用。
   *
   *   u0 / u1  取这条弧的哪一段（0 = 攻击者端、1 = 目标端）；带的尾在 u0、
   *            头在 u1，所以"甩过去"就是 u1 从 0 涨到 1、u0 跟在后面
   *   bow      垂直于 from→to 的弓高（px），正负决定往哪边弯
   *   hw(u)    半宽函数（沿长度的宽度曲线）
   *
   * 二次贝塞尔，不是圆弧：控制点就一个（中点外推 bow），弧度随距离自动缩放，
   * 随从贴脸打（180px）和英雄打对面（790px）用同一组参数都不会弯过头。
   */
  function bowPath(from, to, u0, u1, n, bow, hw) {
    const mx = (from.x + to.x) * 0.5;
    const my = (from.y + to.y) * 0.5;
    const dx = to.x - from.x;
    const dy = to.y - from.y;
    const len = Math.hypot(dx, dy) || 1;
    const cx = mx - (dy / len) * bow;
    const cy = my + (dx / len) * bow;
    const pts = new Array(n);
    for (let i = 0; i < n; i++) {
      const u = lerp(u0, u1, n === 1 ? 0 : i / (n - 1));
      const v = 1 - u;
      pts[i] = {
        x: v * v * from.x + 2 * v * u * cx + u * u * to.x,
        y: v * v * from.y + 2 * v * u * cy + u * u * to.y,
        hw: hw(i / Math.max(1, n - 1), u),
      };
    }
    return pts;
  }

  /**
   * 条状素材的横向厚度。相邻两张随从卡只隔 180px，而英雄打到对面随从要跨
   * 790px —— 固定厚度在前者身上会画出一条比自己还胖的带子（量出来 h 190 /
   * w 180，读成一团，根本不是"甩过去的一道光"）。按交战距离压一档，远距离
   * 仍然拿到设计厚度。
   */
  function strikeBandH(base, dist) {
    return Math.min(base, dist * 0.85);
  }

  /**
   * 命中处沿攻击方向的单向冲击折射（kind 2）。六族同一档，强度由各族给：
   * 贯穿类（投枪）比划开类（剑劈/抓击）强一档。
   */
  function strikeDistort(ctx, x, y, aim, w, strength) {
    ctx.distort({
      x, y, w, kind: 2, strength,
      dirX: Math.cos(aim), dirY: Math.sin(aim),
    });
  }

  require_slash();

  /**
   * 刀光圆弧的几何（沿用第一代的推导）：曲率中心落在目标点**朝施法者**一侧
   * SLASH_CENTER_D 处，半径 SLASH_R，弧张角 ±SLASH_HALF。这样弧的凹面正对
   * 施法者、弦与攻击方向垂直 —— 任意目标点都读得出"这一刀是从施法者那边
   * 劈过来的"。第一代是为了和序列帧素材对齐才这么算，这里没有素材，
   * 只保留这套几何关系。
   */
  // 第 11 轮：弧半径 196 → 290（刀气弧半径 260~320 才有"一刀劈开半个场"的尺度），
  // 曲率中心同步外推到 264，保证弧的顶点仍然落在目标点外侧 26px。
  const SLASH_R = 290 * SLASH_SCALE;          // 203
  const SLASH_CENTER_D = 264 * SLASH_SCALE;   // 184.8
  const SLASH_HALF = 0.82; // ±47°，弦半长 ≈ 148px

  function slashArc(inst, t0, t1, n, radius, squashY) {
    // inst.scale：随从平砍用 0.6 的轻量剑风，弧半径与曲率中心一起缩，
    // 弧相对目标点的位置关系（凹面朝施法者、顶点在目标外侧）保持不变。
    const k = inst.scale || 1;
    const back = inst.aim + Math.PI;
    const cx = inst.to.x + Math.cos(back) * SLASH_CENTER_D * k;
    const cy = inst.to.y + Math.sin(back) * SLASH_CENTER_D * k;
    const R = (radius == null ? SLASH_R : radius) * k;
    const pts = new Array(n);
    for (let i = 0; i < n; i++) {
      const u = n === 1 ? t0 : lerp(t0, t1, i / (n - 1));
      const a = inst.aim + lerp(-SLASH_HALF, SLASH_HALF, u);
      const x = cx + Math.cos(a) * R;
      let y = cy + Math.sin(a) * R;
      if (squashY) y = inst.to.y + (y - inst.to.y) * GROUND_SQUASH;
      pts[i] = { x, y };
    }
    return pts;
  }

  function require_slash() {
    // 第 10–12 轮定下的剑劈：拔刀光带（Ribbon，从攻击者甩向目标）→ 新月刀光序列帧
    // 劈在目标上 → 金属火花背离攻击者扇开。
    //
    // V2（2026-09-17）：
    //   · 平砍（近战）由卡片冲撞讲故事：导演层在碰撞那一刻调 attack，时间映射直接
    //     从 impact 开始，拔刀光带只在"剑劈作为法术"（sabotage / 钢铁英雄技能）时出现。
    //   · 删掉：卡面刀痕残留（200ms 的 body 桶新月）、命中白闪星（整卡打白）、
    //     切入、顿帧、震屏、推镜、闪帧。
    const T = { draw: 40, impact: 180, release: 300 };
    const DRAW_H = 300;     // 光带贴图的横向厚度（slash-draw2 内容占其中 26%）
    const ARC_FB_MS = 300;  // 新月序列帧播完的时长（16 帧）
    const ARC_MS = 120;     // 新月张开：0.7 → 1.15 倍
    const ARC_HOLD = 84;    // 满不透明的那一拍
    const ARC_OUT = 300;    // 从命中算起到彻底消失
    const ARC_D = 260 * 1.15;
    const SPARK_MS = 154;   // 扇形火花
    const SPARK_D = 200;

    SKILLS.slash = {
      label: "剑劈",
      nat: { launch: T.draw, impact: T.impact, end: T.impact + T.release },
      extent: 350,
      castExtent: 160,

      post: {
        bloom1: [
          { t: 0, v: 0.30 }, { t: T.impact - 10, v: 0.36 },
          { t: T.impact + 6, v: 0.52 }, { t: T.impact + 130, v: 0.40 },
          { t: T.impact + T.release, v: 0.30 },
        ],
        bloom2: [
          { t: 0, v: 0.14 }, { t: T.impact + 6, v: 0.15 },
          { t: T.impact + 160, v: 0.14 },
        ],
        distort: [
          { t: 0, v: 0 }, { t: T.impact - 10, v: 6 },
          { t: T.impact + 4, v: 20 }, { t: T.impact + 150, v: 7 },
          { t: T.impact + T.release, v: 0 },
        ],
      },

      init(inst) {
        inst.aim = Math.atan2(inst.to.y - inst.from.y, inst.to.x - inst.from.x);
        // 贴图版的随机相位在 init 里定死，debugSeek 定格才可复现
        inst.arcRot = (inst.rng() - 0.5) * 0.7; // ±0.35
      },

      update(inst, ctx) {
        const rng = inst.rng;
        ctx.contact(inst);
        ctx.once(inst, "hit", T.impact, () => {
          // 6 条细亮线沿弧的中段朝外甩（位置、角度、长度都随机）
          for (let i = 0; i < 6; i++) {
            const u = 0.14 + rng() * 0.72;
            const p = slashArc(inst, u, u, 1)[0];
            const a = inst.aim + lerp(-SLASH_HALF, SLASH_HALF, u) + (rng() - 0.5) * 0.5;
            const sp = 260 + rng() * 360;
            ctx.particles.emit({
              x: p.x + (rng() - 0.5) * 20, y: p.y + (rng() - 0.5) * 16,
              vx: Math.cos(a) * sp, vy: Math.sin(a) * sp * 0.72 - 60,
              gy: 820, drag: 3.6 + rng() * 1.4, life: 180 + rng() * 160,
              s0: 14 + rng() * 16, s1: 4, sExp: 1.6, stretch: 4.5,
              c0: [0.94, 1.0, 1.0], c1: [0.14, 0.72, 0.84],
              a0: 0.95, a1: 0, fadeIn: 0.02, alignVel: true,
              mode: M.SOFT, p0: [M.SOFT, 3.4, 0, 0],
            });
          }
        });
      },

      draw(inst, ctx) {
        const TINT = inst.tint || [0.72, 0.92, 1.0];
        const SAT = saturate(TINT, 1.4);
        const HOT = wash(SAT, 0.5);   // 火花：一半主色一半白
        const EDGE = wash(SAT, 0.3);  // 刀光：学派色全在这一层
        const t = inst.t;
        const F = inst.from;
        const To = inst.to;
        const aim = inst.aim;
        const dist = Math.hypot(To.x - F.x, To.y - F.y);
        const P = inst.kp;

        // ================= 起手：拔刀光带（path 层）===========================
        // 从攻击者卡心沿一条弓起来的路径甩到目标卡心，在命中那一格之前淡尽。
        if (t >= T.draw && t < T.impact && ctx.path(inst)) {
          const u = (t - T.draw) / (T.impact - T.draw);
          const a =
            0.9 * Math.min(1, u / 0.18) * Math.pow(clamp((1 - u) / 0.35, 0, 1), 0.9);
          if (a > 0.02) {
            const head = easeOut(u);
            const tail = Math.max(0, head - 0.55);
            const HW = strikeBandH(DRAW_H * P, dist) * 0.5;
            const pts = bowPath(F, To, tail, head, 14,
              Math.min(110, dist * 0.22) * P * (inst.arcRot < 0 ? -1 : 1),
              (k) => HW * (0.28 + 0.9 * k) * (k > 0.88 ? (1 - k) / 0.12 * 0.7 + 0.3 : 1));
            ctx.ribbon(pts, {
              cell: "swordRibbon", col: EDGE, alpha: a, hdr: 1.4,
              fadeHead: 0.10, fadeTail: 0.30, bucket: "add",
              uvDistort: 0.01, seconds: t / 1000,
            });
            const hp = pts[pts.length - 1];
            ctx.sprite({
              cell: "flashWhite", x: hp.x, y: hp.y,
              w: 120 * P, h: 120 * P, rot: aim + u * 2.2,
              col: HOT, alpha: a * 0.8, hdr: 1.3, bucket: "add",
            });
          }
        }

        // ================= 劈（接触层）=======================================
        if (t >= T.impact && ctx.contact(inst)) {
          const dt2 = t - T.impact;
          if (dt2 <= ARC_OUT) {
            const g = clamp(dt2 / ARC_MS, 0, 1);
            const d = (0.7 + 0.45 * easeOut(g)) * ARC_D;
            const a =
              dt2 < ARC_HOLD
                ? 1
                : Math.pow(1 - (dt2 - ARC_HOLD) / (ARC_OUT - ARC_HOLD), 1.4);
            ctx.flipbook({
              cell: "slashArcFb", x: To.x, y: To.y, w: d, h: d,
              rot: aim + inst.arcRot,
              frame: clamp(dt2 / ARC_FB_MS, 0, 0.999) * 16,
              col: EDGE, alpha: 0.75 * a, hdr: 1.3,
              uvDistort: 0.012, seconds: t / 1000, bucket: "add",
            });
            strikeDistort(ctx, To.x, To.y, aim, d * 1.1, 0.7 * a);
          }

          // 金属火花：扇形从命中点背离攻击者张开（ax 0 + rot aim）
          const ks = dt2 / SPARK_MS;
          if (ks < 1)
            ctx.sprite({
              cell: "slashSparks", x: To.x, y: To.y,
              w: (0.5 + 0.5 * ks) * SPARK_D,
              h: (0.5 + 0.5 * ks) * SPARK_D,
              ax: 0, rot: aim, col: HOT, alpha: Math.pow(1 - ks, 1.2),
              hdr: 1.2, bucket: "add", core: true,
            });

          strikeImpact(ctx, To.x, To.y, dt2, {
            mul: 0.85, grad: inst.tintGrad, col: HOT,
            rot: aim + inst.arcRot, hdr: 1.3, seconds: t / 1000,
          });
        }
      },
    };
  }

  // ============================================================ 抓击（claw）
  //
  // 三道抓痕直接在目标卡面上划出来。和剑劈同一套"划 → 停 → 消"的读法，但
  // 形状不是一整条新月，而是三条细痕；顿帧也只给 2 帧（剑劈是 5 帧 —— 那一刀
  // 要更重）。主色由攻击方学派给。
  //
  // 第 10 轮（贴图化）：起手的三条平行 trail 换成一张手绘挥爪拖尾，目标身上
  // 那三条逐帧生成的梭形折线换成一张手绘抓痕 —— 后者用溶解阈值"划出来"，
  // 省掉整套弧几何（clawArc / CLAW_R / CLAW_HALF / CLAW_GAP 随之删除），
  // 而且痕的边缘是画出来的、不是算出来的。
  require_claw();

  function require_claw() {
    // 三道抓痕（三条各自带时钟与溶解阈值的短 Ribbon）在目标卡面上划出来、再撕裂碎掉。
    //
    // V2（2026-09-17）：
    //   · 近战平砍从 impact 开始（卡片冲撞就是路径）；作为法术时保留挥爪拖尾（path 层）。
    //   · 抓痕挂住时间 320 → 90ms：残留必须在接触后 250ms 内消失（原则 5），
    //     "伤口"读法交给受击反应与数字。
    //   · 删掉：命中白闪星、切入、顿帧、震屏、推镜、闪帧。
    const T = { wind: 60, impact: 170, release: 280 };
    const TRAIL_H = 260;     // 拖尾贴图的横向厚度（素材内容占其中 47%）
    const TRAIL_A = 0.8;
    const MARK_IN = 50;      // 抓痕"划出来"：threshold 0.9 → 0.1
    const MARK_HOLD = 90;
    const MARK_OUT = 100;    // 阈值 0.1 → 1 撕裂碎掉
    const MARK_K = 1.6;      // 卡宽的 1.6 倍（接触层再整体缩放）
    const MARK_STAGGER = 30; // 三条痕的错时
    const MARK_GAP = 34;
    const MARK_HW = 11;
    const EMBER_MS = 240;    // 冷色火星
    const EMBER_D = 260;

    SKILLS.claw = {
      label: "抓击",
      nat: { launch: T.wind, impact: T.impact, end: T.impact + T.release },
      extent: 245,
      castExtent: 160,

      post: {
        bloom1: [
          { t: 0, v: 0.3 }, { t: T.impact - 8, v: 0.32 },
          { t: T.impact + 6, v: 0.38 }, { t: T.impact + 140, v: 0.32 },
          { t: T.impact + T.release, v: 0.3 },
        ],
        bloom2: [{ t: 0, v: 0.14 }],
        distort: [
          { t: 0, v: 0 }, { t: T.impact - 8, v: 4 },
          { t: T.impact + 4, v: 14 }, { t: T.impact + 140, v: 5 },
          { t: T.impact + T.release, v: 0 },
        ],
      },

      init(inst) {
        inst.aim = Math.atan2(inst.to.y - inst.from.y, inst.to.x - inst.from.x);
        inst.emberRot = inst.rng() * Math.PI * 2;
      },

      update(inst, ctx) {
        const rng = inst.rng;
        const To = inst.to;
        const TINT = inst.tint || [0.86, 0.93, 1.0];
        ctx.contact(inst);
        // 碎屑：少量硬边小方片，被抓飞出去再落下
        ctx.once(inst, "chips", T.impact, () => {
          for (let i = 0; i < 10; i++) {
            const a = inst.aim + (rng() - 0.5) * 2.0;
            const sp = 150 + rng() * 200;
            ctx.particles.emit({
              x: To.x + (rng() - 0.5) * 60, y: To.y + (rng() - 0.5) * 50,
              vx: Math.cos(a) * sp, vy: Math.sin(a) * sp * 0.7 - 120,
              gy: 1500, drag: 1.8, life: 220 + rng() * 120,
              s0: 7.5 + rng() * 7.5, s1: 6, sExp: 1,
              rot: rng() * 6.28, rotVel: (rng() - 0.5) * 16,
              c0: [1, 1, 1], c1: TINT,
              a0: 0.9, a1: 0, fadeIn: 0.02,
              mode: M.SOFT, p0: [M.SOFT, 9.0, 0, 0],
            });
          }
        });
      },

      draw(inst, ctx) {
        const t = inst.t;
        const TINT = inst.tint || [0.86, 0.93, 1.0];
        const SAT = saturate(TINT, 1.45);
        const HOT = wash(SAT, 0.5);
        const MARK = wash(SAT, 0.25);
        const BRIGHT = wash(SAT, 0.45);
        const To = inst.to;
        const F = inst.from;
        const dt2 = t - T.impact;
        const aim = inst.aim;
        const dist = Math.hypot(To.x - F.x, To.y - F.y);

        // ================= 起手：三道挥爪拖尾（path 层）========================
        if (t < T.impact) {
          if (t >= T.wind && ctx.path(inst)) {
            const u = (t - T.wind) / (T.impact - T.wind);
            const a =
              Math.min(1, u / 0.2) * Math.pow(clamp((1 - u) / 0.32, 0, 1), 0.9);
            if (a > 0.02)
              ctx.sprite({
                cell: "clawTrail", x: F.x, y: F.y,
                w: dist * (0.3 + 0.7 * easeOut(u)),
                h: strikeBandH(TRAIL_H * inst.kp, dist),
                ax: 0, rot: aim, col: MARK, alpha: a * TRAIL_A, hdr: 1.25,
                flow: 0.2, seconds: t / 1000, bucket: "add",
              });
          }
          return;
        }

        // ================= 抓痕：贴在目标卡面上划出来（接触层）==================
        ctx.contact(inst);
        const MARK_TOTAL = MARK_IN + MARK_HOLD + MARK_OUT;
        const d = STRIKE_CARD_W * MARK_K;
        if (dt2 <= MARK_TOTAL + 2 * MARK_STAGGER) {
          const ang = aim - 0.5;
          const ca = Math.cos(ang), sa = Math.sin(ang);
          for (let i = 0; i < 3; i++) {
            const md = dt2 - i * MARK_STAGGER;
            if (md < 0 || md > MARK_TOTAL) continue;
            const thr =
              md < MARK_IN
                ? lerp(0.9, 0.1, md / MARK_IN)
                : md < MARK_IN + MARK_HOLD
                  ? 0.1
                  : lerp(0.1, 1.0, (md - MARK_IN - MARK_HOLD) / MARK_OUT);
            const off = (i - 1) * MARK_GAP;
            const half = d * 0.5 * (i === 1 ? 1 : 0.82);
            const cx = To.x - sa * off;
            const cy = To.y + ca * off;
            const a0 = { x: cx - ca * half, y: cy - sa * half };
            const a1 = { x: cx + ca * half, y: cy + sa * half };
            const hw = MARK_HW * (i === 1 ? 1 : 0.8);
            ctx.ribbon(
              bowPath(a0, a1, 0, 1, 10, half * 0.28,
                (k) => hw * (0.35 + 1.3 * k * (1 - k) * 2)),
              {
                cell: "swordRibbon", col: BRIGHT, alpha: 1, hdr: 1.35,
                fadeHead: 0.14, fadeTail: 0.14, threshold: thr,
                uvDistort: 0.012, seconds: t / 1000 + i * 0.37, bucket: "add",
              });
          }
          strikeDistort(ctx, To.x, To.y, aim, 220,
            0.45 * clamp(1 - dt2 / MARK_TOTAL, 0, 1));
        }

        strikeImpact(ctx, To.x, To.y, dt2, {
          mul: 0.6, grad: inst.tintGrad, col: HOT,
          rot: inst.emberRot, hdr: 1.25, seconds: t / 1000,
        });

        const ke = dt2 / EMBER_MS;
        if (ke < 1)
          ctx.sprite({
            cell: "embersCool", x: To.x, y: To.y,
            w: (0.5 + 0.6 * ke) * EMBER_D, h: (0.5 + 0.6 * ke) * EMBER_D,
            rot: inst.emberRot, col: HOT, alpha: Math.pow(1 - ke, 1.2),
            hdr: 1.1, bucket: "add", core: true,
          });
      },
    };
  }

  // ============================================================ 重击（slam）
  //
  // 落点地面一圈细亮边冲击环 + 放射裂纹（暗色细线）+ 一团灰尘。
  // 力度档：**重** —— 顿帧 6 帧、震屏 amp 16，都是本管线里最强的一档。
  // 第 13 轮：shockBand()（trail 画的"实体带 + 白芯"冲击环）与它的
  // ringLoop() 一起删掉了。最后两个用户（冰枪的霜环、霜原的地面环）改用
  // ctx.ring —— 环带的内外径各走各的曲线，贴图沿周向铺，比"三条同心折线"
  // 少一半 draw call，也不再需要 gradLo 0.42/0.84/0.999 那套手调的分层。
  require_slam();

  function require_slam() {
    // 第 8–12 轮定下的重击（贴图驱动）：命中序列帧 + 八芒闪光 + 尘土冲击环（环渲染器）
    // + 前沿细亮边 + 放射裂纹 + 尘浪 + 放射火星 + 碎石与烟团粒子。
    //
    // V2（2026-09-17）：
    //   · 裂纹贴花的长尾（长出 90 + 保持 200 + 碎掉 350）→ 60 / 40 / 120，
    //     落点残留的地面亮斑（520ms）删掉 —— 原则 5：瞬时视觉 250ms 内消失。
    //   · 尘浪 400×1.6、裂纹 560 收到与冲击环同一量级，碎石与烟团初速减半：
    //     它们原来比冲击环大一倍，接触层缩放会被它们决定。
    //   · 删掉：顿帧 100ms、震屏 amp 16、推镜 1.06、径向模糊、色散、局部暗角、闪帧。
    const T = { impact: 80, release: 320 };
    const FLASH_MS = 120;
    const FLASH_D = 300;
    const RING_MS = 240;
    const RING_D = 400;
    const RING_UV_R = 0.82;
    const RING_BAND = 150;
    const SHOCK_MS = 280;
    const SHOCK_BUCKET = "body";
    const DUST_MS = 300;
    const DUST_D = 300;
    const DUST_SQUASH = 0.45;
    const EMBER_MS = 220;
    const EMBER_D = 320;
    const CRACK_D = 400;
    const CRACK_GRID = { cols: 1, rows: 1, count: 1 };
    const CRACK_SQUASH = 0.42;
    const CRACK_GROW = 60;
    const CRACK_HOLD = 40;
    const CRACK_BREAK = 120;
    const CARD_FOOT = 60;   // 地面元素的圆心：卡底边缘略上方
    const DUST_COL = [0.66, 0.60, 0.53];

    SKILLS.slam = {
      label: "重击",
      nat: { launch: 0, impact: T.impact, end: T.impact + T.release },
      extent: 360,
      castExtent: 160,

      post: {
        bloom1: [
          { t: 0, v: 0.3 }, { t: T.impact - 8, v: 0.33 },
          { t: T.impact + 6, v: 0.42 }, { t: T.impact + 220, v: 0.33 },
          { t: T.impact + T.release, v: 0.3 },
        ],
        bloom2: [{ t: 0, v: 0.14 }],
        distort: [
          { t: 0, v: 0 }, { t: T.impact - 6, v: 6 },
          { t: T.impact + 4, v: 26 }, { t: T.impact + 200, v: 8 },
          { t: T.impact + T.release, v: 0 },
        ],
      },

      init(inst) {
        inst.aim = Math.atan2(inst.to.y - inst.from.y, inst.to.x - inst.from.x);
        const To = inst.to;
        inst.foot = { x: To.x, y: To.y + CARD_FOOT };
        inst.crackRot = inst.rng() * Math.PI * 2;
        inst.flashRot = (inst.rng() - 0.5) * 0.8;
        inst.emberRot = inst.rng() * Math.PI * 2;
        inst.ringSpin = (inst.rng() < 0.5 ? -1 : 1) * 0.6;
        inst.dustRot = inst.rng() * Math.PI * 2;
        inst.dustSpin = (inst.rng() - 0.5) * 0.5;
      },

      update(inst, ctx) {
        const rng = inst.rng;
        const To = inst.to;
        const foot = inst.foot;
        const TINT = inst.tint || [0.86, 0.93, 1.0];
        ctx.contact(inst);

        ctx.once(inst, "debris", T.impact, () => {
          // 碎石：RGBA 贴图粒子，走 body 桶；落到卡脚下方就一边沉一边被溶解吃掉
          for (let i = 0; i < 8; i++) {
            const side = i % 2 ? 1 : -1;
            const a = 0.35 + rng() * 0.9;
            const sp = 140 + rng() * 160;
            const s = 14 + rng() * 16;
            ctx.particles.emit({
              x: foot.x + side * (16 + rng() * 50),
              y: foot.y + (rng() - 0.5) * 16,
              vx: Math.cos(a) * sp * side, vy: -(180 + rng() * 160),
              gy: 2000, drag: 0.8, life: 300 + rng() * 100,
              s0: s, s1: s, sExp: 1,
              rot: rng() * 6.28, rotVel: (rng() - 0.5) * 18,
              c0: [1, 1, 1], c1: [0.82, 0.80, 0.78],
              a0: 1, a1: 0, aExp: 2.6, fadeIn: 0.02, bucket: "body",
              mode: M.SPRITE, cell: "rock" + (i % 6),
              p0: [M.SPRITE, 1, 0, 0.2], p1: [0, 0, 9, 0],
              sinkY: foot.y + 30,
            });
          }
          // 火花：一小把程序化柔光点（bloom 的喂料）
          for (let i = 0; i < 16; i++) {
            const a = rng() * Math.PI * 2;
            const sp = 160 + rng() * 220;
            ctx.particles.emit({
              x: To.x, y: To.y,
              vx: Math.cos(a) * sp, vy: Math.sin(a) * sp * 0.6 - 200,
              gy: 2200, drag: 1.4, life: 240 + rng() * 120,
              s0: 7 + rng() * 7, s1: 5, sExp: 1,
              rot: 0, alignVel: true, stretch: 2.2,
              c0: [1, 0.98, 0.94], c1: saturate(TINT, 1.4),
              a0: 0.95, a1: 0, fadeIn: 0.02,
              mode: M.SOFT, p0: [M.SOFT, 9.0, 0, 0],
            });
          }
        });

        ctx.once(inst, "smoke", T.impact + 2 * FIXED_DT, () => {
          // 烟：6 片序列帧烟团从卡脚向上翻涌，每片叠一张同轨迹的加色副本当受光边
          for (let i = 0; i < 6; i++) {
            const side = (i / 5) * 2 - 1;
            const warm = Math.abs(side) < 0.45;
            const seed = {
              x: foot.x + side * 60 + (rng() - 0.5) * 18,
              y: foot.y + (rng() - 0.5) * 12,
              vx: side * (30 + rng() * 60), vy: -(90 + rng() * 90),
              gy: 60, drag: 2.4, life: 360 + rng() * 80,
              s0: 60, s1: 140, sExp: 0.7,
              rot: rng() * 6.28, rotVel: (rng() - 0.5) * 1.6,
              aExp: 1.2, fadeIn: 0.15,
              fb: { cell: "smokeFb", loops: 1, threshold: 0.12, soft: 0.30,
                    uvDistort: 0.03 },
              seed: rng() * 10,
            };
            ctx.particles.emit(Object.assign({}, seed, {
              c0: warm ? [0.95, 0.76, 0.56] : [0.72, 0.68, 0.62],
              c1: warm ? [0.40, 0.33, 0.28] : [0.34, 0.32, 0.30],
              a0: 0.6, a1: 0, bucket: "smoke",
            }));
            ctx.particles.emit(Object.assign({}, seed, {
              c0: warm ? [1.0, 0.82, 0.62] : [0.86, 0.82, 0.76],
              c1: warm ? [0.34, 0.26, 0.20] : [0.26, 0.25, 0.24],
              a0: 0.1, a1: 0, bucket: "add",
            }));
          }
        });
      },

      draw(inst, ctx) {
        const t = inst.t;
        if (t < T.impact) return;
        ctx.contact(inst);
        const TINT = inst.tint || [0.86, 0.93, 1.0];
        const SAT = saturate(TINT, 1.4);
        const HOT = wash(SAT, 0.5);
        const WARM = wash(SAT, 0.75);
        const EDGE = wash(SAT, 0.4);
        const To = inst.to;
        const F0 = inst.foot;
        const dt2 = t - T.impact;
        const sec = t / 1000;

        // ---- 命中序列帧：16 帧，芒刺一帧比一帧长出来 ------------------------
        strikeImpact(ctx, To.x, To.y, dt2, {
          mul: 1.0, grad: inst.tintGrad, col: HOT, rot: inst.flashRot,
          hdr: 1.2, alpha: 0.6, seconds: sec,
        });

        // ---- 落点闪光：八芒贴图，两帧张开、120ms 消失 ---------------------
        if (dt2 < FLASH_MS) {
          const g = clamp(dt2 / (2 * FIXED_DT), 0, 1);
          const d = (0.6 + 0.6 * g) * FLASH_D;
          ctx.sprite({
            cell: "flash", x: To.x, y: To.y, w: d, h: d, rot: inst.flashRot,
            col: HOT, alpha: 0.3 * Math.pow(1 - dt2 / FLASH_MS, 1.3),
            hdr: 1.1, bucket: "add", core: true,
          });
        }

        // ---- 主体冲击环：环渲染器，内外径各走各的曲线 ----------------------
        const ks = dt2 / SHOCK_MS;
        if (ks < 1) {
          const R = RING_D * 0.5;
          const rOut = (0.42 + 0.58 * Math.pow(ks, 0.55)) * R;
          // 内径不小于外径的 0.62：刚张开时环带不能是一整块实心盘（over 桶的淡白会把
          // 卡面中央刷白，契约原则 4）
          const rIn = Math.max(rOut * 0.62, rOut - RING_BAND * lerp(0.5, 0.18, Math.pow(ks, 0.8)));
          ctx.ring({
            cell: "shockwave", x: To.x, y: To.y, r0: rIn, r1: rOut,
            squash: GROUND_SQUASH, seg: 56, a0: inst.ringSpin * 0.5 * sec,
            tile: 4, col: EDGE, alpha: 0.5 * Math.pow(1 - ks, 1.2),
            bucket: SHOCK_BUCKET,
          });
        }

        // ---- 前沿细亮边 + 折射 ----------------------------------------------
        const kr = dt2 / RING_MS;
        if (kr < 1) {
          const d = (0.35 + 0.65 * Math.pow(kr, 0.55)) * RING_D;
          const fade = kr < 0.55 ? 1 : Math.pow(1 - (kr - 0.55) / 0.45, 1.5);
          ctx.sprite({
            cell: "ringAnnulus", x: To.x, y: To.y, w: d, h: d,
            squash: GROUND_SQUASH, col: EDGE, alpha: 0.55 * fade, hdr: 0.9,
            bucket: "ground", core: true,
          });
          ctx.distort({
            x: To.x, y: To.y, w: d, squash: GROUND_SQUASH,
            kind: 0, strength: 1.0 * fade, ringRadius: RING_UV_R, ringWidth: 0.1,
          });
        }

        // ---- 放射裂纹：贴地 decal，长出 → 短暂保持 → 烧断碎掉 ---------------
        const dc = dt2 - FIXED_DT;
        if (dc >= 0 && dc <= CRACK_GROW + CRACK_HOLD + CRACK_BREAK) {
          const bk = clamp((dc - CRACK_GROW - CRACK_HOLD) / CRACK_BREAK, 0, 1);
          const grow = dc < CRACK_GROW
            ? lerp(0.5, 1, easeOut(dc / CRACK_GROW)) : 1;
          const cd = CRACK_D * grow;
          ctx.flipbook({
            cell: "groundCrack", frames: CRACK_GRID,
            x: F0.x, y: F0.y, w: cd, h: cd,
            squash: CRACK_SQUASH, rot: inst.crackRot, col: WARM,
            alpha: Math.min(1, dc / (2 * FIXED_DT)),
            hdr: 1.2,
            threshold: bk > 0 ? 0.15 + 0.85 * bk : 0,
            soft: 0.22, edgeWidth: bk > 0 ? 0.20 : 0,
            grad: G.EMBER, gradLo: 0.10,
            uvDistort: 0.008, seconds: sec, bucket: "add", core: true,
          });
        }

        // ---- 尘浪：顶视中空尘环，走 smoke 桶 --------------------------------
        const kd = dt2 / DUST_MS;
        if (kd < 1) {
          const d = (0.4 + 0.9 * Math.pow(kd, 0.62)) * DUST_D;
          ctx.sprite({
            cell: "dustwave", x: F0.x, y: F0.y, w: d, h: d,
            squash: DUST_SQUASH, rot: inst.dustRot + inst.dustSpin * sec,
            col: DUST_COL, alpha: 0.6 * Math.pow(1 - kd, 1.3),
            seconds: sec, bucket: "smoke",
          });
        }

        // ---- 放射火星 --------------------------------------------------------
        const ke = dt2 / EMBER_MS;
        if (ke < 1) {
          const d = (0.5 + 0.6 * ke) * EMBER_D;
          ctx.sprite({
            cell: "embers", x: To.x, y: To.y, w: d, h: d, rot: inst.emberRot,
            col: HOT, alpha: Math.pow(1 - ke, 1.2), hdr: 1.0, bucket: "add", core: true,
          });
        }
      },
    };
  }

  // ================================================== 远程投射物（arrow / spear）
  //
  // 画法两族各一支：
  //   arrow  一支会飞的箭：Ribbon 拖尾 + 箭镞从攻击者卡心飞到目标卡心（力度：轻）
  //   spear  一根刺出去的矛：定长光矛从攻击者卡心刺出、平移到目标（力度：中）
  // 命中：贯穿星芒 + 命中序列帧 + 一小簇冷火星。飞行时长由 plan 按距离给。
  requireShaft("arrow", {
    flight: 120, lance: 0, chips: 6,
    trailH: 200, trailLen: 0.42 * 1.3, trailMax: 300 * 1.3,
    hitD: 240 * 1.4, hitMs: 150, hitLo: 0.6, hitHi: 1.2,
    distort: 0.5, emberD: 220, emberN: 5,
    extent: 355, core: 0.45,
  });
  requireShaft("spear", {
    flight: 160, lance: 1, chips: 5,
    lanceH: 220,
    // 贯穿光不横跨整段距离：裁到 min(距离×0.45, 160px)，矛是一段有长度的枪尖
    lanceLen: 0.45, lanceMax: 160,
    hitD: 280 * 1.3, hitMs: 170, hitLo: 0.6, hitHi: 1.3,
    distort: 0.95, emberD: 240, emberN: 6,
    extent: 440, core: 0.5,
  });

  function requireShaft(name, S) {
    // V2（2026-09-17）：飞行时长交给 plan（远程平砍 1800px/s，钳 90–220ms；作为法术
    // 1400px/s，钳 160–320ms），配方的自然飞行 [0, flight] 被映射到这段时间上。
    //   · 箭的起点不再后移到攻击者卡**外面**（旧版 ARROW_BACK 60px），路径必须从
    //     攻击者卡面出发；
    //   · 命中点残留火星 300 → 160ms，命中白闪星删掉（整卡打白）；
    //   · 删掉：切入、顿帧、震屏、推镜、闪帧。
    const T = { impact: S.flight, release: 240 };
    const HIT_MS = S.hitMs;
    const EMBER_MS = 160;
    const ARROW_HEAD = 72;

    SKILLS[name] = {
      label: name === "arrow" ? "箭" : "投枪",
      nat: { launch: 0, impact: T.impact, end: T.impact + T.release },
      extent: S.extent,
      castExtent: 160,

      post: {
        bloom1: [
          { t: 0, v: 0.3 }, { t: T.impact - 6, v: 0.33 },
          { t: T.impact + 6, v: 0.4 }, { t: T.impact + 120, v: 0.32 },
          { t: T.impact + T.release, v: 0.3 },
        ],
        bloom2: [{ t: 0, v: 0.14 }],
        distort: [
          { t: 0, v: 0 }, { t: T.impact - 6, v: 3 },
          { t: T.impact + 4, v: 10 + 6 * S.lance },
          { t: T.impact + 120, v: 3 }, { t: T.impact + T.release, v: 0 },
        ],
      },

      init(inst) {
        inst.aim = Math.atan2(inst.to.y - inst.from.y, inst.to.x - inst.from.x);
        inst.emberRot = inst.rng() * Math.PI * 2;
      },

      update(inst, ctx) {
        const rng = inst.rng;
        const To = inst.to;
        const TINT = inst.tint || [0.86, 0.93, 1.0];
        ctx.contact(inst);
        ctx.once(inst, "hit", T.impact, () => {
          for (let i = 0; i < S.emberN; i++) {
            const a = rng() * Math.PI * 2;
            const sp = 40 + rng() * 90;
            ctx.particles.emit({
              x: To.x + (rng() - 0.5) * 26, y: To.y + (rng() - 0.5) * 26,
              vx: Math.cos(a) * sp, vy: Math.sin(a) * sp * 0.6 - 40,
              gy: 260, drag: 2.6, life: 200 + rng() * 80,
              s0: 9 + rng() * 6, s1: 3, sExp: 1.3, stretch: 1.6,
              c0: [1, 1, 1], c1: TINT,
              a0: 0.95, a1: 0, aExp: 0.9, fadeIn: 0.02, alignVel: true,
              mode: M.SOFT, p0: [M.SOFT, 5.0, 0, 0],
            });
          }
          for (let i = 0; i < S.chips; i++) {
            const a = inst.aim + Math.PI + (rng() - 0.5) * 2.2;
            const sp = 160 + rng() * 180;
            ctx.particles.emit({
              x: To.x, y: To.y,
              vx: Math.cos(a) * sp, vy: Math.sin(a) * sp * 0.7 - 100,
              gy: 1700, drag: 2.0, life: 200 + rng() * 120,
              s0: 6 + rng() * 6, s1: 4, sExp: 1,
              rot: rng() * 6.28, rotVel: (rng() - 0.5) * 16,
              c0: [1, 1, 1], c1: TINT,
              a0: 0.95, a1: 0, fadeIn: 0.02,
              mode: M.SOFT, p0: [M.SOFT, 9.0, 0, 0],
            });
          }
        });
      },

      draw(inst, ctx) {
        const TINT = inst.tint || [0.86, 0.93, 1.0];
        const SAT = saturate(TINT, 1.4);
        const HOT = wash(SAT, 0.5);
        const SHAFT = wash(SAT, 0.3);
        const F = inst.from;
        const To = inst.to;
        const t = inst.t;
        const aim = inst.aim;
        const dist = Math.hypot(To.x - F.x, To.y - F.y);
        const P = inst.kp;

        // ---- 飞行段（path 层）----------------------------------------------
        if (t <= T.impact && dist > 1 && ctx.path(inst)) {
          const u = clamp(t / S.flight, 0, 1);
          if (S.lance) {
            // 投枪：一段定长的光矛从攻击者卡心刺出去、平移到目标卡心
            const L = Math.min(dist * S.lanceLen, S.lanceMax * P);
            const tip = dist * easeOut(u);
            const back = Math.max(0, tip - L);
            const HW = strikeBandH(S.lanceH * P, dist) * 0.5;
            const b0 = { x: F.x + Math.cos(aim) * back, y: F.y + Math.sin(aim) * back };
            const b1 = { x: F.x + Math.cos(aim) * tip, y: F.y + Math.sin(aim) * tip };
            ctx.ribbon(
              bowPath(b0, b1, 0, 1, 8, 0,
                (k) => HW * (k < 0.75 ? 0.35 + 0.86 * k : (1 - k) / 0.25 * 0.99)),
              {
                cell: "swordRibbon", col: SHAFT,
                alpha: Math.min(1, 0.3 + u / 0.12), hdr: 1.5,
                fadeHead: 0.06, fadeTail: 0.34,
                uvDistort: 0.008, seconds: t / 1000, bucket: "add",
              });
          } else {
            // 箭：Ribbon 拖尾 + 箭镞，从攻击者卡心飞到目标卡心
            const hx = lerp(F.x, To.x, u);
            const hy = lerp(F.y, To.y, u);
            const tailLen = Math.min(S.trailMax * P, dist * S.trailLen);
            const tailU = Math.max(0, u - tailLen / dist);
            const HW = strikeBandH(S.trailH * P, dist) * 0.5;
            ctx.ribbon(
              bowPath(F, To, tailU, Math.max(u, tailU + 0.02), 10, 0,
                (k) => HW * (0.12 + 0.62 * k)),
              {
                cell: "swordRibbon", col: SHAFT, alpha: 1, hdr: 1.4,
                fadeHead: 0.05, fadeTail: 0.42,
                uvDistort: 0.01, seconds: t / 1000, bucket: "add",
              });
            ctx.sprite({
              cell: "arrowTrail", x: hx, y: hy,
              w: ARROW_HEAD * P, h: ARROW_HEAD * 0.5 * P, ax: 1, rot: aim,
              col: HOT, alpha: 1, hdr: 1.6, bucket: "add",
            });
          }
        }

        // ---- 命中：贯穿星芒 + 命中序列帧 + 一小簇火星（接触层）--------------
        const dt2 = t - T.impact;
        if (dt2 >= 0 && ctx.contact(inst)) {
          const kh = dt2 / HIT_MS;
          if (kh < 1) {
            const d = lerp(S.hitLo, S.hitHi, easeOut(kh)) * S.hitD;
            ctx.sprite({
              cell: S.lance ? "spearHit" : "arrowHit",
              x: To.x, y: To.y, w: d, h: d, rot: aim,
              col: HOT, alpha: Math.pow(1 - kh, 1.3), hdr: 1.5, bucket: "add", core: S.core,
            });
          }
          strikeImpact(ctx, To.x, To.y, dt2, {
            mul: S.lance ? 0.95 : 0.62, grad: inst.tintGrad, col: HOT,
            rot: aim, hdr: 1.35, seconds: t / 1000,
          });
          const ke = dt2 / EMBER_MS;
          if (ke <= 1) {
            const ea = 0.9 * Math.pow(1 - ke, 0.8);
            ctx.sprite({
              cell: "embersCool", x: To.x, y: To.y,
              w: (0.45 + 0.5 * ke) * S.emberD,
              h: (0.45 + 0.5 * ke) * S.emberD,
              rot: inst.emberRot, col: HOT,
              alpha: ea, hdr: 1.3, bucket: "add", core: S.core,
            });
            ctx.soft(To.x, To.y, 0.5 * S.emberD, HOT, ea * 0.6, { falloff: 2.4, core: S.core });
          }
          strikeDistort(ctx, To.x, To.y, aim, S.hitD,
            S.distort * Math.pow(clamp(1 - dt2 / 160, 0, 1), 1.2));
        }
      },
    };
  }

  // ============================================================ 魔法平砍（bolt）
  //
  // 蓄能 → 一道电束连上目标 → 命中电光爆散。
  //
  // 第 9 轮把飞行段从"220ms 的小彗星"换成"80ms 到达的能量束"（小彗星慢慢飘
  // 过去，读不出"魔法平砍"的即时感，而且 260ms 的命中点顶满了 300ms 的
  // lead-in）；第 10 轮把束身的三层 trail、命中的 dissolve 火团与 shockBand
  // 全部换成手绘贴图。电弧的"活"不再靠逐帧现算的正弦折线，而是靠
  // flow 抖形 + 每两帧一次的 flip 变体 + 每帧 0.7~1.0 的 alpha 抖动 —— 三样
  // 都不用 CPU 侧算几何，同一张贴图就能不重复。
  require_bolt();

  function require_bolt() {
    // 蓄能 → 一道电束连上目标 → 命中电光爆散（第 9–12 轮的贴图版）。
    //
    // V2（2026-09-17）：
    //   · 电球不再浮在攻击者卡位**上方 60px**（手机上 60px 的卡，电球整个在卡外），
    //     改成卡高的 0.25 倍；
    //   · 卡面电蚀残留（300ms、闪 3 下）删掉 —— 原则 5，电蚀像"持续伤害"状态；
    //   · 命中白闪星删掉；切入、顿帧、震屏、推镜、闪帧删掉。
    const T = { beamIn: 40, impact: 100, release: 220 };
    const ORB_MS = 40;
    const ORB_D = 240;
    const ORB_LIFT = 0.25;
    const BEAM_MS = 60;
    const BEAM_TAIL = 70;
    const BEAM_H = 170;
    const BOLT_VARIANTS = 16;
    const HIT_MS = 200;
    const HIT_D = 312;

    SKILLS.bolt = {
      label: "魔法弹",
      nat: { launch: T.beamIn, impact: T.impact, end: T.impact + T.release },
      extent: 270,
      castExtent: 180,

      post: {
        bloom1: [
          { t: 0, v: 0.3 }, { t: T.impact - 8, v: 0.34 },
          { t: T.impact + 6, v: 0.44 }, { t: T.impact + 160, v: 0.33 },
          { t: T.impact + T.release, v: 0.3 },
        ],
        bloom2: [{ t: 0, v: 0.14 }],
        distort: [
          { t: 0, v: 0 }, { t: T.impact - 6, v: 4 },
          { t: T.impact + 4, v: 16 }, { t: T.impact + 160, v: 5 },
          { t: T.impact + T.release, v: 0 },
        ],
      },

      init(inst) {
        inst.aim = Math.atan2(inst.to.y - inst.from.y, inst.to.x - inst.from.x);
        inst.hitRot = inst.rng() * Math.PI * 2;
      },

      update(inst, ctx) {
        const rng = inst.rng;
        const To = inst.to;
        const TINT = inst.tint || [1.0, 0.54, 0.16];
        ctx.contact(inst);
        ctx.once(inst, "boom", T.impact, () => {
          for (let i = 0; i < 10; i++) {
            const a = rng() * Math.PI * 2;
            const sp = 150 + rng() * 220;
            ctx.particles.emit({
              x: To.x, y: To.y,
              vx: Math.cos(a) * sp, vy: Math.sin(a) * sp * 0.7 - 90,
              gy: 1300, drag: 2.4, life: 200 + rng() * 140,
              s0: 7 + rng() * 7, s1: 4, sExp: 1.4, stretch: 2.6,
              c0: [1, 1, 0.96], c1: TINT,
              a0: 0.95, a1: 0, fadeIn: 0.02, alignVel: true,
              mode: M.SOFT, p0: [M.SOFT, 4.0, 0, 0],
            });
          }
        });
      },

      draw(inst, ctx) {
        const TINT = inst.tint || [1.0, 0.54, 0.16];
        const SAT = saturate(TINT, 1.35);
        const HOT = wash(SAT, 0.5);
        const ARC = wash(SAT, 0.3);
        const F = inst.from;
        const To = inst.to;
        const t = inst.t;
        const sec = t / 1000;
        const aim = inst.aim;
        const dist = Math.hypot(To.x - F.x, To.y - F.y);

        // ---- 蓄能：攻击者卡上一颗电球（caster 层）---------------------------
        if (t < T.beamIn + 2 * FIXED_DT && ctx.caster(inst)) {
          const u = clamp(t / ORB_MS, 0, 1);
          const d = 0.6 * easeOut(u) * ORB_D;
          const a = t <= ORB_MS ? 1 : Math.pow(clamp(1 - (t - ORB_MS) / 40, 0, 1), 1.3);
          if (d > 2 && a > 0.02)
            ctx.sprite({
              cell: "boltOrb", x: F.x, y: F.y - ORB_LIFT * inst.fromBox.h, w: d, h: d,
              rot: sec * 1.4, col: ARC, alpha: a, hdr: 1.5,
              flow: 0.18, seconds: sec, bucket: "add",
            });
        }

        // ---- 束：连上目标，到达后淡出（path 层）-----------------------------
        if (t >= T.beamIn && t <= T.impact + BEAM_TAIL && dist > 1 && ctx.path(inst)) {
          const front = easeOut(clamp((t - T.beamIn) / BEAM_MS, 0, 1));
          const after = clamp((t - T.impact) / BEAM_TAIL, 0, 1);
          const frame = Math.floor(t / FIXED_DT);
          const jitter = 0.7 + 0.3 * Math.abs(Math.sin(frame * 2.399 + inst.seed));
          const step = Math.floor(frame / 2);
          const L = dist * front;
          const mx = F.x + Math.cos(aim) * L * 0.5;
          const my = F.y + Math.sin(aim) * L * 0.5;
          const a2 = jitter * Math.pow(1 - after, 1.4);
          ctx.mark(F.x, F.y, F.x + Math.cos(aim) * L, F.y + Math.sin(aim) * L);
          for (let i = 0; i < 2; i++) {
            const v = Math.floor(
              Math.abs(Math.sin(step * 12.9898 + inst.seed * 0.137 + i * 3.1)) *
              BOLT_VARIANTS) % BOLT_VARIANTS;
            ctx.flipbook({
              // 四边形压成 cos φ : sin φ 的长方形：对角线仍是 from→头部、长度仍是 L，
              // 但电弧的横向摆幅只剩 tan φ ≈ 0.55 倍（正方形时电弧能甩出路径两侧几百像素）
              cell: "lightningFb", x: mx, y: my, w: L * ARC_COS, h: L * ARC_SIN,
              rot: aim - ARC_PHI,
              frame: v, lerp: false,
              col: ARC, alpha: a2 * (i ? 0.7 : 1), hdr: 1.6,
              uvDistort: 0.02, seconds: sec, bucket: "add",
            });
          }
          ctx.distort({
            x: lerp(F.x, To.x, front * 0.5), y: lerp(F.y, To.y, front * 0.5),
            w: dist * front, h: strikeBandH(BEAM_H * inst.kp, dist) * 0.6, rot: aim,
            kind: 1, strength: 0.45 * Math.pow(1 - after, 1.4), seconds: sec,
          });
        }

        // ---- 命中：电光爆散 + 一颗小电球（接触层）---------------------------
        const dt2 = t - T.impact;
        if (dt2 >= 0 && ctx.contact(inst)) {
          strikeImpact(ctx, To.x, To.y, dt2, {
            cell: "electricFb", ms: HIT_MS, d: HIT_D, mul: 1.0,
            grad: inst.tintGrad, col: HOT, rot: inst.hitRot,
            hdr: 1.7, uvDistort: 0.015, seconds: sec, core: 0.15,
          });
          const ko = dt2 / 60;
          if (ko < 1)
            ctx.sprite({
              cell: "boltOrb", x: To.x, y: To.y,
              w: 0.4 * ORB_D, h: 0.4 * ORB_D,
              rot: -sec * 2.2, col: HOT, alpha: Math.pow(1 - ko, 1.2),
              hdr: 1.4, flow: 0.2, seconds: sec, bucket: "add", core: 0.25,
            });
          strikeDistort(ctx, To.x, To.y, aim, HIT_D,
            0.6 * Math.pow(clamp(1 - dt2 / 150, 0, 1), 1.2));
        }
      },
    };
  }

  // ============================================================ 吐息（breath）
  //
  // 从攻击方到目标的火焰锥：锥口钉在攻击者身上、沿 x 伸到目标，目标处炸开
  // 一团焦灼。锥体必须**越靠目标越宽**才读成"喷出来的火"而不是"射出来的光"，
  // 第 10 轮之前这是靠 24 团溶解火焰 + 一条越来越粗的 trail 拼出来的；现在
  // 直接用一张手绘喷火锥（左窄右宽），flow 0.35 让它自己烧起来，走 body 桶
  // （over 混合）——加性桶里火永远是半透明的，读不出"一堵火墙"。
  require_breath();

  function require_breath() {
    // 第 10–12 轮的"流"版吐息：breath-stream 火流（revealU 推进，不拉伸）+ 两张错相位
    // 滚动的平铺副本 + 外层暗红烟锥 + 白黄热芯 + 前端火头 + 沿前端翻出的火舌粒子。
    //
    // V2（2026-09-17）：
    //   · 锥宽约束：终点处最宽的一层（外层烟锥）不超过目标卡宽 1.2 倍。火流贴图的
    //     内容在远端约占四边形高度的 CONE_BAND，烟锥再放大 SMOKE_K，所以
    //     H ≤ 1.2 × 目标卡宽 / (CONE_BAND × SMOKE_K)。火舌粒子的散布与尺寸跟着 H 收。
    //   · 卡面焦痕残留（烟团暗斑 + 裂纹 + 余烬，420ms）删掉 —— 原则 5，像"持续灼烧"。
    //   · 命中暖闪里那两张白盘（240 / 160px 纯白柔光，整卡打白）删掉，只留一层暖色辉光。
    //   · 删掉：顿帧、震屏、推镜、闪帧。
    const T = { open: 20, impact: 220, release: 260 };
    const FLOW_MS = 200;
    const CONE_TAIL = 70;  // 接触后火流收口（原 120：火流本体压在卡面中央太久）
    const CONE_FRONT = 1.08;
    const CONE_FULL = 360;
    const CONE_SQUASH = 0.35;
    const CONE_BAND = 0.566;  // breath-stream 远端内容占四边形高度的比例
    const CONE_MAX_W = 1.2;   // 终点处锥宽 ≤ 目标卡宽 × 1.2（契约）
    const TILE_H = 1.24;
    const CORE_K = 0.45;
    const SMOKE_K = 1.25;
    const SMOKE_LAG = 60;
    const SMOKE_COL = [0.45, 0.12, 0.05];
    const MUZZLE_MS = 60;
    const PUFF_EVERY = 30;
    const HEAD_MS = 260;
    const SCORCH_MS = 160;
    const SCORCH_D = 240;
    const EMBER_MS = 220;
    const EMBER_D = 280;

    /** 这一发的锥高：自然长宽比，超远抛射按斜率收，再按目标卡宽封顶。 */
    function coneH(inst) {
      const W = Math.hypot(inst.to.x - inst.from.x, inst.to.y - inst.from.y);
      const full = CONE_FULL * inst.kp;
      const natural = W <= full ? W : full + (W - full) * CONE_SQUASH;
      return Math.min(natural, CONE_MAX_W * inst.toBox.w / (CONE_BAND * SMOKE_K));
    }

    SKILLS.breath = {
      label: "吐息",
      nat: { launch: T.open, impact: T.impact, end: T.impact + T.release },
      extent: 300,
      castExtent: 160,

      post: {
        bloom1: [
          { t: 0, v: 0.3 }, { t: T.open, v: 0.36 },
          { t: T.impact + 6, v: 0.46 }, { t: T.impact + 200, v: 0.34 },
          { t: T.impact + T.release, v: 0.3 },
        ],
        bloom2: [{ t: 0, v: 0.14 }],
        distort: [
          { t: 0, v: 0 }, { t: T.open, v: 10 },
          { t: T.impact + 4, v: 24 }, { t: T.impact + 200, v: 8 },
          { t: T.impact + T.release, v: 0 },
        ],
      },

      init(inst) {
        inst.aim = Math.atan2(inst.to.y - inst.from.y, inst.to.x - inst.from.x);
        inst.emitAcc = 0;
        inst.scorchRot = inst.rng() * Math.PI * 2;
        inst.emberRot = inst.rng() * Math.PI * 2;
        inst.tilePhase = [inst.rng(), inst.rng()];
        inst.headRot = inst.rng() * Math.PI * 2;
        inst.coneH = coneH(inst);
      },

      update(inst, ctx, dt) {
        const rng = inst.rng;
        const F = inst.from;
        const To = inst.to;
        const t = inst.t;

        // 火舌：跟着前端走，散布与尺寸都不越过锥宽
        if (t >= T.open && t <= T.impact && ctx.path(inst)) {
          const len = Math.hypot(To.x - F.x, To.y - F.y);
          const nx = -Math.sin(inst.aim);
          const ny = Math.cos(inst.aim);
          const H = inst.coneH;
          const pk = clamp(H / 420, 0.2, 1.15);
          const front = easeOut(clamp((t - T.open) / FLOW_MS, 0, 1));
          inst.emitAcc += dt || FIXED_DT;
          while (inst.emitAcc >= PUFF_EVERY) {
            inst.emitAcc -= PUFF_EVERY;
            const n = 2 + (rng() < 0.5 ? 1 : 0);
            for (let i = 0; i < n; i++) {
              const s = clamp(front - 0.06 - rng() * 0.12, 0.02, 1);
              const spread = (rng() - 0.5) * s * H * 0.3;
              ctx.particles.emit({
                x: lerp(F.x, To.x, s) + nx * spread,
                y: lerp(F.y, To.y, s) + ny * spread,
                vx: Math.cos(inst.aim) * (120 + rng() * 150) * pk + nx * spread * 1.2,
                vy: Math.sin(inst.aim) * (120 + rng() * 150) * pk + ny * spread * 1.2
                    - (60 + rng() * 60) * pk,
                gy: -140 * pk, drag: 1.4, life: 200 + rng() * 140,
                s0: (34 + rng() * 22) * pk, s1: (80 + rng() * 40) * pk, sExp: 0.8,
                rot: rng() * 6.28, rotVel: (rng() - 0.5) * 2.6,
                c0: [1, 0.95, 0.8], c1: [1, 0.42, 0.12],
                a0: 0.85, a1: 0, aExp: 1.3, fadeIn: 0.12,
                bucket: "body",
                fb: { cell: "fireFb", loops: 1, threshold: 0.1, soft: 0.3,
                      uvDistort: 0.03, hdr: 1.2 },
              });
            }
            for (let i = 0; i < 2; i++) {
              const s = clamp(front - rng() * 0.2, 0.02, 1);
              const a = inst.aim + (rng() - 0.5) * 0.8;
              const sp = (150 + rng() * 200) * pk;
              ctx.particles.emit({
                x: lerp(F.x, To.x, s), y: lerp(F.y, To.y, s),
                vx: Math.cos(a) * sp, vy: Math.sin(a) * sp * 0.7 - (100 + rng() * 100) * pk,
                gy: 700, drag: 2.4, life: 200 + rng() * 160,
                s0: 5 + rng() * 6, s1: 2, sExp: 1.5, stretch: 2.2,
                c0: [1, 0.96, 0.82], c1: [1, 0.38, 0.1],
                a0: 0.9, a1: 0, fadeIn: 0.02, alignVel: true,
                mode: M.SOFT, p0: [M.SOFT, 4.0, 0, 0],
              });
            }
          }
        }

        ctx.contact(inst);
        ctx.once(inst, "scorch", T.impact, () => {
          for (let i = 0; i < 12; i++) {
            const a = inst.aim + (rng() - 0.5) * 2.6;
            const spd = 140 + rng() * 200;
            ctx.particles.emit({
              x: To.x, y: To.y,
              vx: Math.cos(a) * spd, vy: Math.sin(a) * spd * 0.7 - 120,
              gy: 900, drag: 2.6, life: 220 + rng() * 140,
              s0: 8 + rng() * 8, s1: 3, sExp: 1.5, stretch: 2.4,
              c0: [1, 0.98, 0.86], c1: [1, 0.36, 0.08],
              a0: 0.95, a1: 0, fadeIn: 0.02, alignVel: true,
              mode: M.SOFT, p0: [M.SOFT, 4.0, 0, 0],
            });
          }
        });
      },

      draw(inst, ctx) {
        const TINT = inst.tint || [1.0, 0.55, 0.16];
        const SAT = saturate(TINT, 1.3);
        const FIRE = wash(SAT, 0.2);
        const HOT = wash(SAT, 0.5);
        const F = inst.from;
        const To = inst.to;
        const t = inst.t;
        const sec = t / 1000;
        const aim = inst.aim;
        const len = Math.hypot(To.x - F.x, To.y - F.y);
        const H = inst.coneH;

        // ---- 喷口闪（caster 层）--------------------------------------------
        const dm = t - T.open;
        if (dm >= 0 && dm < MUZZLE_MS && ctx.caster(inst)) {
          const u = dm / MUZZLE_MS;
          ctx.sprite({
            cell: "flashWhite", x: F.x, y: F.y,
            w: 105, h: 105,
            rot: aim, col: [1, 0.84, 0.52], alpha: Math.pow(1 - u, 1.2),
            hdr: 1.6, bucket: "add",
          });
        }

        // ---- 火流本体（path 层）--------------------------------------------
        if (t >= T.open && t <= T.impact + CONE_TAIL && len > 1 && ctx.path(inst)) {
          const flow = clamp((t - T.open) / FLOW_MS, 0, 1);
          const front = easeOut(flow) * CONE_FRONT;
          const tailK = clamp((t - T.impact) / CONE_TAIL, 0, 1);
          // 接触后按平方收口：火流本体不能压在卡面中央（centerLift）
          const a = (1 - tailK) * (1 - tailK) * clamp((t - T.open) / 40, 0, 1);
          const W = len;

          if (a > 0.02) {
            const reach = Math.min(front, 1) * W;
            ctx.mark(F.x, F.y, F.x + Math.cos(aim) * reach, F.y + Math.sin(aim) * reach);
            const smokeFront =
              easeOut(clamp((t - T.open - SMOKE_LAG) / FLOW_MS, 0, 1)) * CONE_FRONT;
            if (smokeFront > 0.01)
              ctx.spriteFlow({
                cell: "breathStream", x: F.x, y: F.y,
                w: W, h: H * SMOKE_K, ax: 0, rot: aim,
                col: SMOKE_COL, alpha: 0.5 * a,
                revealU: smokeFront, softU: 0.18, bucket: "smoke",
              });

            ctx.spriteFlow({
              cell: "breathStream", x: F.x, y: F.y, w: W, h: H, ax: 0, rot: aim,
              col: FIRE, alpha: a, hdr: 1.5,
              revealU: front, softU: 0.14,
              uvDistort: 0.022,
              scrollU: 0.5, seconds: sec, bucket: "body",
            });

            const tiles = [
              { speed: 1.6, alpha: 0.55, flip: false },
              { speed: 2.3, alpha: 0.4, flip: true },
            ];
            for (let i = 0; i < 2; i++) {
              const q = tiles[i];
              ctx.spriteFlow({
                cell: "breathTile", x: F.x, y: F.y,
                w: W, h: H * TILE_H, ax: 0, rot: aim,
                col: FIRE, alpha: q.alpha * a, hdr: 1.3,
                revealU: front, softU: 0.14, uvDistort: 0.016,
                scrollU: q.speed, seconds: sec + inst.tilePhase[i] * 4,
                coneSoft: 0.25, flipX: q.flip, bucket: "add",
              });
            }

            ctx.spriteFlow({
              cell: "breathStream", x: F.x, y: F.y,
              w: W * CORE_K, h: H * CORE_K, ax: 0, rot: aim,
              col: [1, 0.93, 0.72], alpha: a,
              hdr: 2.0, revealU: Math.min(front / CORE_K, CONE_FRONT),
              softU: 0.12, scrollU: 1.1, seconds: sec, bucket: "add",
            });

            if (t < T.impact) {
              const s = Math.min(front, 1);
              const breathe = 0.25 + 0.15 * (0.5 - 0.5 * Math.cos((t / HEAD_MS) * Math.PI * 2));
              const d = Math.min(breathe * SCORCH_D * 1.4, H * CONE_BAND);
              ctx.flipbook({
                cell: "fireFb",
                x: lerp(F.x, To.x, s), y: lerp(F.y, To.y, s),
                w: d, h: d, rot: inst.headRot + sec * 0.6,
                frame: (t / HEAD_MS) * 16,
                col: FIRE, alpha: 0.85 * a, hdr: 1.5,
                uvDistort: 0.02, seconds: sec, bucket: "add",
              });
            }
          }
          ctx.distort({
            x: lerp(F.x, To.x, Math.min(front, 1) * 0.6),
            y: lerp(F.y, To.y, Math.min(front, 1) * 0.6),
            w: len * 0.9, h: H * 0.5, rot: aim,
            kind: 1, strength: 0.7 * (1 - tailK), seconds: sec,
          });
        }

        // ---- 目标处：焦灼爆散 + 暖色辉光 + 放射火星（接触层）----------------
        const dt2 = t - T.impact;
        if (dt2 >= 0 && ctx.contact(inst)) {
          const kf = dt2 / (3 * FIXED_DT);
          if (kf <= 1) {
            const a = 1 - kf * kf;
            ctx.soft(To.x, To.y, 300, SAT, a * 0.42, { falloff: 2.2, core: 0.25 });
          }
          const ksc = dt2 / SCORCH_MS;
          if (ksc < 1) {
            const d = lerp(0.6, 1.3, easeOut(ksc)) * SCORCH_D;
            ctx.sprite({
              cell: "breathScorch", x: To.x, y: To.y, w: d, h: d,
              rot: inst.scorchRot, col: FIRE, alpha: Math.pow(1 - ksc, 1.2),
              hdr: 1.6, seconds: sec, bucket: "add", core: 0.25,
            });
          }
          const ke = dt2 / EMBER_MS;
          if (ke < 1)
            ctx.sprite({
              cell: "embers", x: To.x, y: To.y,
              w: (0.5 + 0.7 * ke) * EMBER_D, h: (0.5 + 0.7 * ke) * EMBER_D,
              rot: inst.emberRot, col: HOT, alpha: Math.pow(1 - ke, 1.2),
              hdr: 1.1, bucket: "add", core: 0.25,
            });
          strikeDistort(ctx, To.x, To.y, aim, SCORCH_D,
            0.7 * Math.pow(clamp(1 - dt2 / 200, 0, 1), 1.2));
        }
      },
    };
  }

  // ============================================================ 冰枪（frost）
  //
  // 直线冰枪投射物 + 命中冰晶炸开 + 霜环。"晶体感"来自三件事：
  //   ① 枪体是**两端收尖的棱形**，边缘 edgeSoft 压到 0.02（硬切），不加噪声
  //   ② 主枪两侧各一片更短更薄的平行碎晶，读出"一束晶体"而不是一根光棒
  //   ③ 命中炸开的是**带角的碎片**（拉长的硬点），不是圆火星
  require_frost();

  function require_frost() {
    // 冰棱 Ribbon（头尖尾 fade）从施法者飞到目标 → frost-burst 16 帧炸开 → 碎冰粒子。
    //
    // V2（2026-09-17）：
    //   · 补一段施法闪（自然时间 0 → 100）：施法者卡上一点冷白凝结。旧版冰枪第 0 帧
    //     就在飞，castFlash 120ms 里什么都没有；
    //   · 卡面结霜残留（frost-field 末段帧、400ms、body 桶）删掉 —— 原则 5，像"冻结"状态；
    //   · 删掉：顿帧、震屏、推镜、闪帧。
    const T = { flash: 100, impact: 270, release: 300 };
    const FLIGHT = T.impact - T.flash;
    const ICE = [0.58, 0.9, 1.0];
    const LANCE_LEN = 0.48;
    const LANCE_HW = 24;
    const BURST_MS = 300;
    const BURST_D = 380;

    SKILLS.frost = {
      label: "冰枪",
      nat: { launch: T.flash, impact: T.impact, end: T.impact + T.release },
      extent: 365,
      castExtent: 150,

      post: {
        bloom1: [
          { t: 0, v: 0.3 }, { t: T.impact - 8, v: 0.34 },
          { t: T.impact + 6, v: 0.46 }, { t: T.impact + 200, v: 0.33 },
          { t: T.impact + T.release, v: 0.3 },
        ],
        bloom2: [{ t: 0, v: 0.14 }],
        distort: [
          { t: 0, v: 0 }, { t: T.impact - 6, v: 5 },
          { t: T.impact + 4, v: 20 }, { t: T.impact + 200, v: 6 },
          { t: T.impact + T.release, v: 0 },
        ],
      },

      init(inst) {
        inst.aim = Math.atan2(inst.to.y - inst.from.y, inst.to.x - inst.from.x);
        inst.burstRot = inst.rng() * Math.PI * 2;
      },

      update(inst, ctx) {
        const To = inst.to;
        ctx.contact(inst);
        // 碎冰：命中那一下崩出去的一批薄片，每片死亡时再裂成 2 粒细屑
        ctx.spawn(inst, {
          key: "shards", burst: 14, at: T.impact, from: To, jitter: 20,
          angle: [0, Math.PI * 2], speed: [160, 380],
          life: [180, 300], size: [9, 16],
          make(e) {
            e.vy *= 0.78;
            e.gy = 900; e.drag = 2.4;
            e.s1 = 3; e.sExp = 1.4; e.stretch = 2.6;
            e.c0 = [1, 1, 1]; e.c1 = [0.52, 0.84, 1.0];
            e.a0 = 0.95; e.a1 = 0; e.fadeIn = 0.02; e.alignVel = true;
            e.mode = M.SOFT; e.p0 = [M.SOFT, 4.6, 0, 0];
            e.child = {
              count: 2, inherit: 0.35,
              make(c, r) {
                c.vx += (r() - 0.5) * 140; c.vy += (r() - 0.5) * 140 - 40;
                c.gy = 1100; c.drag = 2.6; c.life = 120 + r() * 100;
                c.s0 = 5 + r() * 4; c.s1 = 1.5; c.sExp = 1.4; c.stretch = 1.8;
                c.c0 = [0.92, 0.98, 1]; c.c1 = [0.4, 0.7, 0.95];
                c.a0 = 0.8; c.a1 = 0; c.fadeIn = 0.02; c.alignVel = true;
                c.mode = M.SOFT; c.p0 = [M.SOFT, 5.0, 0, 0];
              },
            };
          },
        });
      },

      draw(inst, ctx) {
        const TINT = inst.tint || ICE;
        const SAT = saturate(TINT, 1.35);
        const GRAD = inst.tintGrad == null ? G.FROST : inst.tintGrad;
        const F = inst.from;
        const To = inst.to;
        const t = inst.t;
        const sec = t / 1000;
        const aim = inst.aim;
        const P = inst.kp;

        // ---- 施法闪：施法者卡上一点冷白凝结（caster 层）---------------------
        if (t < T.flash + 60 && ctx.caster(inst)) {
          const u = clamp(t / T.flash, 0, 1);
          const out = clamp((t - T.flash) / 60, 0, 1);
          const a = Math.min(1, t / 40) * (1 - out);
          ctx.soft(F.x, F.y, 90 + 60 * easeOut(u), SAT, 0.5 * a, { falloff: 2.4 });
          ctx.sprite({
            cell: "flashWhite", x: F.x, y: F.y, w: 60 + 50 * easeOut(u), h: 60 + 50 * easeOut(u),
            rot: aim + u * 1.2, col: wash(SAT, 0.5), alpha: 0.9 * a, hdr: 1.3, bucket: "add",
          });
        }

        // ---- 飞行：一根冰棱 Ribbon（path 层）---------------------------------
        if (t >= T.flash && t <= T.impact && ctx.path(inst)) {
          const u = clamp((t - T.flash) / FLIGHT, 0, 1);
          const head = easeOut(u);
          const tail = Math.max(0, head - LANCE_LEN);
          const HW = LANCE_HW * P;
          const pts = bowPath(F, To, tail, Math.max(head, 0.02), 12, 0,
            (k) => HW * (k < 0.78 ? 0.18 + 1.05 * k : (1 - k) / 0.22 * 1.0));
          const a = Math.min(1, (t - T.flash) / 30 + 0.2);
          ctx.ribbon(pts, {
            cell: "swordRibbon", grad: GRAD, gradLo: 0.12,
            col: SAT, alpha: a, hdr: 1.5,
            fadeHead: 0.05, fadeTail: 0.30,
            uvDistort: 0.012, seconds: sec, bucket: "add",
          });
          const hp = pts[pts.length - 1];
          ctx.soft(hp.x, hp.y, 70 * P, [1, 1, 1], a, { falloff: 4.5 });
          ctx.distort({
            x: hp.x, y: hp.y, w: 150 * P, kind: 2, strength: 0.4 * a,
            dirX: Math.cos(aim), dirY: Math.sin(aim),
          });
        }

        // ---- 命中：frost-burst 16 帧（接触层）--------------------------------
        const dt2 = t - T.impact;
        if (dt2 >= 0 && ctx.contact(inst)) {
          if (dt2 < BURST_MS) {
            const u = dt2 / BURST_MS;
            ctx.flipbook({
              cell: "frostBurst", x: To.x, y: To.y,
              w: BURST_D, h: BURST_D, rot: inst.burstRot,
              frame: u * 16, grad: GRAD, gradLo: 0.06,
              alpha: u < 0.7 ? 1 : Math.pow(1 - (u - 0.7) / 0.3, 1.3),
              hdr: 1.6, uvDistort: 0.01, seconds: sec, bucket: "add", core: 0.25,
            });
          }
          strikeDistort(ctx, To.x, To.y, aim, BURST_D,
            0.7 * Math.pow(clamp(1 - dt2 / 170, 0, 1), 1.2));
        }
      },
    };
  }

  // ====================================================== 群体霜原（frost-field）
  //
  // 地面霜环扩张（共用 shockBand）+ **每个目标处冰晶竖起**。
  // 目标点由接入层通过 cast 的 points 传进来（castFx2 里的 effectTargets），
  // 没传就退化成只在 to 处竖一丛。
  require_frost_field();

  function require_frost_field() {
    // V2（2026-09-17）：群体霜原拆成"每个目标一个实例"，时序由 plan 的群体规则给
    // （施法闪 120 → 由近及远每目标错开 45ms）。
    //   领头实例  施法闪（caster 层）+ 地面冰原与冷色环（ground 层，外包 ≤ 全部目标
    //             并集外扩 aoePad，不再是"bbox 跨度 + 300px"）
    //   每个实例  施法者 → 目标的短冰线（path 层）+ 小号 frost-burst 与冰屑（contact 层）
    // 删掉：每点 700ms 的地面冷光残留、顿帧 100ms、震屏 amp 14、推镜、径向模糊、色散、闪帧。
    const T = { flash: 100, impact: 260, release: 400 };
    const SPREAD_MS = 160;
    const HOLD_MS = 100;
    const CRACK_MS = 140;
    const SHEET_ALPHA = 0.15; // 冰壳压在卡面上方的透明度上限
    const BURST_MS = 300;
    const BURST_D = 300;
    const LINK_HW = 14;

    SKILLS["frost-field"] = {
      label: "霜原",
      nat: { launch: T.flash, impact: T.impact, end: T.impact + T.release },
      extent: 295,
      castExtent: 160,

      post: {
        bloom1: [
          { t: 0, v: 0.3 }, { t: T.impact - 80, v: 0.34 },
          { t: T.impact + 6, v: 0.48 }, { t: T.impact + 300, v: 0.33 },
          { t: T.impact + T.release, v: 0.3 },
        ],
        bloom2: [{ t: 0, v: 0.14 }],
        distort: [
          { t: 0, v: 0 }, { t: T.impact - 40, v: 8 },
          { t: T.impact + 4, v: 24 }, { t: T.impact + 300, v: 6 },
          { t: T.impact + T.release, v: 0 },
        ],
      },

      init(inst) {
        inst.aim = Math.atan2(inst.to.y - inst.from.y, inst.to.x - inst.from.x);
        inst.burstRot = inst.rng() * Math.PI * 2;
        inst.fieldFlip = inst.rng() < 0.5;
        // 外扩 aoePad 是逐轴的上限，bloom 的淡边也算在里面，所以实际画的地面再收 GROUND_BLEED
        const pad = timing().aoePad - GROUND_BLEED;
        const u = inst.union || inst.toBox;
        inst.ground = { x: u.x, y: u.y, w: u.w + 2 * pad, h: u.h + 2 * pad };
      },

      update(inst, ctx) {
        const rng = inst.rng;
        const To = inst.to;
        ctx.contact(inst);
        ctx.once(inst, "burst", T.impact, () => {
          for (let i = 0; i < 8; i++) {
            const a = -Math.PI / 2 + (rng() - 0.5) * 2.4;
            const sp = 100 + rng() * 180;
            ctx.particles.emit({
              x: To.x + (rng() - 0.5) * 60, y: To.y + 20,
              vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
              gy: 700, drag: 2.2, life: 240 + rng() * 120,
              s0: 5 + rng() * 6, s1: 3, sExp: 1.3, stretch: 2.2,
              c0: [1, 1, 1], c1: [0.5, 0.82, 1.0],
              a0: 0.9, a1: 0, fadeIn: 0.03, alignVel: true,
              mode: M.SOFT, p0: [M.SOFT, 6.0, 0, 0],
            });
          }
        });
      },

      draw(inst, ctx) {
        const TINT = inst.tint || [0.58, 0.9, 1.0];
        const SAT = saturate(TINT, 1.3);
        const GRAD = inst.tintGrad == null ? G.FROST : inst.tintGrad;
        const t = inst.t;
        const sec = t / 1000;
        const F = inst.from;
        const To = inst.to;
        const dt2 = t - T.impact;
        const Gd = inst.ground;

        // ---- 施法闪（caster 层，只有领头实例画）------------------------------
        if (t < T.flash + 60 && ctx.caster(inst)) {
          const u = clamp(t / T.flash, 0, 1);
          const a = Math.min(1, t / 40) * (1 - clamp((t - T.flash) / 60, 0, 1));
          ctx.soft(F.x, F.y, 100 + 60 * easeOut(u), SAT, 0.5 * a, { falloff: 2.4 });
          ctx.sprite({
            cell: "flashWhite", x: F.x, y: F.y, w: 70 + 50 * easeOut(u), h: 70 + 50 * easeOut(u),
            rot: u * 1.2, col: wash(SAT, 0.5), alpha: 0.9 * a, hdr: 1.3, bucket: "add",
          });
        }

        // ---- 地面：冰原 + 冷色环，外包 = 目标并集 + aoePad（ground 层）--------
        if (ctx.ground(inst)) {
          if (t >= T.flash && t < T.impact) {
            const u = clamp((t - T.flash) / (T.impact - T.flash), 0, 1);
            ctx.soft(Gd.x, Gd.y, Gd.w, SAT, 0.05 + 0.12 * u, {
              h: Gd.h, bucket: "ground", falloff: 3.0,
            });
          }
          // 冰壳本体（frost-field 序列帧）铺满并集 + 外扩，但压在卡面上方的那一层透明度
          // ≤ SHEET_ALPHA —— 整张冰壳满不透明时会把卡面刷白（centerLift 0.40）。亮的冰只
          // 出现在卡与卡之间的缝和并集外沿一圈（下面两段 Ribbon），卡面插画读得出来。
          const span = SPREAD_MS + HOLD_MS + CRACK_MS;
          const fade = dt2 < span - 100 ? 1 : Math.pow(clamp(1 - (dt2 - (span - 100)) / 100, 0, 1), 1.2);
          if (dt2 >= 0 && dt2 <= span) {
            let frame;
            if (dt2 < SPREAD_MS) frame = (dt2 / SPREAD_MS) * 9;
            else if (dt2 < SPREAD_MS + HOLD_MS) frame = 9 + ((dt2 - SPREAD_MS) / HOLD_MS) * 3;
            else frame = 12 + ((dt2 - SPREAD_MS - HOLD_MS) / CRACK_MS) * 3.9;
            ctx.flipbook({
              cell: "frostField", x: Gd.x, y: Gd.y,
              w: inst.fieldFlip ? -Gd.w : Gd.w, h: Gd.h,
              frame, grad: GRAD, gradLo: 0.08,
              alpha: SHEET_ALPHA * fade,
              hdr: 1.0, uvDistort: 0.01, seconds: sec, bucket: "add",
            });
            const grow = easeOut(clamp(dt2 / SPREAD_MS, 0, 1));
            // 外沿：沿并集外框（外扩带的中线）一圈冰棱
            const U = inst.union;
            const m = (Gd.w - U.w) / 4;
            const x0 = U.x - U.w / 2 - m, x1 = U.x + U.w / 2 + m;
            const y0 = U.y - U.h / 2 - m, y1 = U.y + U.h / 2 + m;
            const rim = [];
            const edge = (ax, ay, bx, by, n) => {
              for (let q = 0; q < n; q++) rim.push({ x: lerp(ax, bx, q / n), y: lerp(ay, by, q / n), hw: m * grow });
            };
            edge(x0, y0, x1, y0, 12); edge(x1, y0, x1, y1, 4);
            edge(x1, y1, x0, y1, 12); edge(x0, y1, x0, y0, 4);
            rim.push(Object.assign({}, rim[0]));
            ctx.ribbon(rim, {
              cell: "swordRibbon", grad: GRAD, gradLo: 0.14, col: SAT, closed: true,
              fadeHead: 0, fadeTail: 0, tile: 6, alpha: 0.9 * fade, hdr: 1.3,
              uvDistort: 0.016, seconds: sec, bucket: "add",
            });
            // 卡缝：同一排相邻两张卡之间的空隙里竖一条冰棱，宽度不超过缝本身
            const row = (inst.targets || []).slice().sort((a, b) => a.x - b.x);
            for (let q = 0; q + 1 < row.length; q++) {
              const a = row[q], b = row[q + 1];
              if (Math.abs(a.y - b.y) > Math.min(a.h, b.h) / 2) continue;
              const gap = (b.x - b.w / 2) - (a.x + a.w / 2);
              if (!(gap > 2)) continue;
              const gx = (a.x + a.w / 2 + b.x - b.w / 2) / 2;
              const top = Math.max(a.y - a.h / 2, b.y - b.h / 2) - m;
              const bot = Math.min(a.y + a.h / 2, b.y + b.h / 2) + m;
              const len = (bot - top) * grow;
              const mid = (top + bot) / 2;
              ctx.ribbon([
                { x: gx, y: mid - len / 2, hw: gap / 2 },
                { x: gx, y: mid, hw: gap / 2 },
                { x: gx, y: mid + len / 2, hw: gap / 2 },
              ], {
                cell: "swordRibbon", grad: GRAD, gradLo: 0.14, col: SAT,
                fadeHead: 0.2, fadeTail: 0.2, alpha: 0.9 * fade, hdr: 1.3,
                uvDistort: 0.016, seconds: sec + q, bucket: "add",
              });
            }
          }
        }

        // ---- 施法者 → 目标的短冰线（path 层）---------------------------------
        if (t >= T.flash && t <= T.impact + 60 && ctx.path(inst)) {
          const u = clamp((t - T.flash) / (T.impact - T.flash), 0, 1);
          const head = easeOut(u);
          const tail = Math.max(0, head - 0.5);
          const fade = 1 - clamp((t - T.impact) / 60, 0, 1);
          const HW = LINK_HW * inst.kp;
          ctx.ribbon(bowPath(F, To, tail, Math.max(head, 0.02), 10, 0,
            (k) => HW * (k < 0.8 ? 0.2 + k : (1 - k) / 0.2)), {
            cell: "swordRibbon", grad: GRAD, gradLo: 0.12, col: SAT,
            alpha: 0.9 * fade, hdr: 1.4, fadeHead: 0.05, fadeTail: 0.35,
            uvDistort: 0.012, seconds: sec, bucket: "add",
          });
        }

        // ---- 目标处：小号 frost-burst（contact 层）---------------------------
        if (dt2 >= 0 && ctx.contact(inst)) {
          const kb = dt2 / BURST_MS;
          if (kb < 1) {
            ctx.flipbook({
              cell: "frostBurst", x: To.x, y: To.y, w: BURST_D, h: BURST_D, rot: inst.burstRot,
              frame: kb * 16, grad: GRAD, gradLo: 0.06,
              alpha: kb < 0.7 ? 1 : Math.pow(1 - (kb - 0.7) / 0.3, 1.3),
              hdr: 1.6, uvDistort: 0.012, seconds: sec, bucket: "add", core: 0.16,
            });
          }
        }
      },
    };
  }

  // ============================================================ 圣光（holy）
  //
  // 光柱从上方落到目标 + 地面光环 + 上升金粒；护盾类（aegis/shield/icebarrier）
  // 额外闪一次六边护盾。群体（rally/muster）由接入层传 points，每个目标各落
  // 一道光柱，震屏与顿帧同步升到"重"档。
  require_holy();

  function require_holy() {
    // V2（2026-09-17）：圣光不再"从天而降"。
    //   施法闪 0 → 120   施法者卡上一团暖金辉光（caster 层）
    //   光束 120 → 300   施法者 → 目标的金色光束（Ribbon，G.HOLY 渐变映射，path 层）
    //   接触 300         目标处**小号**光柱（holy-pillar 序列帧，只取"立住 → 散掉"那一段）
    //                    + 地面金环 + 上升光带 + 上升金粒（contact 层）
    // 群体（rally / muster / absolution）由 cast 拆成每目标一个实例，各自一段短光束。
    // 删掉：落地白盘（380/250/170px 纯白柔光，整卡打白）、620ms 地面金光残留、
    // 护盾穹顶（shield-hex 600ms —— 原则 5，护盾状态由卡面 CSS 接管）、
    // 顿帧、震屏、推镜、闪帧。
    const T = { flash: 120, impact: 300, release: 320 };
    const BEAM_HW = 20;
    const BEAM_TAIL = 50;
    const PILLAR_H = 240;
    const PILLAR_FOOT = 40;
    const PILLAR_F0 = 6;      // 序列帧从第 6 帧（柱头已触地）开始播
    const PILLAR_MS = 300;
    const RING_MS = 260;
    const HEAL_MS = 320;
    const HEAL_D = 220;

    SKILLS.holy = {
      label: "圣光",
      nat: { launch: T.flash, impact: T.impact, end: T.impact + T.release },
      extent: 430,
      castExtent: 180,

      post: {
        bloom1: [
          { t: 0, v: 0.3 }, { t: T.impact - 120, v: 0.36 },
          { t: T.impact + 6, v: 0.5 }, { t: T.impact + 240, v: 0.34 },
          { t: T.impact + T.release, v: 0.3 },
        ],
        bloom2: [{ t: 0, v: 0.14 }],
        distort: [
          { t: 0, v: 0 }, { t: T.impact - 40, v: 6 },
          { t: T.impact + 4, v: 18 }, { t: T.impact + 240, v: 5 },
          { t: T.impact + T.release, v: 0 },
        ],
      },

      init(inst) {
        inst.aim = Math.atan2(inst.to.y - inst.from.y, inst.to.x - inst.from.x);
        inst.bow = (inst.rng() - 0.5) * 0.3;
      },

      update(inst, ctx) {
        const rng = inst.rng;
        const To = inst.to;
        ctx.contact(inst);
        ctx.once(inst, "land", T.impact, () => {
          // 上升金粒：慢、轻、往上飘
          for (let i = 0; i < 10; i++)
            ctx.particles.emit({
              x: To.x + (rng() - 0.5) * 100, y: To.y + 30 + rng() * 30,
              vx: (rng() - 0.5) * 40, vy: -(70 + rng() * 110),
              gy: -30, drag: 0.8, life: 280 + rng() * 120,
              s0: 5 + rng() * 7, s1: 2, sExp: 1.2,
              c0: [1, 1, 0.94], c1: [1, 0.8, 0.36],
              a0: 0.9, a1: 0, fadeIn: 0.18,
              mode: M.SOFT, p0: [M.SOFT, 4.5, 0, 0],
            });
        });
      },

      draw(inst, ctx) {
        const TINT = inst.tint || [1.0, 0.82, 0.42];
        const SAT = saturate(TINT, 1.25);
        const GRAD = inst.tintGrad == null ? G.HOLY : inst.tintGrad;
        const t = inst.t;
        const sec = t / 1000;
        const F = inst.from;
        const To = inst.to;
        const dist = Math.hypot(To.x - F.x, To.y - F.y);
        const dt2 = t - T.impact;

        // ---- 施法闪（caster 层）---------------------------------------------
        if (t < T.flash + 80 && ctx.caster(inst)) {
          const u = clamp(t / T.flash, 0, 1);
          const a = Math.min(1, t / 50) * (1 - clamp((t - T.flash) / 80, 0, 1));
          ctx.soft(F.x, F.y, 130 + 70 * easeOut(u), SAT, 0.45 * a, { falloff: 2.4 });
          ctx.flipbook({
            cell: "healRise", x: F.x, y: F.y + 30, w: 150, h: 150, ay: 0.78,
            frame: u * 6, grad: GRAD, gradLo: 0.05,
            alpha: 0.7 * a, hdr: 1.3, uvDistort: 0.012, seconds: sec, bucket: "add",
          });
        }

        // ---- 光束：施法者 → 目标（path 层）----------------------------------
        if (t >= T.flash && t <= T.impact + BEAM_TAIL && dist > 1 && ctx.path(inst)) {
          const u = clamp((t - T.flash) / (T.impact - T.flash), 0, 1);
          const head = easeOut(u);
          const after = clamp((t - T.impact) / BEAM_TAIL, 0, 1);
          const HW = BEAM_HW * inst.kp;
          const pts = bowPath(F, To, 0, Math.max(head, 0.02), 16, dist * inst.bow * 0.3,
            (k) => HW * (0.45 + 0.55 * k));
          ctx.ribbon(pts, {
            cell: "swordRibbon", grad: GRAD, gradLo: 0.14, col: SAT,
            alpha: Math.min(1, (t - T.flash) / 40 + 0.2) * Math.pow(1 - after, 1.3),
            hdr: 1.5, fadeHead: after > 0 ? 0.02 : 0.1, fadeTail: 0.2, tile: 2,
            scrollU: -1.6, seconds: sec, uvDistort: 0.012, bucket: "add",
          });
          if (after <= 0) {
            const hp = pts[pts.length - 1];
            ctx.soft(hp.x, hp.y, 80 * inst.kp, [1, 0.97, 0.86], 0.8, { falloff: 3.2 });
          }
        }

        if (dt2 < 0) return;
        ctx.contact(inst);

        // ---- 小号光柱：从"柱头触地"那一帧开始，立住 → 散掉 -------------------
        const pu = clamp(dt2 / PILLAR_MS, 0, 1);
        if (pu < 1) {
          ctx.flipbook({
            cell: "holyPillar", x: To.x, y: To.y + PILLAR_FOOT,
            w: PILLAR_H, h: PILLAR_H, ay: 1,
            frame: PILLAR_F0 + pu * (16 - PILLAR_F0), grad: GRAD, gradLo: 0.05,
            alpha: pu < 0.6 ? 1 : Math.pow(1 - (pu - 0.6) / 0.4, 1.3),
            hdr: 1.6, uvDistort: 0.01, seconds: sec, bucket: "add", core: 0.28,
          });
        }

        // ---- 触地：一层暖色辉光（不是白盘）+ 地面金环 -------------------------
        const kf = dt2 / (3 * FIXED_DT);
        if (kf <= 1) ctx.soft(To.x, To.y, 240, SAT, (1 - kf * kf) * 0.4, { falloff: 2.4, core: 0.5 });
        const kr = dt2 / RING_MS;
        if (kr < 1) {
          const rOut = 70 + 80 * Math.pow(clamp(dt2 / 100, 0, 1), 1.4);
          ctx.ring({
            cell: "shockwave", x: To.x, y: To.y + 26,
            r0: Math.max(2, rOut - 36 * lerp(1, 0.35, kr)), r1: rOut,
            squash: GROUND_SQUASH, seg: 52, a0: sec * 0.4, tile: 3,
            grad: GRAD, gradLo: 0.22, col: SAT,
            alpha: 0.9 * Math.pow(1 - kr, 1.8), bucket: "add",
          });
        }

        // ---- 上升光带 heal-rise -----------------------------------------------
        const kh = dt2 / HEAL_MS;
        if (kh <= 1) {
          ctx.flipbook({
            cell: "healRise", x: To.x, y: To.y + 18, w: HEAL_D, h: HEAL_D, ay: 0.78,
            frame: kh * 16, grad: GRAD, gradLo: 0.05,
            alpha: 0.75 * (kh < 0.7 ? 1 : Math.pow(1 - (kh - 0.7) / 0.3, 1.2)),
            hdr: 1.4, uvDistort: 0.012, seconds: sec, bucket: "add", core: 0.4,
          });
        }
      },
    };
  }

  // ============================================================ 自然（nature）
  //
  // 地面绿光炸起 + 叶片碎屑 + 上升藤线。warcry 变体（battlecry）只是把主色
  // 换成 ember 并且走同一套配方 —— 由接入层的 tint/tintGrad 覆盖决定。
  require_nature();

  function require_nature() {
    // V2（2026-09-17）：
    //   施法闪 0 → 100   施法者脚下一圈收拢的绿光（caster 层）
    //   藤线 100 → 240   两条互相缠绕的绿色 Ribbon 从施法者长到目标（path 层）
    //   接触 240         nature-burst 16 帧 + 叶片碎屑（contact 层）；召唤类落点加藤环
    // 删掉：目标处"预兆收拢绿光"（接触前就出现在目标身上，因果倒置）、
    // 620ms 地面绿光残留、叶片 700ms 飘落长尾、顿帧、震屏、推镜、闪帧。
    const T = { flash: 100, impact: 240, release: 320 };
    const BURST_MS = 320;
    const BURST_D = 360;
    const VINE_RING_MS = 280;
    const VINE_HW = 14;

    SKILLS.nature = {
      label: "自然",
      nat: { launch: T.flash, impact: T.impact, end: T.impact + T.release },
      extent: 350,
      castExtent: 200,

      post: {
        bloom1: [
          { t: 0, v: 0.3 }, { t: T.impact - 80, v: 0.34 },
          { t: T.impact + 6, v: 0.46 }, { t: T.impact + 240, v: 0.33 },
          { t: T.impact + T.release, v: 0.3 },
        ],
        bloom2: [{ t: 0, v: 0.14 }],
        distort: [
          { t: 0, v: 0 }, { t: T.impact - 30, v: 6 },
          { t: T.impact + 4, v: 20 }, { t: T.impact + 240, v: 6 },
          { t: T.impact + T.release, v: 0 },
        ],
      },

      init(inst) {
        inst.burstRot = inst.rng() * Math.PI * 2;
        inst.twist = inst.rng() < 0.5 ? -1 : 1;
        // 召唤类（wolves / mooncall …）的 to 与 from 几乎重合
        inst.summonish = Math.hypot(inst.to.x - inst.from.x, inst.to.y - inst.from.y) < 140;
      },

      update(inst, ctx) {
        const rng = inst.rng;
        const To = inst.to;
        ctx.contact(inst);
        ctx.once(inst, "burst", T.impact, () => {
          for (let i = 0; i < 12; i++) {
            const a = -Math.PI / 2 + (rng() - 0.5) * 2.6;
            const sp = 110 + rng() * 180;
            ctx.particles.emit({
              x: To.x + (rng() - 0.5) * 80, y: To.y + 20 + (rng() - 0.5) * 30,
              vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
              gy: 520, drag: 2.8, life: 260 + rng() * 120,
              s0: 16 + rng() * 12, s1: 11, sExp: 1,
              rot: rng() * 6.28, rotVel: (rng() - 0.5) * 9,
              squash: 0.42,
              c0: [0.78, 1.0, 0.6], c1: [0.2, 0.52, 0.18],
              a0: 0.9, a1: 0, fadeIn: 0.05,
              fb: { cell: "natureBurst", loops: 0, lerp: false,
                    frame0: 12 + Math.floor(rng() * 4),
                    grad: G.NATURE, gradLo: 0.08 },
              seed: rng() * 10,
            });
          }
        });
      },

      draw(inst, ctx) {
        const TINT = inst.tint || [0.62, 1.0, 0.54];
        const SAT = saturate(TINT, 1.3);
        const GRAD = inst.tintGrad == null ? G.NATURE : inst.tintGrad;
        const t = inst.t;
        const sec = t / 1000;
        const F = inst.from;
        const To = inst.to;
        const dist = Math.hypot(To.x - F.x, To.y - F.y);
        const dt2 = t - T.impact;

        // ---- 施法闪：施法者脚下一圈收拢的绿光（caster 层）--------------------
        if (t < T.flash + 60 && ctx.caster(inst)) {
          const u = clamp(t / T.flash, 0, 1);
          const a = 1 - clamp((t - T.flash) / 60, 0, 1);
          ctx.soft(F.x, F.y + 20, 240 - 110 * u, SAT, (0.1 + 0.3 * u) * a, {
            bucket: "ground", squash: GROUND_SQUASH, falloff: 3.0,
          });
          ctx.soft(F.x, F.y, 90, [0.9, 1, 0.8], 0.4 * u * a, { falloff: 2.6 });
        }

        // ---- 藤线：两条缠绕的绿带从施法者长到目标（path 层）------------------
        if (t >= T.flash && t <= T.impact + 80 && dist > 8 && ctx.path(inst)) {
          const u = clamp((t - T.flash) / (T.impact - T.flash), 0, 1);
          const head = easeOut(u);
          const fade = 1 - clamp((t - T.impact) / 80, 0, 1);
          const HW = VINE_HW * inst.kp;
          const nx = -(To.y - F.y) / dist;
          const ny = (To.x - F.x) / dist;
          for (let i = 0; i < 2; i++) {
            const sgn = (i ? -1 : 1) * inst.twist;
            const n = 16;
            const pts = new Array(n);
            for (let j = 0; j < n; j++) {
              const s = (j / (n - 1)) * Math.max(head, 0.02);
              const wav = Math.sin(s * Math.PI * 3 + sec * 6) * 18 * inst.kp * Math.sin(Math.PI * s) * sgn;
              pts[j] = {
                x: lerp(F.x, To.x, s) + nx * wav,
                y: lerp(F.y, To.y, s) + ny * wav,
                hw: HW * (0.5 + 0.5 * (j / (n - 1))),
              };
            }
            ctx.ribbon(pts, {
              cell: "swordRibbon", grad: GRAD, gradLo: 0.14, col: SAT,
              alpha: 0.9 * fade * (i ? 0.75 : 1), hdr: 1.4,
              fadeHead: 0.08, fadeTail: 0.2, uvDistort: 0.016, seconds: sec + i * 0.4,
              bucket: "add",
            });
          }
        }

        if (dt2 < 0) return;
        ctx.contact(inst);

        // ---- 主体：nature-burst 16 帧 ------------------------------------------
        const ku = dt2 / BURST_MS;
        if (ku < 1) {
          ctx.flipbook({
            cell: "natureBurst", x: To.x, y: To.y + 10, w: BURST_D, h: BURST_D,
            rot: inst.burstRot,
            frame: ku * 16, grad: GRAD, gradLo: 0.05,
            alpha: ku < 0.7 ? 1 : Math.pow(1 - (ku - 0.7) / 0.3, 1.3),
            hdr: 1.5, uvDistort: 0.014, seconds: sec, bucket: "add",
          });
        }

        // ---- 召唤类落点地面加一圈藤环 -----------------------------------------
        if (inst.summonish) {
          const kr = dt2 / VINE_RING_MS;
          if (kr < 1) {
            const rOut = 70 + 90 * Math.pow(clamp(dt2 / 140, 0, 1), 1.2);
            ctx.ring({
              cell: "shockwave", x: To.x, y: To.y + 30,
              r0: Math.max(2, rOut - 40), r1: rOut,
              squash: GROUND_SQUASH, seg: 48, a0: sec * 0.5, tile: 5,
              grad: GRAD, gradLo: 0.28, col: SAT,
              alpha: 0.85 * Math.pow(1 - kr, 1.7), bucket: "add",
            });
          }
        }
      },
    };
  }

  // ============================================================ 虚空（void）
  //
  // 暗色触须向内收拢 + 紫环坍缩 + 小爆。整条时间线是**朝内**的：
  // 别的技能都是从命中点往外扩，这一个反过来，收到一点再炸开一小下。
  require_void();

  function require_void() {
    // V2（2026-09-17）：虚空的"朝内收拢 → 炸开一小下"保留，但必须有来处。
    //   施法闪 0 → 100   施法者卡上一小团内卷的暗紫漩涡（void-implode 前 4 帧，caster 层）
    //   暗线 100 → 280   施法者 → 目标的暗紫 Ribbon（path 层）
    //   接触 280         void-implode：暗线快到时（−120ms）目标处开始内卷，接触帧（第 9 帧）
    //                    翻成外放的环（contact 层）
    // 删掉：卡面暗紫残留（300ms body 桶 —— 原则 5，像"沉默"状态）、顿帧、震屏、推镜、
    // 局部暗角、闪帧。
    const T = { flash: 100, impact: 280, release: 300 };
    const IMPLODE_MS = 120;
    const EXPLODE_MS = 300;
    const VOID_D = 360;
    const LINK_HW = 18;

    SKILLS.void = {
      label: "虚空",
      nat: { launch: T.flash, impact: T.impact, end: T.impact + T.release },
      extent: 435,
      castExtent: 170,

      post: {
        bloom1: [
          { t: 0, v: 0.3 }, { t: T.impact - 80, v: 0.33 },
          { t: T.impact + 6, v: 0.46 }, { t: T.impact + 240, v: 0.32 },
          { t: T.impact + T.release, v: 0.3 },
        ],
        bloom2: [{ t: 0, v: 0.14 }],
        distort: [
          { t: 0, v: 0 }, { t: T.impact - 60, v: 8 },
          { t: T.impact + 4, v: 22 }, { t: T.impact + 240, v: 6 },
          { t: T.impact + T.release, v: 0 },
        ],
      },

      init(inst) {
        inst.spin = (inst.rng() < 0.5 ? -1 : 1) * (0.9 + inst.rng() * 0.6);
        inst.bow = (inst.rng() - 0.5) * 0.4;
      },

      update(inst, ctx) {
        const rng = inst.rng;
        const To = inst.to;
        ctx.contact(inst);
        ctx.once(inst, "pop", T.impact, () => {
          for (let i = 0; i < 12; i++) {
            const a = rng() * Math.PI * 2;
            const sp = 130 + rng() * 200;
            ctx.particles.emit({
              x: To.x, y: To.y,
              vx: Math.cos(a) * sp, vy: Math.sin(a) * sp * 0.75 - 60,
              gy: 900, drag: 2.8, life: 200 + rng() * 140,
              s0: 6 + rng() * 7, s1: 3, sExp: 1.4, stretch: 2.4,
              c0: [1, 0.96, 1], c1: [0.44, 0.16, 0.7],
              a0: 0.95, a1: 0, fadeIn: 0.02, alignVel: true,
              mode: M.SOFT, p0: [M.SOFT, 4.5, 0, 0],
            });
          }
        });
      },

      draw(inst, ctx) {
        const TINT = inst.tint || [0.6, 0.36, 0.9];
        const SAT = saturate(TINT, 1.3);
        const GRAD = inst.tintGrad == null ? G.VOID : inst.tintGrad;
        const t = inst.t;
        const sec = t / 1000;
        const F = inst.from;
        const To = inst.to;
        const dist = Math.hypot(To.x - F.x, To.y - F.y);
        const dt2 = t - T.impact;

        // ---- 施法闪：内卷的小漩涡（caster 层）--------------------------------
        if (t < T.flash + 60 && ctx.caster(inst)) {
          const u = clamp(t / T.flash, 0, 1);
          const a = Math.min(1, t / 40) * (1 - clamp((t - T.flash) / 60, 0, 1));
          const d = lerp(170, 110, u);
          ctx.flipbook({
            cell: "voidImplode", x: F.x, y: F.y, w: d, h: d, rot: inst.spin * sec,
            frame: u * 4, grad: GRAD, gradLo: 0.06, alpha: a, hdr: 1.4,
            uvDistort: 0.016, seconds: sec, bucket: "add",
          });
        }

        // ---- 暗线：施法者 → 目标（path 层）----------------------------------
        if (t >= T.flash && t <= T.impact + 80 && dist > 1 && ctx.path(inst)) {
          const u = clamp((t - T.flash) / (T.impact - T.flash), 0, 1);
          const head = easeOut(u);
          const tail = Math.max(0, head - 0.7);
          const fade = 1 - clamp((t - T.impact) / 80, 0, 1);
          const HW = LINK_HW * inst.kp;
          ctx.ribbon(bowPath(F, To, tail, Math.max(head, 0.02), 16, dist * inst.bow * 0.25,
            (k) => HW * (0.35 + 0.65 * k)), {
            cell: "swordRibbon", grad: GRAD, gradLo: 0.1, col: SAT,
            alpha: 0.95 * fade, hdr: 1.4, fadeHead: 0.06, fadeTail: 0.3, tile: 2,
            scrollU: -2.2, seconds: sec, uvDistort: 0.02, bucket: "add",
          });
        }

        // ---- void-implode：接触前 120ms 内卷，接触帧翻成外放的环（contact 层）----
        if (dt2 >= -IMPLODE_MS && dt2 < EXPLODE_MS && ctx.contact(inst)) {
          const start = -IMPLODE_MS;
          const frame = dt2 < 0
            ? (1 - dt2 / start) * 8
            : 8 + (dt2 / EXPLODE_MS) * 8;
          const d = (dt2 < 0
            ? lerp(1.1, 0.8, 1 - dt2 / start)
            : lerp(0.8, 1.3, easeOut(dt2 / EXPLODE_MS))) * VOID_D;
          ctx.flipbook({
            cell: "voidImplode", x: To.x, y: To.y, w: d, h: d,
            rot: inst.spin * sec,
            frame, grad: GRAD, gradLo: 0.06,
            alpha: dt2 < 0
              ? Math.min(1, (dt2 - start) / 50)
              : (dt2 / EXPLODE_MS < 0.65 ? 1
                 : Math.pow(1 - (dt2 / EXPLODE_MS - 0.65) / 0.35, 1.3)),
            hdr: 1.5, uvDistort: 0.016, seconds: sec, bucket: "add",
          });
          ctx.distort({
            x: To.x, y: To.y, w: d * 1.05,
            kind: 0, strength: dt2 < 0 ? 0.8 : 1.2 * Math.pow(clamp(1 - dt2 / 180, 0, 1), 1.1),
            ringRadius: dt2 < 0 ? lerp(0.85, 0.35, 1 - dt2 / start) : lerp(0.35, 0.95, clamp(dt2 / 180, 0, 1)),
            ringWidth: 0.14, seconds: sec,
          });
        }
      },
    };
  }

  // ============================================================ 汲取（siphon）
  //
  // 目标 → 施法方的血色光束，束上有**朝施法方跑**的脉冲。方向是这一个技能
  // 唯一重要的事：生命是从目标那边被抽回来的，所以脉冲一律逆着攻击方向跑。
  require_siphon();

  function require_siphon() {
    // V2（2026-09-17）：汲取先"伸出去"再"抽回来"。
    //   施法闪 0 → 90    施法者卡上一点血色辉光（caster 层）
    //   吸取线 90 → 200  施法者 → 目标的一条细血线（path 层）
    //   接触 200         目标处 siphon-orbs（精华被拽出，contact 层）
    //   回流 200 → 520   三条错时 Ribbon 从目标流回施法者 + 施法者处 heal-rise
    //                    （path 层；整段在接触后 residueMaxMs 内收完）
    // 删掉：接触前就挂在目标身上的精华序列帧（因果倒置）、命中白闪星、顿帧、震屏、
    // 推镜、局部暗角、闪帧。
    const T = { flash: 90, impact: 200, release: 320 };
    const BLOOD = [1.0, 0.24, 0.26];
    const ORB_MS = 300;
    const ORB_D = 300;
    const LINK_HW = 12;
    const BEAM_STAGGER = 40;
    const BEAM_HW = 14;
    const BEAM_BOW = 30;
    const BEAM_MS = 260;
    const ARRIVE_MS = 110;
    const HEAL_MS = 200;
    const HEAL_D = 190;

    SKILLS.siphon = {
      label: "汲取",
      nat: { launch: T.flash, impact: T.impact, end: T.impact + T.release },
      extent: 290,
      castExtent: 190,

      post: {
        bloom1: [
          { t: 0, v: 0.3 }, { t: T.flash, v: 0.34 },
          { t: T.impact + 6, v: 0.44 }, { t: T.impact + 240, v: 0.33 },
          { t: T.impact + T.release, v: 0.3 },
        ],
        bloom2: [{ t: 0, v: 0.14 }],
        distort: [
          { t: 0, v: 0 }, { t: T.flash, v: 6 },
          { t: T.impact + 4, v: 18 }, { t: T.impact + 240, v: 5 },
          { t: T.impact + T.release, v: 0 },
        ],
      },

      init(inst) {
        inst.aim = Math.atan2(inst.to.y - inst.from.y, inst.to.x - inst.from.x);
      },

      update(inst, ctx) {
        const rng = inst.rng;
        const To = inst.to;
        ctx.contact(inst);
        ctx.once(inst, "tear", T.impact, () => {
          for (let i = 0; i < 12; i++) {
            const a = inst.aim + Math.PI + (rng() - 0.5) * 2.0;
            const sp = 120 + rng() * 200;
            ctx.particles.emit({
              x: To.x + (rng() - 0.5) * 50, y: To.y + (rng() - 0.5) * 44,
              vx: Math.cos(a) * sp, vy: Math.sin(a) * sp * 0.8 - 60,
              gy: 600, drag: 2.6, life: 220 + rng() * 140,
              s0: 6 + rng() * 6, s1: 3, sExp: 1.4, stretch: 2.2,
              c0: [1, 0.86, 0.86], c1: [0.7, 0.06, 0.12],
              a0: 0.95, a1: 0, fadeIn: 0.03, alignVel: true,
              mode: M.SOFT, p0: [M.SOFT, 4.5, 0, 0],
            });
          }
        });
      },

      draw(inst, ctx) {
        const TINT = inst.tint || BLOOD;
        const SAT = saturate(TINT, 1.3);
        const GRAD = inst.tintGrad == null ? G.BLOOD : inst.tintGrad;
        const F = inst.from;
        const To = inst.to;
        const t = inst.t;
        const sec = t / 1000;
        const aim = inst.aim;
        const dist = Math.hypot(To.x - F.x, To.y - F.y);
        const dt2 = t - T.impact;
        const P = inst.kp;

        // ---- 施法闪（caster 层）---------------------------------------------
        if (t < T.flash + 60 && ctx.caster(inst)) {
          const u = clamp(t / T.flash, 0, 1);
          const a = Math.min(1, t / 40) * (1 - clamp((t - T.flash) / 60, 0, 1));
          ctx.soft(F.x, F.y, 120 + 60 * easeOut(u), SAT, 0.45 * a, { falloff: 2.6 });
        }

        if (dist > 1 && ctx.path(inst)) {
          // ---- 吸取线：施法者 → 目标 -----------------------------------------
          if (t >= T.flash && t <= T.impact + 60) {
            const u = clamp((t - T.flash) / (T.impact - T.flash), 0, 1);
            const fade = 1 - clamp((t - T.impact) / 60, 0, 1);
            ctx.ribbon(bowPath(F, To, 0, Math.max(easeOut(u), 0.02), 14, 0,
              (k) => LINK_HW * P * (0.4 + 0.6 * k)), {
              cell: "swordRibbon", grad: GRAD, gradLo: 0.14, col: SAT,
              alpha: 0.9 * fade, hdr: 1.4, fadeHead: 0.06, fadeTail: 0.2,
              uvDistort: 0.016, seconds: sec, bucket: "add",
            });
          }

          // ---- 回流：目标 → 施法者，三条错时 Ribbon，scrollU 朝施法者 ---------
          for (let i = 0; i < 3; i++) {
            const local = t - T.impact - i * BEAM_STAGGER;
            if (local < 0 || local > BEAM_MS) continue;
            const reach = easeOut(clamp(local / ARRIVE_MS, 0, 1));
            const a = Math.min(1, local / 50) *
              Math.pow(clamp(1 - (local - (BEAM_MS - 90)) / 90, 0, 1), 1.2);
            if (a <= 0.02) continue;
            const HW = BEAM_HW * P * (i === 0 ? 1 : 0.72);
            const bow = (i - 1) * BEAM_BOW * P;
            ctx.ribbon(
              bowPath(To, F, 0, Math.max(reach, 0.02), 16, bow,
                (k) => HW * (0.45 + 0.9 * Math.sin(Math.PI * k))),
              {
                cell: "swordRibbon", grad: GRAD, gradLo: 0.14,
                col: SAT, alpha: a * (i === 0 ? 1 : 0.7), hdr: 1.5,
                fadeHead: 0.14, fadeTail: 0.14, tile: 3,
                scrollU: 1.9 + i * 0.4, seconds: sec + i * 0.31,
                uvDistort: 0.016, bucket: "add",
              });
          }

          // ---- 施法者处：吸回来的那一口 -----------------------------------------
          const kh = (t - T.impact - ARRIVE_MS) / HEAL_MS;
          if (kh >= 0 && kh <= 1) {
            ctx.flipbook({
              cell: "healRise", x: F.x, y: F.y + 16 * P, w: HEAL_D * P, h: HEAL_D * P, ay: 0.78,
              frame: kh * 16, grad: GRAD, gradLo: 0.05,
              alpha: 0.9 * (kh < 0.6 ? 1 : Math.pow(1 - (kh - 0.6) / 0.4, 1.2)),
              hdr: 1.4, uvDistort: 0.012, seconds: sec, bucket: "add",
            });
            ctx.soft(F.x, F.y, 170 * P, SAT, 0.3 * Math.pow(1 - kh, 1.4), { falloff: 2.6 });
          }
        }

        // ---- 目标处：精华被拽出（contact 层）---------------------------------
        if (dt2 >= -20 && ctx.contact(inst)) {
          const ko = (dt2 + 20) / ORB_MS;
          if (ko < 1) {
            ctx.flipbook({
              cell: "siphonOrbs", x: To.x, y: To.y, w: ORB_D, h: ORB_D,
              rot: aim + Math.PI,
              frame: ko * 16, grad: GRAD, gradLo: 0.05,
              alpha: ko < 0.7 ? 1 : Math.pow(1 - (ko - 0.7) / 0.3, 1.2),
              hdr: 1.5, uvDistort: 0.014, seconds: sec, bucket: "add",
            });
          }
          if (dt2 >= 0)
            strikeDistort(ctx, To.x, To.y, aim + Math.PI, ORB_D,
              0.55 * Math.pow(clamp(1 - dt2 / 180, 0, 1), 1.2));
        }
      },
    };
  }

  // ============================================================ 奥术
  require_arcane();

  function require_arcane() {
    // V2（2026-09-17）：
    //   施法闪 0 → 200   施法者卡上一枚小符环（arcane-burst 前 3 帧循环）+ 螺旋汇入**施法者**
    //                    的光点（caster 层；旧版光点汇入的是目标，接触前就出现在目标身上）
    //   奥术线 200 → 320 符环 → 目标的紫色 Ribbon，头上一颗亮点（path 层）
    //   接触 320         arcane-burst 16 帧 + 晶体碎片 + 火花 + 中心辉光（contact 层）
    // 删掉：切入、顿帧、震屏、推镜、色散、局部暗角、闪帧、430ms 余韵辉光长尾。
    const T = { flash: 200, impact: 320, release: 320 };
    const RUNE_D = 170;
    const RUNE_LOOP = 200;
    const BURST_MS = 300;
    const BURST_D = 400;
    const LINK_HW = 16;

    SKILLS.arcane = {
      label: "奥术",
      nat: { launch: T.flash, impact: T.impact, end: T.impact + T.release },
      extent: 445,
      castExtent: 200,

      post: {
        bloom1: [
          { t: 0, v: 0.30 }, { t: 160, v: 0.40 }, { t: T.impact - 10, v: 0.46 },
          { t: T.impact + 6, v: 0.54 }, { t: T.impact + 140, v: 0.40 },
          { t: T.impact + T.release, v: 0.30 },
        ],
        bloom2: [
          { t: 0, v: 0.14 }, { t: T.impact + 6, v: 0.16 },
          { t: T.impact + 180, v: 0.14 },
        ],
        distort: [
          { t: 0, v: 0 }, { t: T.impact - 10, v: 5 },
          { t: T.impact + 4, v: 26 }, { t: T.impact + 160, v: 9 },
          { t: T.impact + T.release, v: 0 },
        ],
      },

      init(inst) {
        inst.aim = Math.atan2(inst.to.y - inst.from.y, inst.to.x - inst.from.x);
        inst.emitAcc = 0;
        inst.spiraled = 0;
        inst.burstRot = inst.rng() * Math.PI * 2;
        inst.bow = (inst.rng() - 0.5) * 0.5;
      },

      update(inst, ctx, dt) {
        const t = inst.t;
        const rng = inst.rng;
        const F = inst.from;
        const To = inst.to;

        // ---- 施法闪：光点沿螺旋汇入施法者 ------------------------------------
        if (t > 20 && t < T.flash && inst.spiraled < 18 && ctx.caster(inst)) {
          inst.emitAcc += dt;
          while (inst.emitAcc >= 10 && inst.spiraled < 18) {
            inst.emitAcc -= 10;
            inst.spiraled += 1;
            ctx.particles.emit({
              x: F.x, y: F.y, life: 160 + rng() * 80,
              s0: 12 + rng() * 8, s1: 3, sExp: 1.5,
              c0: [0.80, 0.50, 1.0], c1: [0.96, 0.88, 1.0],
              a0: 0.95, a1: 0.25, fadeIn: 0.18,
              mode: M.SOFT, p0: [M.SOFT, 1.9, 0, 0],
              orbit: {
                ox: F.x, oy: F.y, r0: 110 + rng() * 50, r1: 10,
                a0: rng() * Math.PI * 2,
                spin: (2.2 + rng() * 1.4),
                squash: GROUND_SQUASH,
              },
            });
          }
        }

        // ---- 爆发：晶体碎片 + 火花（contact 层）------------------------------
        ctx.contact(inst);
        ctx.once(inst, "boom", T.impact, () => {
          for (let i = 0; i < 10; i++) {
            const a = (i / 10) * Math.PI * 2 + rng() * 0.4;
            const sp = 160 + rng() * 200;
            ctx.particles.emit({
              x: To.x + Math.cos(a) * 60, y: To.y + Math.sin(a) * 44,
              vx: Math.cos(a) * sp, vy: Math.sin(a) * sp * 0.62 - 120,
              gy: 640, drag: 2.0, life: 260 + rng() * 120,
              s0: 18 + rng() * 10, s1: 6, sExp: 1.2,
              c0: [1, 1, 1], c1: [1, 1, 1], a0: 0.95, a1: 0,
              rot: rng() * 6.28, rotVel: (rng() - 0.5) * 6,
              mode: M.SHAPE,
              p0: [M.SHAPE, 3, 0.12, G.ARCANE],
              p1: [0.04, 0, 0.78, 0],
            });
          }
          for (let i = 0; i < 16; i++) {
            const a = (i / 16) * Math.PI * 2 + rng() * 0.3;
            const sp = 240 + rng() * 300;
            ctx.particles.emit({
              x: To.x, y: To.y,
              vx: Math.cos(a) * sp, vy: Math.sin(a) * sp * 0.66 - 60,
              gy: 760, drag: 3.2, life: 180 + rng() * 140,
              s0: 16 + rng() * 12, s1: 5, sExp: 1.5, stretch: 4.0,
              c0: [0.97, 0.90, 1.0], c1: [0.56, 0.22, 0.98],
              a0: 1, a1: 0, fadeIn: 0.02, alignVel: true,
              mode: M.SOFT, p0: [M.SOFT, 3.2, 0, 0],
            });
          }
        });
      },

      draw(inst, ctx) {
        const TINT = inst.tint || [0.78, 0.54, 1.0];
        const SAT = saturate(TINT, 1.28);
        const GRAD = inst.tintGrad == null ? G.ARCANE : inst.tintGrad;
        const F = inst.from;
        const To = inst.to;
        const t = inst.t;
        const sec = t / 1000;
        const dist = Math.hypot(To.x - F.x, To.y - F.y);

        // ---- 施法闪：施法者卡上一枚小符环（caster 层）-----------------------
        if (t < T.impact && ctx.caster(inst)) {
          const a = Math.min(1, t / 60) *
            Math.pow(clamp(1 - (t - (T.flash - 20)) / 100, 0, 1), 1.0);
          if (a > 0.02) {
            ctx.flipbook({
              cell: "arcaneBurst", x: F.x, y: F.y, w: RUNE_D, h: RUNE_D,
              rot: sec * 0.9,
              frame: (t % RUNE_LOOP) / RUNE_LOOP * 3,
              grad: GRAD, gradLo: 0.06, alpha: a, hdr: 1.4,
              uvDistort: 0.01, seconds: sec, bucket: "add",
            });
          }
        }

        // ---- 奥术线：施法者 → 目标（path 层）-------------------------------
        if (t >= T.flash && t <= T.impact + 70 && dist > 1 && ctx.path(inst)) {
          const u = clamp((t - T.flash) / (T.impact - T.flash), 0, 1);
          const head = easeOut(u);
          const tail = Math.max(0, head - 0.6);
          const fade = 1 - clamp((t - T.impact) / 70, 0, 1);
          const HW = LINK_HW * inst.kp;
          const pts = bowPath(F, To, tail, Math.max(head, 0.02), 16, dist * inst.bow * 0.3,
            (k) => HW * (0.3 + 0.7 * k));
          ctx.ribbon(pts, {
            cell: "swordRibbon", grad: GRAD, gradLo: 0.12, col: SAT,
            alpha: 0.95 * fade, hdr: 1.5, fadeHead: 0.05, fadeTail: 0.35,
            uvDistort: 0.014, seconds: sec, bucket: "add",
          });
          if (fade >= 1) {
            const hp = pts[pts.length - 1];
            ctx.soft(hp.x, hp.y, 70 * inst.kp, [0.96, 0.9, 1], 0.9, { falloff: 3.2 });
          }
        }

        // ---- 爆发：arcane-burst 16 帧（contact 层）---------------------------
        const dt2 = t - T.impact;
        if (dt2 >= 0 && ctx.contact(inst)) {
          if (dt2 < BURST_MS) {
            const u = dt2 / BURST_MS;
            ctx.flipbook({
              cell: "arcaneBurst", x: To.x, y: To.y, w: BURST_D, h: BURST_D,
              rot: inst.burstRot + sec * 0.35,
              frame: u * 16, grad: GRAD, gradLo: 0.05,
              alpha: u < 0.7 ? 1 : Math.pow(1 - (u - 0.7) / 0.3, 1.3),
              hdr: 1.7, uvDistort: 0.014, seconds: sec, bucket: "add", core: 0.28,
            });
            ctx.distort({
              x: To.x, y: To.y, w: BURST_D * 1.05, kind: 0,
              strength: 1.1 * Math.pow(clamp(1 - u * 3, 0, 1), 1.1),
              ringRadius: lerp(0.25, 0.9, clamp(u * 3, 0, 1)), ringWidth: 0.13,
              seconds: sec,
            });
          }
          const kg = dt2 / T.release;
          if (kg <= 1)
            ctx.soft(To.x, To.y, 220, SAT, Math.pow(1 - kg, 1.6) * 0.34, { falloff: 2.6, core: 0.3 });
        }
      },
    };
  }

  // ============================================================ 剑气（bladeCross）
  //
  // 移植自 src/presentation/fx-top.js（EmberFxTop，2D 画布，已删除）。原版：深蓝墨色
  // 高等腰三角从天上（目标左上方 1000px）切到目标 → 底边与 X 形四臂一体展开 → 一起
  // 变细消失，落点一圈青光。墨色、四臂的相对角度与长度比、变细曲线原样保留。
  //
  // V2 的改动只有"从哪来"和"多大"：
  //   · 三角的尖端钉在**施法者卡心**（原版钉在天上），底边中心从施法者一侧切到目标卡心 ——
  //     这一整道剑气就是 path 层，从施法者卡面出发、终点在目标卡面；
  //   · 底边宽度 ≤ 目标卡宽，底边方向垂直于攻击方向（原版固定 −24°，那是为天降角度配的）；
  //   · X 四臂、命中闪光、落点青光与方形碎屑在 contact 层，整体按目标卡缩放；
  //   · 原版命中那一下的纯白柔光盘（500px，整卡打白）换成青色；
  //   · 顿帧 40 / 震屏 8 / 全屏闪帧 0.42 删掉（impulse 接管）。
  require_blade_cross();

  function require_blade_cross() {
    const T = { flash: 120, impact: 260, hold: 40, thin: 340 };
    const CUT = T.impact - T.flash;
    const INK = [0.03, 0.07, 0.3];
    const GLOW = [0.4, 0.8, 1.0];
    const BASE_W = 190;
    // X 四臂的相对长度（原版 370 / 290 / 240 / 170 的比例）与宽度（占卡短边）
    const ARM_LEN = [1, 0.84, 0.72, 0.52];
    const ARM_W = [0.07, 0.065, 0.065, 0.05];
    const ARM_ALPHA = 0.85;

    /** 施法者 → 目标卡心这条线穿出目标卡边框的那一点。剑身只画到这里，不压卡面。 */
    function edgePoint(inst) {
      const b = inst.toBox;
      const dx = inst.from.x - b.x;
      const dy = inst.from.y - b.y;
      const L = Math.hypot(dx, dy) || 1;
      const t = Math.min(
        Math.abs(dx) > 1e-6 ? (b.w / 2) / Math.abs(dx) : Infinity,
        Math.abs(dy) > 1e-6 ? (b.h / 2) / Math.abs(dy) : Infinity,
      );
      const k = Math.min(1, t);
      return { x: b.x + dx * k, y: b.y + dy * k, inside: L * k };
    }

    SKILLS.bladeCross = {
      label: "剑气",
      nat: { launch: T.flash, impact: T.impact, end: T.impact + T.hold + T.thin },
      // X 与辉光在 contactBox 层按预算直接定尺寸；extent 只管碎屑粒子
      extent: 420,
      castExtent: 150,

      post: {
        bloom1: [
          { t: 0, v: 0.3 }, { t: T.impact + 6, v: 0.46 }, { t: T.impact + 200, v: 0.32 },
          { t: T.impact + T.hold + T.thin, v: 0.3 },
        ],
        bloom2: [{ t: 0, v: 0.14 }],
        distort: [{ t: 0, v: 0 }],
      },

      init(inst) {
        const r = inst.rng;
        inst.aim = Math.atan2(inst.to.y - inst.from.y, inst.to.x - inst.from.x);
        inst.baseW = Math.min(BASE_W * inst.kp, 0.55 * inst.toBox.w);
        inst.edge = edgePoint(inst);
        // X 沿目标卡的两条对角线展开。与底边共线的那一对（原版 arms[0] / arms[2]）取
        // 更接近"垂直于攻击方向"的那条对角线；四臂各带一点长度抖动。
        const hx = 0.92 * inst.budgetW / 2;
        const hy = 0.92 * inst.budgetH / 2;
        const perp = inst.aim - Math.PI / 2;
        const d1 = { x: hx, y: hy };
        const d2 = { x: hx, y: -hy };
        const dot = (d) => Math.abs(Math.cos(perp) * d.x + Math.sin(perp) * d.y) / Math.hypot(d.x, d.y);
        const base = dot(d1) >= dot(d2) ? d1 : d2;
        const other = base === d1 ? d2 : d1;
        const jit = () => 0.94 + r() * 0.06;
        inst.arms = [
          { x: base.x, y: base.y, len: ARM_LEN[0] * jit(), w: ARM_W[0] },
          { x: other.x, y: other.y, len: ARM_LEN[1] * jit(), w: ARM_W[1] },
          { x: -base.x, y: -base.y, len: ARM_LEN[2] * jit(), w: ARM_W[2] },
          { x: -other.x, y: -other.y, len: ARM_LEN[3] * jit(), w: ARM_W[3] },
        ];
      },

      update(inst, ctx) {
        const r = inst.rng;
        const To = inst.to;
        ctx.contact(inst);
        ctx.once(inst, "chips", T.impact, () => {
          for (let i = 0; i < 16; i++) {
            const a = r() * Math.PI * 2;
            const sp = 100 + r() * 180;
            ctx.particles.emit({
              x: To.x + (r() - 0.5) * 80, y: To.y + (r() - 0.5) * 30,
              vx: Math.cos(a) * sp, vy: Math.sin(a) * sp * 0.6 - 100 - r() * 80,
              gy: 900, drag: 2.6, life: 240 + r() * 120,
              s0: 7 + r() * 9, s1: 4, sExp: 1, aExp: 4,
              rot: r() * 6.28, rotVel: (r() - 0.5) * 12,
              c0: [0.62, 0.86, 1.0], c1: [0.9, 0.98, 1.0],
              a0: 1, a1: 0, fadeIn: 0.02,
              mode: M.SOFT, p0: [M.SOFT, 9.0, 0, 0],
            });
          }
        });
      },

      draw(inst, ctx) {
        const t = inst.t;
        const F = inst.from;
        const To = inst.to;
        const B = inst.toBox;

        // ---- 施法闪：施法者卡上一点冷白（caster 层）--------------------------
        if (t < T.flash + 60 && ctx.caster(inst)) {
          const u = clamp(t / T.flash, 0, 1);
          const a = Math.min(1, t / 40) * (1 - clamp((t - T.flash) / 60, 0, 1));
          ctx.soft(F.x, F.y, 120 + 60 * easeOut(u), GLOW, 0.5 * a, { falloff: 2.2 });
          ctx.soft(F.x, F.y, 50, [0.9, 0.97, 1], 0.8 * a, { falloff: 3 });
        }

        if (t < T.flash) return;

        const dc = t - T.flash;
        const k = clamp((t - T.impact - T.hold) / T.thin, 0, 1);
        const thick =
          t < T.impact
            ? easeOut(dc / CUT)
            : t < T.impact + T.hold
              ? 1
              : Math.pow(1 - k, 1.8);
        const endFade = 1 - clamp((k - 0.78) / 0.22, 0, 1);
        if (thick <= 0.002 && endFade <= 0.01) return;
        const cutK = easeOut(clamp(dc / CUT, 0, 1));
        const E = inst.edge;
        // 底边中心：从施法者一侧（30% 处）切到**目标卡的外沿**（剑气与卡框的交点）
        const C = { x: lerp(F.x, E.x, 0.3 + 0.7 * cutK), y: lerp(F.y, E.y, 0.3 + 0.7 * cutK) };

        // ---- 三角剑身：尖端在施法者、底边落在目标卡外沿（path 层）------------
        // 剑身不进卡面：卡面上只有接触层的 X（细线沿对角线），插画与数字读得出来。
        if (thick > 0.002 && ctx.path(inst)) {
          ctx.wedge({
            x0: C.x, y0: C.y, hw0: inst.baseW * thick / 2,
            x1: F.x, y1: F.y, hw1: 0,
            col: INK, alpha: 0.97 * endFade, tipFade: 0.04, bucket: "body",
          });
          ctx.mark(F.x, F.y, E.x, E.y);
        }

        if (t < T.impact) return;
        ctx.contactBox(inst);
        const dt2 = t - T.impact;
        const hx = 0.92 * inst.budgetW / 2;
        const hy = 0.92 * inst.budgetH / 2;

        // ---- 命中闪光 + 落点青光：柔光四边形正好是逐轴预算框 ---------------------
        const kf = dt2 / 160;
        if (kf <= 1) {
          ctx.soft(To.x, To.y, 2 * hx, [0.45, 0.8, 1.0],
            Math.pow(1 - kf, 1.4) * 0.55, { h: 2 * hy, falloff: 1.8, core: 0.5 });
          ctx.soft(To.x, To.y, 1.2 * hx, [0.7, 0.9, 1.0],
            Math.pow(1 - kf, 1.2) * 0.4, { h: 1.2 * hy, falloff: 2.2, core: 0.5 });
        }
        ctx.soft(To.x, To.y + 0.1 * hy, 2 * hx, GLOW, 0.3 * endFade, {
          h: 1.6 * hy, bucket: "ground", falloff: 3.0,
        });

        // ---- X 四臂：沿目标卡对角线展开，到预算框的角 -----------------------------
        const grow = easeOutQuint(clamp(dt2 / 160, 0, 1));
        const minSide = Math.min(B.w, B.h);
        for (let i = 0; i < 4; i++) {
          const a = inst.arms[i];
          const L = a.len * (0.25 + 0.75 * grow);
          ctx.wedge({
            x0: To.x, y0: To.y, hw0: a.w * minSide * (0.55 + 0.45 * thick) / 2,
            x1: To.x + a.x * L, y1: To.y + a.y * L, hw1: 0,
            col: INK, alpha: ARM_ALPHA * endFade, bucket: "body",
          });
        }
        ctx.soft(To.x, To.y, (0.3 * thick + 0.12) * minSide, [0.8, 0.95, 1.0],
          0.6 * thick * endFade, { falloff: 4 });
      },
    };
  }

  // ============================================================ 通用接触点（contact）
  //
  // 无来源的伤害（疲劳、亡语、奥秘反制）用它：命中序列帧 + 一小把火花，按 at 包围盒缩放。
  require_contact();

  function require_contact() {
    const T = { impact: 0, release: 260 };
    SKILLS.contact = {
      label: "接触点",
      nat: { launch: 0, impact: T.impact, end: T.release },
      extent: 270,
      castExtent: 150,
      post: {
        bloom1: [{ t: 0, v: 0.4 }, { t: T.release, v: 0.3 }],
        bloom2: [{ t: 0, v: 0.14 }],
        distort: [{ t: 0, v: 10 }, { t: 160, v: 0 }],
      },
      init(inst) {
        inst.hitRot = inst.rng() * Math.PI * 2;
      },
      update(inst, ctx) {
        const rng = inst.rng;
        const To = inst.to;
        const TINT = inst.tint || [1, 0.8, 0.5];
        ctx.contact(inst);
        ctx.once(inst, "sparks", 0, () => {
          for (let i = 0; i < 10; i++) {
            const a = rng() * Math.PI * 2;
            const sp = 120 + rng() * 180;
            ctx.particles.emit({
              x: To.x, y: To.y,
              vx: Math.cos(a) * sp, vy: Math.sin(a) * sp * 0.7 - 80,
              gy: 900, drag: 2.6, life: 180 + rng() * 100,
              s0: 6 + rng() * 6, s1: 3, sExp: 1.4, stretch: 2.4,
              c0: [1, 1, 0.96], c1: TINT,
              a0: 0.95, a1: 0, fadeIn: 0.02, alignVel: true,
              mode: M.SOFT, p0: [M.SOFT, 4.0, 0, 0],
            });
          }
        });
      },
      draw(inst, ctx) {
        const TINT = inst.tint || [1, 0.8, 0.5];
        const HOT = wash(saturate(TINT, 1.3), 0.5);
        const To = inst.to;
        ctx.contact(inst);
        strikeImpact(ctx, To.x, To.y, inst.t - T.impact, {
          ms: 240, d: 300, grad: inst.tintGrad, col: HOT, rot: inst.hitRot,
          hdr: 1.3, seconds: inst.t / 1000,
        });
        strikeDistort(ctx, To.x, To.y, 0, 260,
          0.5 * Math.pow(clamp(1 - inst.t / 160, 0, 1), 1.2));
      },
    };
  }

  const SKILL_ORDER = [
    "fireball", "lightning", "slash", "claw", "slam", "arrow", "spear", "bolt",
    "breath", "frost", "frost-field", "holy", "nature", "void", "siphon",
    "arcane", "bladeCross", "contact",
  ];

  // ================================================================ 计划（纯函数）
  //
  // V2 契约 §3.3 / §4.2：导演层用 plan() 安排数字与受击时刻，引擎用**同一份**
  // 计划驱动画面，所以接触帧与 hitAt 天然一致（误差 < 1 帧，见 knotsFor）。
  // plan 不碰 WebGL、不碰 DOM，node 里可以直接 require 测。

  /** 平砍族里默认近战的三族；其余四族（arrow / spear / bolt / breath）默认远程。 */
  const MELEE = Object.freeze({ slash: true, claw: true, slam: true });
  /** cast() 走"弹道"时长（按距离）的技能；其余走"施法闪 + 连线"。 */
  const PROJECTILE = Object.freeze({
    fireball: true, frost: true, arrow: true, spear: true, bolt: true,
  });
  /** 群体技能每个目标那一段短连线的长度（ms）。rank 0 的接触在施法闪末尾。 */
  const GROUP_LINK = 90;
  /** 接触后残留的收尾淡出带（ms）：最后这一段 alpha 从 1 平滑到 0。 */
  const ENV_MS = 80;
  /** 接触画面实际占用 contactBoxMax 预算的比例（留 8% 给量化噪声）。 */
  const CONTACT_FILL = 0.92;
  /** 施法者处的蓄力 / 施法闪最多占施法者卡 max(w,h) 的倍数。 */
  const CAST_FILL = 1.5;
  /** 路径宽度的参照卡高：桌面随从卡 146px。更小的卡（手机）按比例收窄。 */
  const PATH_REF = 146;
  /** 没给 w/h 时的兜底盒（桌面随从卡）。 */
  const DEFAULT_BOX = Object.freeze({ w: 116, h: 146 });
  /** 按档把 HDR 与 bloom 的"推高量"降一级（契约：HDR 与 bloom 的推高按档降一级）。 */
  const HDR_K = [0, 0.45, 0.65, 0.85];
  const BLOOM_K = [0, 0.35, 0.55, 0.75];
  /** 命中核心（命中序列帧、落点闪光、火花扇面、火星）的 alpha 按档再降一级：
   *  接触帧卡面中央的平均亮度提升 ≤ 0.2（tools/fx2-measure.cjs 的 centerLift）。 */
  const CORE_K = [0, 0.25, 0.3, 0.35];
  /** 群体地面层外扩 aoePad 里要给 bloom 的淡边留出的余量（px）。 */
  const GROUND_BLEED = 8;
  const BLOOM_BASE1 = 0.30;
  const BLOOM_BASE2 = 0.16;
  /** 色调压缩拐点：有特效在跑时开，空闲时关（空闲路径根本不进后期链）。 */
  const TONE_ACTIVE = 0.80;
  /** 边缘闪：寿命与各档的加亮量。加亮量 ≤ flashMaxLuma − 1（见 impulse）。 */
  const EDGE_MS = 90;
  const EDGE_AMT = [0, 0.18, 0.24, 0.30];
  /** 推镜（只有 impulse({tier:3, cinematic:true})）。 */
  const PUSH_MS = 320;
  const PUSH_PEAK = 1.04;

  function timing() {
    if (typeof EmberTiming !== "undefined") return EmberTiming;
    if (typeof require === "function") return require("./presentation/timing.js");
    throw new Error("EmberTiming 未加载：src/presentation/timing.js 必须先于 fx2-engine.js");
  }

  /** {x, y, w, h}（x/y 是中心）规范化；缺 w/h 用桌面随从卡兜底。 */
  function toBox(b) {
    if (!b) return null;
    const w = b.w > 0 ? b.w : DEFAULT_BOX.w;
    const h = b.h > 0 ? b.h : DEFAULT_BOX.h;
    const x = Number.isFinite(b.x) ? b.x : Number.isFinite(b.left) ? b.left + w / 2 : 0;
    const y = Number.isFinite(b.y) ? b.y : Number.isFinite(b.top) ? b.top + h / 2 : 0;
    return { x, y, w, h };
  }

  function targetsOf(o, fallback) {
    const list = Array.isArray(o.targets) ? o.targets : o.to ? [o.to] : [];
    const out = list.map(toBox).filter(Boolean);
    return out.length ? out : fallback ? [fallback] : [];
  }

  function unionBox(boxes) {
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    for (const b of boxes) {
      x0 = Math.min(x0, b.x - b.w / 2); x1 = Math.max(x1, b.x + b.w / 2);
      y0 = Math.min(y0, b.y - b.h / 2); y1 = Math.max(y1, b.y + b.h / 2);
    }
    return { x: (x0 + x1) / 2, y: (y0 + y1) / 2, w: x1 - x0, h: y1 - y0 };
  }

  const boxDist = (a, b) => Math.hypot(b.x - a.x, b.y - a.y);

  /**
   * plan(kind, { from, targets, tier, aoe, ranged? }) → { hitAt: number[], duration }
   *
   *   平砍（传了布尔 ranged，或 attack: true）
   *     近战      hitAt = 0（导演层在卡片碰撞那一刻调 attack）
   *     远程      hitAt = 距离 / attack.rangedSpeed，钳到 [rangedMin, rangedMax]
   *   法术
   *     群体      aoe 为真、目标多于一个、或 kind 是 frost-field：
   *               按到 from 的距离由近及远排名 r，
   *               hitAt = spell.castFlash + min(r, staggerSteps) × stagger
   *     单体弹道  hitAt = castFlash + 距离 / spell.projectileSpeed，钳到 [projectileMin, projectileMax]
   *     单体连线  hitAt = castFlash + spell.link
   *   contact   hitAt = 0
   *
   * hitAt 与 targets 同序，单位 ms、相对调用时刻、**不含顿帧**（impulse 的顿帧会把
   * 此后所有画面整体后移 hitStopMs）。duration = max(hitAt) + residueMaxMs。
   */
  function plan(kind, o) {
    const T = timing();
    const opt = o || {};
    const from = toBox(opt.from) || toBox(opt.at) || { x: 0, y: 0, ...DEFAULT_BOX };
    const targets = targetsOf(opt, from);
    let hitAt;
    if (kind === "contact") {
      hitAt = targets.map(() => 0);
    } else if (opt.attack === true || typeof opt.ranged === "boolean") {
      const ranged = typeof opt.ranged === "boolean" ? opt.ranged : !MELEE[kind];
      const A = T.attack;
      hitAt = targets.map((t) =>
        ranged ? clamp(boxDist(from, t) / A.rangedSpeed * 1000, A.rangedMin, A.rangedMax) : 0);
    } else {
      const S = T.spell;
      const aoe = !!opt.aoe || kind === "frost-field" || targets.length > 1;
      if (aoe) {
        const order = targets
          .map((t, i) => ({ i, d: boxDist(from, t) }))
          .sort((a, b) => a.d - b.d || a.i - b.i);
        hitAt = new Array(targets.length);
        order.forEach((e, r) => {
          hitAt[e.i] = S.castFlash + Math.min(r, T.staggerSteps) * T.stagger;
        });
      } else if (PROJECTILE[kind]) {
        hitAt = [S.castFlash + clamp(boxDist(from, targets[0]) / S.projectileSpeed * 1000,
          S.projectileMin, S.projectileMax)];
      } else {
        hitAt = [S.castFlash + S.link];
      }
    }
    // timeScale：导演层整体压缩一幕时传进来（0 < s ≤ 1），接触时刻与残留一起按比例缩
    const sc = scaleOf(opt);
    hitAt = hitAt.map((v) => Math.round(v * sc));
    return { hitAt, duration: Math.max(0, ...hitAt) + Math.round(T.residueMaxMs * sc) };
  }

  function scaleOf(o) {
    const s = o && Number(o.timeScale);
    return s > 0 && s <= 1 ? s : 1;
  }

  /**
   * 实例的时间映射：真实毫秒 → 技能配方的"自然毫秒"。分段线性，节点是
   * [real, natural]。每个技能只声明三个自然时刻 nat = {launch, impact, end}：
   *   launch  施法闪 / 蓄力结束、路径开始
   *   impact  接触
   *   end     接触画面全部结束
   * 映射把 impact 钉在 plan 的 hitAt 上，把 end 钉在 hitAt + residueMaxMs 上，
   * 所以"接触帧 = hitAt"与"残留 ≤ 250ms"是构造出来的，不靠逐技能手调。
   */
  function knotsFor(def, mode, hit, scale) {
    const T = timing();
    const N = def.nat;
    const sc = scale || 1;
    const R = T.residueMaxMs * sc;
    if (mode === "melee" || mode === "instant") return [[0, N.impact], [R, N.end]];
    if (mode === "ranged") return [[0, N.launch], [hit, N.impact], [hit + R, N.end]];
    if (mode === "group") {
      const pre = Math.min(GROUP_LINK * sc, hit);
      return [[0, 0], [hit - pre, N.launch], [hit, N.impact], [hit + R, N.end]];
    }
    const cf = Math.min(T.spell.castFlash * sc, hit);
    return [[0, 0], [cf, N.launch], [hit, N.impact], [hit + R, N.end]];
  }

  function mapKnots(k, t) {
    if (t <= k[0][0]) return k[0][1];
    for (let i = 0; i < k.length - 1; i++) {
      const a = k[i], b = k[i + 1];
      if (t <= b[0]) {
        const span = b[0] - a[0];
        return span <= 0 ? b[1] : a[1] + (b[1] - a[1]) * ((t - a[0]) / span);
      }
    }
    const last = k[k.length - 1];
    return last[1] + (t - last[0]);
  }

  // ================================================================ 模拟（无 GL）
  //
  // createSim 是引擎里与 WebGL 无关的那一半：实例、粒子、时钟、冲击队列、ctx。
  // create() 把它接到真实批渲染器上；node 单测把它接到一个只记几何的 sink 上。

  const NO_SCOPE = Object.freeze({ layer: "none", cx: 0, cy: 0, k: 1, env: 1, hdrK: 1 });

  function createSim(options) {
    const opts = options || {};
    const T = timing();
    const particles = createParticles(opts.maxParticles || 2600);
    const effects = [];
    const shakes = [];
    const pushes = [];
    const edges = [];
    const sim = {
      outer: 0, time: 0, freeze: 0, seq: 0,
      low: false,
      lite: false,
      debugLayer: null,
      trace: null,
      toggles: { bloom: true, distort: true },
    };
    let sink = opts.sink || null;
    let scope = NO_SCOPE;
    let cur = null;
    let lowCount = 0;

    // ---- 粒子：带上发射时的作用域、速率与残留期限 ------------------------------
    const rawEmit = particles.emit;
    particles.emit = function (o) {
      const inst = cur;
      if (!inst) return rawEmit(o);
      if (scope.layer === "skip") return null;
      // 低档：每两个粒子只发一个（契约 5：超标就降档，减粒子）
      if (sim.low && (lowCount++ & 1)) return null;
      const remain = inst.end - inst.realT;
      if (!(remain > 0)) return null;
      const cap = remain * inst.rate;
      let clamped = false;
      if (!(o.life > 0)) o.life = 400;
      if (o.life > cap) { o.life = cap; clamped = true; }
      if (o.core) o.a0 = coreAlpha(o.a0 == null ? 1 : o.a0, o.core);
      if (o.life < 8) return null;
      const p = rawEmit(o);
      if (!p) return null;
      p.rate = inst.rate;
      p.xf = scope;
      p.maxAge = cap;
      p.clamped = clamped;
      return p;
    };

    function setScope(inst, s) {
      s.env = inst.env;
      scope = s;
    }

    /**
     * 命中核心的 alpha 按档压暗（契约原则 4：卡面中央不打白）。
     *   core: true   乘 scope.coreK（按档 0.25 / 0.3 / 0.35）
     *   core: c 数字  按技能微调：乘 c × coreK / CORE_K[3]（c 是 3 档时的系数）
     * 非接触层 coreK 为空，不压。
     */
    function coreAlpha(a, core) {
      if (!core || scope.coreK == null) return a;
      return typeof core === "number" ? a * core * (scope.coreK / CORE_K[3]) : a * scope.coreK;
    }

    function hdrOf(h) {
      if (!h) return 0;
      return h > 1 ? 1 + (h - 1) * scope.hdrK : h;
    }

    function emitQuad(bucket, q) {
      const s = scope;
      if (s.layer === "skip" || (sim.debugLayer && s.layer !== sim.debugLayer)) return;
      if (s.k !== 1) {
        q.x = s.cx + (q.x - s.cx) * s.k;
        q.y = s.cy + (q.y - s.cy) * s.k;
        q.w *= s.k;
        if (q.h != null) q.h *= s.k;
      }
      if (s.env !== 1) q.col = [q.col[0], q.col[1], q.col[2], q.col[3] * s.env];
      if (sim.trace && s.layer === "path") tracePath(q.x, q.y, q.x, q.y);
      if (sink) sink.quad(bucket, q);
    }

    function emitStrip(bucket, pts, p0, p1, p2, p3, closed) {
      const s = scope;
      if (s.layer === "skip" || (sim.debugLayer && s.layer !== sim.debugLayer)) return;
      if (s.k !== 1 || s.env !== 1) {
        for (let i = 0; i < pts.length; i++) {
          const q = pts[i];
          if (s.k !== 1) {
            q.x = s.cx + (q.x - s.cx) * s.k;
            q.y = s.cy + (q.y - s.cy) * s.k;
            q.hw *= s.k;
          }
          if (s.env !== 1) q.col = [q.col[0], q.col[1], q.col[2], q.col[3] * s.env];
        }
      }
      if (sim.trace && s.layer === "path" && pts.length > 1) {
        tracePath(pts[0].x, pts[0].y, pts[pts.length - 1].x, pts[pts.length - 1].y);
      }
      if (sink) sink.strip(bucket, pts, p0, p1, p2, p3, closed);
    }

    /** 路径型画面的几何轨迹：量化表用它判"起点在 from 盒内、终点在目标盒内"。 */
    function tracePath(x0, y0, x1, y1) {
      if (!cur) return;
      sim.trace.push({
        type: "path", id: cur.id, kind: cur.kind, real: cur.realT, outer: sim.outer,
        a: [Math.round(x0), Math.round(y0)], b: [Math.round(x1), Math.round(y1)],
      });
    }

    const ctx = {
      particles,

      // ---- 作用域：路径 / 施法者 / 接触 / 地面 ------------------------------
      //
      // 每个技能在画一段东西之前声明它属于哪一层。接触层整体按 inst.xf
      // 绕目标中心等比缩放（契约原则 3，逐轴：宽 ≤ contactBoxMax × w × contactScale/1.2、
      // 高 ≤ contactBoxMax × h × contactScale/1.2），
      // 施法者层按施法者卡的大小缩放，路径层不缩放（它本来就钉在两张卡之间）。
      /** 施法者处的蓄力 / 施法闪。群体技能只有领头实例画，返回 false 时跳过。 */
      caster(inst) {
        if (!inst.leader) { scope = NO_DRAW; return false; }
        setScope(inst, inst.cxf);
        return true;
      },
      path(inst) { setScope(inst, inst.pxf); return true; },
      contact(inst) { setScope(inst, inst.xf); return true; },
      /** 接触层，但不做等比缩放：尺寸由技能按 inst.budgetW / budgetH 自己算（bladeCross 的 X）。 */
      contactBox(inst) { setScope(inst, inst.bxf); return true; },
      /** 群体地面层：不缩放，由技能自己按 inst.union + aoePad 定尺寸。只有领头实例画。 */
      ground(inst) {
        if (!inst.leader) { scope = NO_DRAW; return false; }
        setScope(inst, inst.gxf);
        return true;
      },

      /** 程序化软光点。bloom 的主要喂料。 */
      soft(x, y, size, col, alpha, o) {
        const opt = o || {};
        if (opt.core) alpha = coreAlpha(alpha, opt.core);
        if (!(alpha > 0.002)) return;
        emitQuad(opt.bucket || "add", {
          x, y, w: size, h: opt.h || size, rot: opt.rot || 0,
          squash: opt.squash, col: [col[0], col[1], col[2], alpha],
          p0: [M.SOFT, opt.falloff == null ? 2.0 : opt.falloff, 0, 0],
        });
      },

      /**
       * 溶解火焰体。cell < 0 = 程序化椭圆；否则取剪影表的一格。
       * gamma  <1 把整体推向渐变表亮端（火焰内部应该是亮的）
       * steps  色阶量化段数（赛璐璐分层），<=1 = 连续渐变
       * hdr    只把最热一段推到 1 以上，专门喂 bloom
       * flip   剪影翻转变体 0..3（配合 rot 的 90° 旋转共 16 种）
       * bucket 不透明火焰传 "body"（over 混合），辉光类留在 "add"
       */
      dissolve(o) {
        if (o.core) o = Object.assign({}, o, { alpha: coreAlpha(o.alpha, o.core) });
        if (!(o.alpha > 0.002)) return;
        emitQuad(o.bucket || "add", {
          x: o.x, y: o.y, w: o.w, h: o.h == null ? o.w : o.h,
          rot: o.rot || 0, squash: o.squash,
          col: [o.col ? o.col[0] : 1, o.col ? o.col[1] : 1, o.col ? o.col[2] : 1, o.alpha],
          p0: [M.DISSOLVE, o.threshold, o.soft == null ? 0.04 : o.soft, o.grad],
          p1: [o.noiseScale == null ? 2.0 : o.noiseScale, o.seconds || 0,
               o.cell == null ? -1 : o.cell, o.flow || 0],
          p2: [o.gamma == null ? 1 : o.gamma, o.steps || 0,
               hdrOf(o.hdr), o.flip || 0],
        });
      },

      /** 极坐标环 / 放射线。radius < 0 = 不画环。 */
      polar(o) {
        if (o.core) o = Object.assign({}, o, { alpha: coreAlpha(o.alpha, o.core) });
        if (!(o.alpha > 0.002)) return;
        emitQuad(o.bucket || "add", {
          x: o.x, y: o.y, w: o.w, h: o.h == null ? o.w : o.h,
          rot: o.rot || 0, squash: o.squash,
          col: [o.col ? o.col[0] : 1, o.col ? o.col[1] : 1, o.col ? o.col[2] : 1, o.alpha],
          p0: [M.POLAR, o.radius == null ? 0.7 : o.radius,
               o.width == null ? 0.08 : o.width, o.break == null ? 0 : o.break],
          p1: [o.rotate || 0, o.rays || 0, o.raySharp || 4, o.grad == null ? G.FIRE : o.grad],
        });
      },

      /**
       * 拖尾网格。pts = [{x, y, hw}]。
       * comet  头宽尾窄的彗尾包络；flat 恒定宽度（两者互斥，flat 优先）
       * gradLo 渐变表查表下限（默认 0.22）。走 body 桶的实心体要抬高它
       */
      trail(pts, o) {
        if (!(o.alpha > 0.002) || pts.length < 2) return;
        const col = [o.col ? o.col[0] : 1, o.col ? o.col[1] : 1, o.col ? o.col[2] : 1, o.alpha];
        const out = new Array(pts.length);
        for (let i = 0; i < pts.length; i++) {
          out[i] = { x: pts[i].x, y: pts[i].y, hw: o.width == null ? pts[i].hw : o.width, col };
        }
        emitStrip(o.bucket || "add", out,
          [M.TRAIL, o.grad == null ? G.FIRE : o.grad, o.headBias == null ? 1.4 : o.headBias,
           o.edgeSoft == null ? 0.6 : o.edgeSoft],
          [o.noise || 0, o.seconds || 0, o.flat ? 2 : (o.comet ? 1 : 0), o.gradLo || 0]);
      },

      /** 火焰剪影（不溶解）。 */
      shape(o) {
        if (!(o.alpha > 0.002)) return;
        emitQuad(o.bucket || "add", {
          x: o.x, y: o.y, w: o.w, h: o.h == null ? o.w : o.h,
          rot: o.rot || 0, squash: o.squash,
          col: [o.col ? o.col[0] : 1, o.col ? o.col[1] : 1, o.col ? o.col[2] : 1, o.alpha],
          p0: [M.SHAPE, o.cell, o.edgeSoft == null ? 0.1 : o.edgeSoft, o.grad == null ? G.FIRE : o.grad],
          p1: [o.flow || 0, o.seconds || 0, o.gradPos == null ? 1 : o.gradPos, 0],
          p2: [0, 0, hdrOf(o.hdr), o.flip || 0],
        });
      },

      /**
       * 贴图图集的一格。形状与质感全由素材给，这里只管"放哪、多大、怎么消"。
       *
       *   cell      ATLAS_CELLS 的键；格子自带图集号
       *   kind      0 加色贴图（黑底，alpha 由亮度推）/ 1 RGBA 贴图（碎石）
       *   rot       旋转（弧度），squash 在旋转之后作用（贴地元素传 0.8 上下）
       *   ax / ay   锚点（默认 0.5 中心）；"左 = 攻击者端"的条状素材传 ax 0
       *   flipX/flipY  左右 / 上下翻转
       *   threshold 噪声溶解阈值 0→1，0 = 不溶解；soft 过渡带宽（默认 0.18）
       *   reveal    径向显现 0→1.18，≥1.18 = 全开（默认全开）
       *   flow      流向图扰动强度，seconds 是它的时钟
       *   hdr       把最热一段推过 1，喂 bloom（按档降一级，见 HDR_K）
       */
      sprite(o) {
        if (o.core) o = Object.assign({}, o, { alpha: coreAlpha(o.alpha, o.core) });
        if (!(o.alpha > 0.002)) return;
        const cell = ATLAS_CELLS[o.cell];
        if (!cell) return;
        emitQuad(o.bucket || "add", {
          x: o.x, y: o.y, w: o.w, h: o.h == null ? o.w : o.h,
          rot: o.rot || 0, squash: o.squash, ax: o.ax, ay: o.ay,
          u0: o.flipX ? cell[2] : cell[0], v0: o.flipY ? cell[3] : cell[1],
          u1: o.flipX ? cell[0] : cell[2], v1: o.flipY ? cell[1] : cell[3],
          col: [o.col ? o.col[0] : 1, o.col ? o.col[1] : 1, o.col ? o.col[2] : 1, o.alpha],
          p0: [M.SPRITE, (o.kind || 0) + (cell[4] || 0) * 2, o.threshold || 0,
               o.soft == null ? 0.18 : o.soft],
          p1: [o.flow || 0, o.seconds || 0,
               o.reveal == null ? 9 : o.reveal, hdrOf(o.hdr)],
          p2: cell,
        });
      },

      /**
       * 轴向流动的贴图（MODE_SPRITE_FLOW）。和 sprite 取同一张格子表：
       *   scrollU   u 方向恒速滚动（格/秒）；seconds 是它的时钟
       *   revealU   alpha 沿 u 的推进前端 0 → 1.2；softU 带宽
       *   coneSoft  > 0 打开楔形遮罩（喷口窄、远端满高）
       *   flipX     u 方向翻转（折进 kind 的第 3 位）
       */
      spriteFlow(o) {
        if (!(o.alpha > 0.002)) return;
        const cell = ATLAS_CELLS[o.cell];
        if (!cell) return;
        emitQuad(o.bucket || "add", {
          x: o.x, y: o.y, w: o.w, h: o.h == null ? o.w : o.h,
          rot: o.rot || 0, squash: o.squash, ax: o.ax, ay: o.ay,
          col: [o.col ? o.col[0] : 1, o.col ? o.col[1] : 1, o.col ? o.col[2] : 1, o.alpha],
          p0: [M.SPRITE_FLOW,
               (o.kind || 0) + (cell[4] || 0) * 2 + (o.flipX ? 4 : 0),
               o.revealU == null ? 9 : o.revealU,
               o.softU == null ? 0.12 : o.softU],
          p1: [o.scrollU || 0, o.seconds || 0, o.coneSoft || 0, hdrOf(o.hdr)],
          p2: cell,
          p3: [o.uvDistort || 0, 0, 0, 0],
        });
      },

      /**
       * 序列帧（flipbook）。
       *   cell      ATLAS_CELLS 的键，取到的矩形是**整块 cols×rows 网格**
       *   frames    {cols, rows, count?}
       *   frame     浮点帧号，自动环绕；小数部分在相邻两帧之间 mix
       *   lerp      false = 不插值（变体表）
       *   grad      给了就开渐变映射；gradLo 暗端下限（默认 0.05）
       *   threshold 噪声溶解阈值；soft 过渡带宽（默认 0.14）；edgeWidth 边缘色
       *   uvDistort UV 扰动强度
       */
      flipbook(o) {
        if (o.core) o = Object.assign({}, o, { alpha: coreAlpha(o.alpha, o.core) });
        if (!(o.alpha > 0.002)) return;
        const cell = ATLAS_CELLS[o.cell];
        if (!cell) return;
        const fr = o.frames || FB_DEFAULT_GRID;
        const cols = fr.cols || 4;
        const rows = fr.rows || 4;
        const count = fr.count || cols * rows;
        let frame = o.frame;
        if (frame == null) frame = o.dur ? (o.t || 0) / o.dur * count : 0;
        const useGrad = o.grad != null;
        emitQuad(o.bucket || "add", {
          x: o.x, y: o.y, w: o.w, h: o.h == null ? o.w : o.h,
          rot: o.rot || 0, squash: o.squash, ax: o.ax, ay: o.ay,
          col: [o.col ? o.col[0] : 1, o.col ? o.col[1] : 1, o.col ? o.col[2] : 1, o.alpha],
          p0: [M.FLIPBOOK,
               (o.kind || 0) + (cell[4] || 0) * 2 + (o.lerp === false ? 8 : 0) +
               (useGrad ? 16 : 0),
               frame, useGrad ? o.grad : 0],
          p1: [cols + rows * 64, o.seconds || 0, o.uvDistort || 0, hdrOf(o.hdr)],
          p2: cell,
          p3: [o.threshold || 0, o.soft == null ? 0.14 : o.soft,
               o.edgeWidth || 0, o.gradLo == null ? 0.05 : o.gradLo],
        });
      },

      /**
       * 带状渲染器（Ribbon）。pts = [{x, y, hw, a?}]。
       *   cell      横向纹理的格子（u 沿长度、v 沿横截面）
       *   fadeHead / fadeTail  头 / 尾端的淡出带宽
       *   tile      u 方向平铺次数；scrollU 每秒滚多少格
       *   threshold 整条带的溶解阈值
       *   closed    首尾相接（ctx.ring 用）
       */
      ribbon(pts, o) {
        if (o.core) o = Object.assign({}, o, { alpha: coreAlpha(o.alpha, o.core) });
        if (!(o.alpha > 0.002) || !pts || pts.length < 2) return;
        const cell = ATLAS_CELLS[o.cell];
        if (!cell) return;
        const base = [o.col ? o.col[0] : 1, o.col ? o.col[1] : 1,
                      o.col ? o.col[2] : 1, o.alpha];
        const out = new Array(pts.length);
        for (let i = 0; i < pts.length; i++) {
          const q = pts[i];
          out[i] = {
            x: q.x, y: q.y, hw: o.width == null ? q.hw : o.width,
            col: q.a == null ? base : [base[0], base[1], base[2], base[3] * q.a],
          };
        }
        const useGrad = o.grad != null;
        emitStrip(o.bucket || "add", out,
          [M.RIBBON,
           (o.kind || 0) + (cell[4] || 0) * 2 + (useGrad ? 8 : 0),
           o.fadeHead == null ? 0.12 : o.fadeHead,
           o.fadeTail == null ? 0.18 : o.fadeTail],
          [o.scrollU || 0, o.seconds || 0, o.uvDistort || 0, hdrOf(o.hdr)],
          cell,
          [useGrad ? o.grad : 0, o.gradLo == null ? 0.05 : o.gradLo,
           o.tile || 1, o.threshold || 0],
          !!o.closed);
      },

      /**
       * 环渲染器：内外径各自给，环带是一条首尾相接的 ribbon，贴图沿周向铺。
       *   r0 / r1   内径 / 外径；seg 分段数（默认 48）；a0 起始角；squash 贴地压扁
       */
      ring(o) {
        if (!(o.alpha > 0.002)) return;
        const r0 = Math.min(o.r0, o.r1);
        const r1 = Math.max(o.r0, o.r1);
        if (!(r1 - r0 > 0.5)) return;
        // 轻档（低画质 / 高 DPR 手机）环的分段减半：环在 0.5 倍渲染分辨率下看不出折线
        const seg = Math.max(16, Math.round((o.seg || 48) * (sim.lite ? 0.5 : 1)));
        const q = o.squash == null ? 1 : o.squash;
        const mid = (r0 + r1) * 0.5;
        const hw = (r1 - r0) * 0.5;
        const a0 = o.a0 || 0;
        const pts = new Array(seg + 1);
        for (let i = 0; i <= seg; i++) {
          const a = a0 + (i % seg) / seg * Math.PI * 2;
          pts[i] = { x: o.x + Math.cos(a) * mid, y: o.y + Math.sin(a) * mid * q, hw };
        }
        this.ribbon(pts, Object.assign({}, o, {
          fadeHead: 0, fadeTail: 0, closed: true, width: null,
        }));
      },

      /**
       * 实心楔形 / 三角（MODE_SOLID）：两点一条带，hw0 在起点、hw1 在终点，
       * hw1 = 0 就是三角。tipFade = 终点那一端的淡出比例。bladeCross 的墨色剑气。
       */
      wedge(o) {
        if (!(o.alpha > 0.002)) return;
        const col = [o.col[0], o.col[1], o.col[2], o.alpha];
        emitStrip(o.bucket || "body", [
          { x: o.x0, y: o.y0, hw: o.hw0, col },
          { x: o.x1, y: o.y1, hw: o.hw1 || 0, col },
        ], [M.SOLID, o.tipFade || 0, 0, 0], ZERO4, ZERO4, ZERO4, false);
      },

      /** 关键帧曲线取值：ctx.curve([[0, 0], [120, 1, "out"], [300, 0]], t)。 */
      curve(track, t, fallback) {
        if (!track || !track.length) return fallback == null ? 0 : fallback;
        if (!track.__k) {
          const k = new Array(track.length);
          for (let i = 0; i < track.length; i++) {
            const r = track[i];
            k[i] = Array.isArray(r) ? { t: r[0], v: r[1], ease: r[2] } : r;
          }
          try { Object.defineProperty(track, "__k", { value: k }); } catch (e) { /* frozen */ }
          return sampleTrack(k, t, fallback);
        }
        return sampleTrack(track.__k, t, fallback);
      },

      /**
       * 发射器节点（一级子节点即可）。
       *   ctx.spawn(inst, { key, burst | rate, at, until, from, to, jitter,
       *                     speed, angle, life, size, inheritVelocity, make(o, rng) })
       * 返回这一帧实际发了多少个。
       */
      spawn(inst, o) {
        const rng = inst.rng;
        let n = 0;
        if (o.burst) {
          const key = o.key || "burst";
          if (inst.fired["spawn:" + key]) return 0;
          if (inst.t < (o.at || 0)) return 0;
          inst.fired["spawn:" + key] = true;
          n = o.burst;
        } else if (o.rate) {
          const at = o.at || 0;
          const until = o.until == null ? Infinity : o.until;
          if (inst.t < at || inst.t > until) return 0;
          const key = "spawn:" + (o.key || "rate");
          const acc = (inst.acc[key] || 0) + o.rate * (inst.dt / 1000);
          n = Math.floor(acc);
          inst.acc[key] = acc - n;
        }
        for (let i = 0; i < n; i++) {
          const u = o.to ? rng() : 0;
          const jx = o.jitter ? (rng() * 2 - 1) * o.jitter : 0;
          const jy = o.jitter ? (rng() * 2 - 1) * o.jitter : 0;
          const ang = rangeAt(rng, o.angle, 0);
          const sp = rangeAt(rng, o.speed, 0);
          const e = {
            x: lerp(o.from.x, o.to ? o.to.x : o.from.x, u) + jx,
            y: lerp(o.from.y, o.to ? o.to.y : o.from.y, u) + jy,
            vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp,
            life: rangeAt(rng, o.life, 400),
            s0: rangeAt(rng, o.size, 8),
            seed: rng() * 10,
          };
          const iv = o.inheritVelocity;
          if (iv) {
            const k = iv.k == null ? 1 : iv.k;
            e.vx += (iv.vx || 0) * k;
            e.vy += (iv.vy || 0) * k;
          }
          if (o.make) o.make(e, rng);
          particles.emit(e);
        }
        return n;
      },

      /** 写扭曲场。kind：0 径向环 / 1 热浪 / 2 单向冲击。低档整条关掉。 */
      distort(o) {
        if (!sim.toggles.distort || sim.low || !(o.strength > 0.002)) return;
        emitQuad("distort", {
          x: o.x, y: o.y, w: o.w, h: o.h == null ? o.w : o.h,
          rot: o.rot || 0, squash: o.squash,
          col: [1, 1, 1, o.alpha == null ? 1 : o.alpha],
          p0: [M.DISTORT, o.kind || 0, o.strength, o.ringRadius == null ? 0.7 : o.ringRadius],
          p1: [o.ringWidth == null ? 0.1 : o.ringWidth, o.seconds || 0, o.dirX || 1, o.dirY || 0],
        });
      },

      /** 只记轨迹不画：路径型画面是一张不贴着端点的四边形时（对角线电弧、喷火锥），
       *  由技能显式报一段 from→头部的几何，给量化探针判起点 / 终点。 */
      mark(x0, y0, x1, y1) {
        if (sim.trace && scope.layer === "path") tracePath(x0, y0, x1, y1);
      },

      once(inst, key, at, fn) {
        if (inst.fired[key]) return;
        if (inst.t < at) return;
        inst.fired[key] = true;
        fn();
      },
    };
    const NO_DRAW = Object.freeze({ layer: "skip", cx: 0, cy: 0, k: 1, env: 1, hdrK: 1 });

    // ---- 实例 ----------------------------------------------------------------

    function makeInst(kind, mode, fromBox, toBoxI, hit, opt, index, extra) {
      const def = SKILLS[kind];
      const tier = clamp(Math.round(opt.tier || 2), 1, 3);
      const tt = T.tiers[tier];
      const seed = opt.seed == null
        ? (sim.seq * 2246822519 + 12345) >>> 0
        : (opt.seed + index * 7919) >>> 0;
      const toMax = Math.max(toBoxI.w, toBoxI.h);
      const fromMax = Math.max(fromBox.w, fromBox.h);
      // 逐轴预算：宽 ≤ contactBoxMax × w × contactScale/1.2、高同理（随从横向间隙只有
      // ~16px，按 max(w,h) 算会压到邻卡）。接触层是等比缩放（贴图不变形），自然外包
      // extent 取两轴里较大的那个，所以按较紧的一轴定 k 就能同时满足两轴。
      const budgetW = T.contactBoxMax * toBoxI.w * tt.contactScale / 1.2;
      const budgetH = T.contactBoxMax * toBoxI.h * tt.contactScale / 1.2;
      const budget = Math.min(budgetW, budgetH);
      const hdrK = HDR_K[tier];
      const inst = Object.assign({
        id: sim.seq++,
        kind, def, mode, index,
        leader: index === 0,
        from: { x: fromBox.x, y: fromBox.y }, fromBox,
        to: { x: toBoxI.x, y: toBoxI.y }, toBox: toBoxI,
        hit, end: hit + T.residueMaxMs * scaleOf(opt),
        knots: knotsFor(def, mode, hit, scaleOf(opt)),
        realT: 0, t: 0, dt: 0, rate: 1, env: 1,
        tier, seed, rng: mulberry32(seed),
        tint: opt.tint || null,
        tintGrad: opt.tintGrad == null ? null : opt.tintGrad,
        scale: 1,
        // 路径宽度按两张卡里较小的那张收窄：手机上 60px 的卡配 300px 的刀光带是一整条墙
        kp: clamp(Math.min(fromMax, toMax) / PATH_REF, 0.3, 1),
        fired: {}, acc: {}, done: false, contacted: false,
        budget, budgetW, budgetH,
        xf: { layer: "contact", cx: toBoxI.x, cy: toBoxI.y,
              k: CONTACT_FILL * budget / def.extent, env: 1, hdrK, coreK: CORE_K[tier] },
        cxf: { layer: "cast", cx: fromBox.x, cy: fromBox.y,
               k: Math.min(1, CAST_FILL * fromMax / (def.castExtent || 200)), env: 1, hdrK },
        pxf: { layer: "path", cx: 0, cy: 0, k: 1, env: 1, hdrK },
        gxf: { layer: "ground", cx: 0, cy: 0, k: 1, env: 1, hdrK },
        // 接触层、但不缩放：技能自己按 budgetW / budgetH 直接在目标卡的坐标里定尺寸
        bxf: { layer: "contact", cx: 0, cy: 0, k: 1, env: 1, hdrK, coreK: CORE_K[tier] },
      }, extra || null);
      inst.t = mapKnots(inst.knots, 0);
      if (opt.k != null) inst.xf.k = opt.k; // 调试：量自然尺寸时强制 k
      if (def.init) {
        cur = inst;
        def.init(inst);
        cur = null;
      }
      return inst;
    }

    function cast(kind, o) {
      const opt = o || {};
      if (!SKILLS[kind] || kind === "contact") throw new Error("未知技能 " + kind);
      const fromBox = toBox(opt.from) || toBox(opt.at);
      if (!fromBox) throw new Error("cast 需要 from 包围盒");
      const targets = targetsOf(opt, fromBox);
      const p = plan(kind, { from: fromBox, targets, aoe: opt.aoe, timeScale: opt.timeScale });
      const group = !!opt.aoe || kind === "frost-field" || targets.length > 1;
      const union = unionBox(targets);
      targets.forEach((tb, i) => {
        effects.push(makeInst(kind, group ? "group" : "spell", fromBox, tb, p.hitAt[i], opt, i, {
          group, union, count: targets.length, targets,
        }));
      });
      return p;
    }

    function attack(family, o) {
      const opt = o || {};
      if (!SKILLS[family]) throw new Error("未知平砍族 " + family);
      const fromBox = toBox(opt.from);
      const tb = toBox(opt.to) || targetsOf(opt, null)[0];
      if (!fromBox || !tb) throw new Error("attack 需要 from / to 包围盒");
      const ranged = typeof opt.ranged === "boolean" ? opt.ranged : !MELEE[family];
      const p = plan(family, { from: fromBox, targets: [tb], ranged, timeScale: opt.timeScale });
      effects.push(makeInst(family, ranged ? "ranged" : "melee", fromBox, tb, p.hitAt[0], opt, 0, {
        group: false, union: tb, count: 1,
      }));
      return p;
    }

    function contact(o) {
      const opt = o || {};
      const at = toBox(opt.at);
      if (!at) throw new Error("contact 需要 at 包围盒");
      effects.push(makeInst("contact", "instant", at, at, 0, opt, 0, {
        group: false, union: at, count: 1,
      }));
      return plan("contact", { at, timeScale: opt.timeScale });
    }

    /**
     * 震屏 / 顿帧 / 局部边缘闪 / 推镜。导演层在接触时刻调，多目标取最高档只调一次。
     *   shake   tiers[tier].shakePx / shakeMs，外部时钟衰减
     *   freeze  tiers[tier].hitStopMs：冻住整个特效世界（实例、粒子）
     *   edge    目标卡边缘一圈加亮，外扩到 1.2 × max(w,h)，加亮量 ≤ flashMaxLuma − 1
     *   push    只有 tier 3 且 cinematic 才推镜（传奇与英雄）
     */
    function impulse(o) {
      const opt = o || {};
      const tier = clamp(Math.round(opt.tier || 1), 1, 3);
      const tt = T.tiers[tier];
      const boxes = (Array.isArray(opt.at) ? opt.at : [opt.at]).map(toBox).filter(Boolean);
      if (tt.shakePx > 0 && tt.shakeMs > 0) {
        shakes.push({ amp: tt.shakePx, dur: tt.shakeMs, age: 0, seed: sim.seq++ });
      }
      if (tt.hitStopMs > 0) sim.freeze = Math.max(sim.freeze, tt.hitStopMs);
      const amt = Math.min(EDGE_AMT[tier], T.flashMaxLuma - 1);
      for (const b of boxes) edges.push({ box: b, age: 0, dur: EDGE_MS, amt });
      if (tier === 3 && opt.cinematic && boxes.length) {
        pushes.push({ age: 0, dur: PUSH_MS, focus: { x: boxes[0].x, y: boxes[0].y } });
      }
      return { hitStopMs: tt.hitStopMs, shakeMs: tt.shakeMs, shakePx: tt.shakePx };
    }

    // ---- 时钟 ----------------------------------------------------------------

    function envOf(inst) {
      const left = inst.end - inst.realT;
      if (left >= ENV_MS) return 1;
      const u = clamp(left / ENV_MS, 0, 1);
      return u * u * (3 - 2 * u);
    }

    function step(dt) {
      sim.outer += dt;
      for (const list of [shakes, pushes, edges]) {
        for (let i = list.length - 1; i >= 0; i--) {
          list[i].age += dt;
          if (list[i].age >= list[i].dur) list.splice(i, 1);
        }
      }
      if (sim.freeze > 0) {
        const used = Math.min(sim.freeze, dt);
        sim.freeze -= used;
        dt -= used;
        if (dt <= 0) return;
      }
      for (let i = effects.length - 1; i >= 0; i--) {
        const inst = effects[i];
        const before = inst.t;
        inst.realT += dt;
        inst.t = mapKnots(inst.knots, inst.realT);
        inst.dt = Math.max(0, inst.t - before);
        inst.rate = clamp(inst.dt / dt, 0.25, 4);
        inst.env = envOf(inst);
        if (!inst.contacted && inst.realT >= inst.hit - 1e-6) {
          inst.contacted = true;
          if (sim.trace) {
            sim.trace.push({
              type: "contact", id: inst.id, kind: inst.kind, index: inst.index,
              real: inst.realT, outer: sim.outer, hit: inst.hit, natural: inst.t,
              impact: inst.def.nat.impact,
            });
          }
        }
        cur = inst;
        setScope(inst, inst.pxf);
        if (inst.def.update) inst.def.update(inst, ctx, inst.dt);
        cur = null;
        scope = NO_SCOPE;
        if (inst.realT >= inst.end) {
          inst.done = true;
          effects.splice(i, 1);
        }
      }
      sim.time += dt;
      particles.update(dt);
    }

    function busy() {
      return effects.length > 0 || particles.count > 0 || shakes.length > 0 ||
        pushes.length > 0 || edges.length > 0 || sim.freeze > 0;
    }

    // ---- 收集一帧的全部四边形 ------------------------------------------------

    function drawParticles() {
      const live = particles.live;
      for (let i = 0; i < live.length; i++) {
        const p = live[i];
        const xf = p.xf || NO_SCOPE;
        if (sim.debugLayer && xf.layer !== sim.debugLayer) continue;
        const u = p.age / p.life;
        let size = lerp(p.s0, p.s1, Math.pow(u, p.sExp));
        let alpha = lerp(p.a0, p.a1, Math.pow(u, p.aExp));
        if (p.fadeIn > 0 && u < p.fadeIn) alpha *= u / p.fadeIn;
        if (p.clamped) alpha *= clamp((p.life - p.age) / (ENV_MS * p.rate), 0, 1);
        if (!(alpha > 0.002) || size <= 0.4) continue;
        const r = lerp(p.c0[0], p.c1[0], u);
        const g = lerp(p.c0[1], p.c1[1], u);
        const b = lerp(p.c0[2], p.c1[2], u);
        const rot = p.alignVel ? Math.atan2(p.vy, p.vx) : p.rot;
        let px = p.x;
        let py = p.y;
        if (xf.k !== 1) {
          px = xf.cx + (px - xf.cx) * xf.k;
          py = xf.cy + (py - xf.cy) * xf.k;
          size *= xf.k;
        }
        let p0 = p.p0;
        let p1 = p.p1 || ZERO4;
        let p2 = ZERO4;
        let p3 = ZERO4;
        let cell = null;
        if (p.mode === M.DISSOLVE) {
          p0 = [M.DISSOLVE, lerp(p.p0[1], 0.86, Math.pow(u, 1.25)), p.p0[2], p.p0[3]];
          p1 = [p.p1[0], p.age / 900 + p.seed, p.p1[2], p.p1[3]];
        } else if (p.mode === M.SPRITE) {
          cell = p.cell;
          if (!cell) continue;
          let thr = p.p0[2] > 0 ? lerp(p.p0[2], 0.92, Math.pow(u, 1.2)) : 0;
          if (p.sinkY != null && p.y > p.sinkY) {
            const s = clamp((p.y - p.sinkY) / 40, 0, 1);
            alpha *= 1 - s;
            thr = Math.max(thr, s * 0.95);
          }
          p0 = [M.SPRITE, p.p0[1] + (cell[4] || 0) * 2, thr, p.p0[3]];
          p1 = [p1[0], p.age / 1000 + p.seed, p.p1 ? p.p1[2] : 9, p1[3]];
          p2 = cell;
        } else if (p.mode === M.FLIPBOOK) {
          cell = p.cell;
          if (!cell) continue;
          const fb = p.fb;
          const gr = fb.frames || FB_DEFAULT_GRID;
          const cols = gr.cols || 4;
          const rows = gr.rows || 4;
          const count = gr.count || cols * rows;
          const loops = fb.loops == null ? 1 : fb.loops;
          const useGrad = fb.grad != null;
          p0 = [M.FLIPBOOK,
                (fb.kind || 0) + (cell[4] || 0) * 2 + (fb.lerp === false ? 8 : 0) +
                (useGrad ? 16 : 0),
                (fb.frame0 || 0) + u * count * loops,
                useGrad ? fb.grad : 0];
          p1 = [cols + rows * 64, p.age / 1000 + p.seed,
                fb.uvDistort || 0, fb.hdr ? 1 + (fb.hdr - 1) * xf.hdrK : 0];
          p2 = cell;
          p3 = [fb.threshold ? lerp(fb.threshold, 0.92, Math.pow(u, 1.2)) : 0,
                fb.soft == null ? 0.14 : fb.soft,
                fb.edgeWidth || 0, fb.gradLo == null ? 0.05 : fb.gradLo];
        }
        if (sink) sink.quad(p.bucket, {
          x: px, y: py, w: size * p.stretch, h: size, rot,
          squash: p.squash, col: [r, g, b, alpha], p0, p1, p2, p3,
          u0: cell ? cell[0] : 0, v0: cell ? cell[1] : 0,
          u1: cell ? cell[2] : 1, v1: cell ? cell[3] : 1,
        });
      }
    }

    const EDGE_SCOPE = Object.freeze({ layer: "flash", cx: 0, cy: 0, k: 1, env: 1, hdrK: 1 });
    function drawEdges() {
      scope = EDGE_SCOPE;
      for (const e of edges) {
        const u = clamp(e.age / e.dur, 0, 1);
        const a = e.amt * (1 - u) * (1 - u);
        if (!(a > 0.002)) continue;
        const b = e.box;
        const out = 0.1 * Math.max(b.w, b.h);
        const inner = Math.max(3, 0.05 * Math.min(b.w, b.h));
        const radius = Math.min(10, 0.08 * Math.min(b.w, b.h));
        const qw = b.w + 2 * out;
        const qh = b.h + 2 * out;
        emitQuad("add", {
          x: b.x, y: b.y, w: qw, h: qh, rot: 0,
          col: [1, 1, 1, a],
          p0: [M.EDGE, b.w / 2, b.h / 2, radius],
          p1: [qw, qh, out, inner],
        });
      }
      scope = NO_SCOPE;
    }

    function collect() {
      for (let i = 0; i < effects.length; i++) {
        const inst = effects[i];
        cur = inst;
        setScope(inst, inst.pxf);
        inst.def.draw(inst, ctx);
        cur = null;
      }
      scope = NO_SCOPE;
      drawParticles();
      drawEdges();
    }

    /** 每帧把活动实例的 bloom / 折射轨道求值（取最强），并算出推镜。 */
    function evalPost() {
      const post = { bloom1: BLOOM_BASE1, bloom2: BLOOM_BASE2, distort: 0, tone: 1 };
      for (let i = 0; i < effects.length; i++) {
        const inst = effects[i];
        const P = inst.def.post || {};
        const t = inst.t;
        const bk = BLOOM_K[inst.tier] * inst.env;
        post.tone = TONE_ACTIVE;
        const b1 = sampleTrack(P.bloom1, t, BLOOM_BASE1);
        const b2 = sampleTrack(P.bloom2, t, BLOOM_BASE2);
        post.bloom1 = Math.max(post.bloom1, BLOOM_BASE1 + Math.max(0, b1 - BLOOM_BASE1) * bk);
        post.bloom2 = Math.max(post.bloom2, BLOOM_BASE2 + Math.max(0, b2 - BLOOM_BASE2) * bk);
        post.distort = Math.max(post.distort,
          sampleTrack(P.distort, t, 0) * Math.min(1, inst.xf.k) * inst.env);
      }
      if (particles.count || edges.length) post.tone = TONE_ACTIVE;
      if (!sim.toggles.bloom) { post.bloom1 = 0; post.bloom2 = 0; }
      if (!sim.toggles.distort || sim.low) post.distort = 0;
      return post;
    }

    function camera() {
      let ox = 0;
      let oy = 0;
      for (let i = 0; i < shakes.length; i++) {
        const s = shakes[i];
        const u = s.age / s.dur;
        const amp = s.amp * Math.pow(1 - u, 2);
        const ph = s.age * 0.085 + s.seed;
        ox += Math.sin(ph * 1.7) * amp;
        oy += Math.cos(ph * 2.1) * amp;
      }
      let scale = 1;
      let focus = null;
      for (const p of pushes) {
        const u = p.age / p.dur;
        const v = u < 0.12
          ? lerp(1, PUSH_PEAK, easeOut(u / 0.12))
          : lerp(PUSH_PEAK, 1, smooth(clamp((u - 0.12) / 0.88, 0, 1)));
        if (v > scale) { scale = v; focus = p.focus; }
      }
      return { ox, oy, scale, focus };
    }

    function reset() {
      effects.length = 0;
      shakes.length = 0;
      pushes.length = 0;
      edges.length = 0;
      particles.clear();
      sim.outer = 0;
      sim.time = 0;
      sim.freeze = 0;
      sim.seq = 0;
      lowCount = 0;
    }

    return {
      sim, ctx, particles, effects,
      cast, attack, contact, impulse,
      step, busy, collect, evalPost, camera, reset,
      setSink(s) { sink = s; },
    };
  }

  // ================================================================== 引擎（GL）

  function create(options) {
    const opts = options || {};
    const canvas = opts.canvas;
    if (!canvas) throw new Error("EmberFx2Engine.create 需要 canvas");

    // 设备档：DPR > 1.5 的屏幕（高 DPR 手机）与"低画质"只降渲染分辨率（0.5）
    // 并跳过 1/8 级 bloom，不换管线（契约原则 7）。
    const deviceDpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
    const highDpr = deviceDpr > 1.5;

    const state = {
      renderScale: opts.renderScale || (highDpr ? 0.5 : 1),
      highDpr,
      low: false,
      stageW: opts.stageW || STAGE_W,
      stageH: opts.stageH || STAGE_H,
      globalTimeScale: 1,
      paused: false,
      ready: false,
      destroyed: false,
      manual: false,
      lastRafAt: 0,
      jsMs: 0,
      jsMsLast: 0,
      jsMsPeak: 0,
      drawCalls: 0,
      passes: 0,
      quads: 0,
      dirty: false,
      halfFloat: false,
      rtFormat: "RGBA8",
      texUnits: 0,
    };

    const core = createSim({ maxParticles: opts.maxParticles || 2600 });
    const sim = core.sim;
    sim.lite = highDpr;

    const gl = canvas.getContext("webgl", {
      // 透明画布：这一层叠在战场之上，空闲时必须能被看穿
      alpha: true,
      antialias: false,
      depth: false,
      stencil: false,
      // 预乘 alpha：收尾 pass 输出预乘颜色 + 覆盖率，浏览器按 dst = src.rgb + dst*(1-a) 合成
      premultipliedAlpha: true,
      // 快档截图与量化探针要在 debugSeek 之后读这一帧的像素
      preserveDrawingBuffer: true,
      powerPreference: "high-performance",
    });
    if (!gl) throw new Error("WebGL1 不可用");

    const extHF = gl.getExtension("OES_texture_half_float");
    const extHFL = gl.getExtension("OES_texture_half_float_linear");
    const extCBHF =
      gl.getExtension("EXT_color_buffer_half_float") ||
      gl.getExtension("WEBGL_color_buffer_float");
    const HALF_FLOAT_OES = extHF ? extHF.HALF_FLOAT_OES : 0x8d61;
    let rtType = gl.UNSIGNED_BYTE;
    if (!opts.forceRGBA8 && extHF && extHFL && extCBHF) {
      rtType = HALF_FLOAT_OES;
      state.halfFloat = true;
      state.rtFormat = "RGBA16F(half)";
    } else if (opts.forceRGBA8) {
      state.rtFormat = "RGBA8(forceRGBA8)";
    }

    let programs = null;
    let batch = null;
    let textures = null;
    let quadBuffer = null;
    const rts = {};
    let lastPost = null;
    let lastCam = { ox: 0, oy: 0, scale: 1, focus: null };

    // ------------------------------------------------------------- RT 管理

    function makeRT(name, w, h) {
      const tex = gl.createTexture();
      gl.bindTexture(gl.TEXTURE_2D, tex);
      gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
      gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, w, h, 0, gl.RGBA, rtType, null);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      const fb = gl.createFramebuffer();
      gl.bindFramebuffer(gl.FRAMEBUFFER, fb);
      gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex, 0);
      const ok = gl.checkFramebufferStatus(gl.FRAMEBUFFER) === gl.FRAMEBUFFER_COMPLETE;
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      return { name, tex, fb, w, h, ok };
    }

    function dropRT(rt) {
      if (!rt) return;
      gl.deleteTexture(rt.tex);
      gl.deleteFramebuffer(rt.fb);
    }

    const RT_NAMES = ["scene", "fx", "distort", "comp", "b1a", "b1b", "b2a", "b2b"];
    function allocRTs() {
      const w = canvas.width;
      const h = canvas.height;
      if (rts.scene && rts.scene.w === w && rts.scene.h === h) return;
      RT_NAMES.forEach((k) => dropRT(rts[k]));
      const q = (v) => Math.max(1, Math.round(v));
      rts.scene = makeRT("scene", w, h);
      rts.fx = makeRT("fx", w, h);
      rts.distort = makeRT("distort", q(w / 2), q(h / 2));
      rts.comp = makeRT("comp", w, h);
      rts.b1a = makeRT("b1a", q(w / 4), q(h / 4));
      rts.b1b = makeRT("b1b", q(w / 4), q(h / 4));
      rts.b2a = makeRT("b2a", q(w / 8), q(h / 8));
      rts.b2b = makeRT("b2b", q(w / 8), q(h / 8));
      const bad = RT_NAMES.filter((k) => rts[k] && !rts[k].ok);
      if (bad.length && rtType !== gl.UNSIGNED_BYTE) {
        rtType = gl.UNSIGNED_BYTE;
        state.halfFloat = false;
        state.rtFormat = "RGBA8(half-float 退化)";
        RT_NAMES.forEach((k) => { dropRT(rts[k]); rts[k] = null; });
        allocRTs();
        return;
      }
      if (bad.length) throw new Error("帧缓冲不完整：" + bad.join(","));
    }

    function sizeCanvas() {
      const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
      const w = Math.max(1, Math.round(state.stageW * dpr * state.renderScale));
      const h = Math.max(1, Math.round(state.stageH * dpr * state.renderScale));
      if (canvas.width !== w || canvas.height !== h) {
        canvas.width = w;
        canvas.height = h;
      }
      if (state.ready) allocRTs();
    }

    // ------------------------------------------------------------- 演出（DOM）

    function applyStage(cam) {
      // 震屏 / 推镜只作用在 opts.cameraTargets 上（棋盘与特效层；英雄卡按 t.shake
      // 做同相位轻震、不缩放）。HUD、手牌不在其中。
      const targets = opts.cameraTargets;
      if (!targets || !targets.length) return;
      const ox = cam.ox;
      const oy = cam.oy;
      const sc = cam.scale;
      const f = cam.focus || { x: state.stageW / 2, y: state.stageH / 2 };
      if (sc === 1 && ox === 0 && oy === 0) {
        for (let i = 0; i < targets.length; i++) {
          const t = targets[i];
          if (!t.el || t.el.style.transform === "") continue;
          t.el.style.transform = "";
          t.el.style.transformOrigin = "";
        }
        return;
      }
      const shift =
        "translate3d(" + ox.toFixed(2) + "px," + oy.toFixed(2) + "px,0) scale(" +
        sc.toFixed(4) + ")";
      for (let i = 0; i < targets.length; i++) {
        const t = targets[i];
        if (!t.el) continue;
        if (t.shake) {
          const sx = ox * t.shake;
          const sy = oy * t.shake;
          if (!sx && !sy) {
            if (t.el.style.transform !== "") {
              t.el.style.transform = "";
              t.el.style.transformOrigin = "";
            }
            continue;
          }
          t.el.style.transformOrigin = "";
          t.el.style.transform =
            "translate3d(" + sx.toFixed(2) + "px," + sy.toFixed(2) + "px,0)";
          continue;
        }
        t.el.style.transformOrigin =
          (f.x - (t.ox || 0)).toFixed(1) + "px " + (f.y - (t.oy || 0)).toFixed(1) + "px";
        t.el.style.transform = shift;
      }
    }

    // ------------------------------------------------------------------ 渲染

    function bindRT(rt) {
      if (rt) {
        gl.bindFramebuffer(gl.FRAMEBUFFER, rt.fb);
        gl.viewport(0, 0, rt.w, rt.h);
      } else {
        gl.bindFramebuffer(gl.FRAMEBUFFER, null);
        gl.viewport(0, 0, canvas.width, canvas.height);
      }
      state.passes += 1;
    }

    function fullscreen(prog) {
      gl.useProgram(prog.p);
      gl.bindBuffer(gl.ARRAY_BUFFER, quadBuffer);
      gl.enableVertexAttribArray(prog.aPos);
      gl.vertexAttribPointer(prog.aPos, 2, gl.FLOAT, false, 0, 0);
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
      state.drawCalls += 1;
    }

    function bindTex(unit, tex, loc) {
      gl.activeTexture(gl.TEXTURE0 + unit);
      gl.bindTexture(gl.TEXTURE_2D, tex);
      gl.uniform1i(loc, unit);
    }

    function scenePass(target) {
      bindRT(target);
      gl.disable(gl.BLEND);
      const p = programs.scene;
      gl.useProgram(p.p);
      gl.bindBuffer(gl.ARRAY_BUFFER, quadBuffer);
      gl.enableVertexAttribArray(p.aPos);
      gl.vertexAttribPointer(p.aPos, 2, gl.FLOAT, false, 0, 0);
      bindTex(0, textures.host || textures.black, p.u.uScene);
      gl.uniform1f(p.u.uHasScene, textures.host ? 1 : 0);
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
      state.drawCalls += 1;
    }

    function forceChainRender() {
      state.forceChain = true;
      render();
      state.forceChain = false;
    }

    function render() {
      if (!state.ready || state.destroyed) return;
      const t0 = performance.now();
      state.drawCalls = 0;
      state.passes = 0;

      const post = state.postOverride
        ? Object.assign({ bloom1: 0, bloom2: 0, distort: 0, tone: 1 }, state.postOverride)
        : core.evalPost();
      lastPost = post;
      const cam = core.camera();
      lastCam = cam;
      const active = core.busy() || state.forceChain;

      gl.disable(gl.DEPTH_TEST);

      if (!active) {
        // 空闲路径：整条链跳过，画布清空，0 draw call
        if (state.dirty) {
          gl.bindFramebuffer(gl.FRAMEBUFFER, null);
          gl.viewport(0, 0, canvas.width, canvas.height);
          gl.clearColor(0, 0, 0, 0);
          gl.clear(gl.COLOR_BUFFER_BIT);
          state.dirty = false;
        }
        batch.reset();
        state.quads = 0;
        applyStage(cam);
        const ms0 = performance.now() - t0;
        state.jsMsLast = ms0;
        state.jsMs = state.jsMs ? state.jsMs * 0.88 + ms0 * 0.12 : ms0;
        if (ms0 > state.jsMsPeak) state.jsMsPeak = ms0;
        return;
      }

      state.dirty = true;
      // ---- 1) 场景（只有折射要用；低档不折射就不传）------------------------
      const wantDistortPass = post.distort > 0.01;
      if (wantDistortPass) scenePass(rts.scene);

      // ---- 2) 特效 + 3) 扭曲 --------------------------------------------------
      batch.reset();
      const tc = performance.now();
      core.collect();
      state.collectMsLast = performance.now() - tc;
      gl.useProgram(programs.sprite.p);
      gl.uniform2f(programs.sprite.u.uStage, state.stageW, state.stageH);
      gl.uniform1f(programs.sprite.u.uTime, sim.time / 1000);
      gl.uniform1f(programs.sprite.u.uGradRows, textures.gradRows);
      // 采样器 uniform 在链接时已经一次性设好（见 ready），这里只绑纹理单元
      for (let unit = 0; unit < TEXTURE_KEYS.length; unit++) {
        gl.activeTexture(gl.TEXTURE0 + unit);
        gl.bindTexture(gl.TEXTURE_2D, textures[TEXTURE_KEYS[unit]]);
      }

      bindRT(rts.fx);
      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);
      gl.enable(gl.BLEND);
      // 加性元素只加 rgb，alpha 通道保持（它的语义是"遮住了多少背景"）
      gl.blendFuncSeparate(gl.ONE, gl.ONE, gl.ZERO, gl.ONE);
      batch.flushBucket("ground");
      batch.flushBucket("add");
      gl.blendFuncSeparate(gl.ONE, gl.ONE_MINUS_SRC_ALPHA, gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
      batch.flushBucket("body");
      batch.flushBucket("smoke");

      const wantDistort = wantDistortPass && batch.has("distort");
      if (wantDistort) {
        bindRT(rts.distort);
        gl.clearColor(0.5, 0.5, 0, 1);
        gl.clear(gl.COLOR_BUFFER_BIT);
        gl.blendFuncSeparate(gl.ONE, gl.ONE_MINUS_SRC_ALPHA, gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
        batch.flushBucket("distort");
      }

      gl.disable(gl.BLEND);

      // ---- 4~6) bloom：低档（低画质 / 高 DPR）砍掉 1/8 级 ------------------
      const lowTier = state.low || (state.highDpr && state.renderScale <= 0.5);
      const wantBloom2 = !lowTier && post.bloom2 > 0.004;
      const wantBloom = post.bloom1 > 0.004 || wantBloom2;
      if (wantBloom) {
        const pb = programs.bright;
        bindRT(rts.b1a);
        gl.useProgram(pb.p);
        bindTex(0, rts.fx.tex, pb.u.uTex);
        gl.uniform1f(pb.u.uThreshold, opts.bloomThreshold == null ? 1.0 : opts.bloomThreshold);
        gl.uniform1f(pb.u.uKnee, 0.28);
        gl.uniform2f(pb.u.uTexel, 1 / rts.fx.w, 1 / rts.fx.h);
        fullscreen(pb);

        const pblur = programs.blur;
        gl.useProgram(pblur.p);
        bindRT(rts.b1b);
        bindTex(0, rts.b1a.tex, pblur.u.uTex);
        gl.uniform2f(pblur.u.uTexel, 1 / rts.b1a.w, 1 / rts.b1a.h);
        gl.uniform2f(pblur.u.uDir, 1, 0);
        gl.uniform1f(pblur.u.uScale, 1);
        fullscreen(pblur);
        bindRT(rts.b1a);
        bindTex(0, rts.b1b.tex, pblur.u.uTex);
        gl.uniform2f(pblur.u.uDir, 0, 1);
        fullscreen(pblur);
        if (wantBloom2) {
          bindRT(rts.b2a);
          bindTex(0, rts.b1a.tex, pblur.u.uTex);
          gl.uniform2f(pblur.u.uTexel, 1 / rts.b1a.w, 1 / rts.b1a.h);
          gl.uniform2f(pblur.u.uDir, 1, 0);
          gl.uniform1f(pblur.u.uScale, 2);
          fullscreen(pblur);
          bindRT(rts.b2b);
          bindTex(0, rts.b2a.tex, pblur.u.uTex);
          gl.uniform2f(pblur.u.uTexel, 1 / rts.b2a.w, 1 / rts.b2a.h);
          gl.uniform2f(pblur.u.uDir, 0, 1);
          gl.uniform1f(pblur.u.uScale, 1);
          fullscreen(pblur);
        }
      }

      // ---- 7) 合成 -----------------------------------------------------------
      const pc = programs.composite;
      bindRT(rts.comp);
      gl.useProgram(pc.p);
      bindTex(0, (wantDistort ? rts.scene : rts.fx).tex, pc.u.uScene);
      bindTex(1, rts.fx.tex, pc.u.uFx);
      bindTex(2, wantDistort ? rts.distort.tex : textures.black, pc.u.uDistort);
      bindTex(3, wantBloom ? rts.b1a.tex : textures.black, pc.u.uBloom1);
      bindTex(4, wantBloom2 ? rts.b2b.tex : textures.black, pc.u.uBloom2);
      gl.uniform1f(pc.u.uDistortPx, wantDistort ? post.distort : 0);
      gl.uniform2f(pc.u.uStage, state.stageW, state.stageH);
      gl.uniform1f(pc.u.uBloom1W, wantBloom ? post.bloom1 : 0);
      gl.uniform1f(pc.u.uBloom2W, wantBloom2 ? post.bloom2 : 0);
      gl.uniform1f(pc.u.uFxGain, 1.0);
      fullscreen(pc);

      // ---- 8) 收尾：只剩色调压缩 -----------------------------------------------
      const pf = programs.final;
      bindRT(null);
      gl.useProgram(pf.p);
      bindTex(0, rts.comp.tex, pf.u.uTex);
      gl.uniform1f(pf.u.uTone, post.tone);
      fullscreen(pf);

      applyStage(cam);
      state.drawCalls += batch.drawCalls;
      state.quads = batch.quads;
      const ms = performance.now() - t0;
      state.jsMsLast = ms;
      state.jsMs = state.jsMs ? state.jsMs * 0.88 + ms * 0.12 : ms;
      if (ms > state.jsMsPeak) state.jsMsPeak = ms;
    }

    /**
     * 预热：用一个独立的模拟器把每个技能在屏外跑一遍（几何写进真实批渲染器、但不
     * flush）。第一次施法时各技能的 draw/update 还没被 JIT 优化，手机 4× 降速下首发
     * 的 JS 时间是热身后的 3~4 倍；载入时一次性付掉，约几毫秒。
     */
    function warmup() {
      const w = createSim({ maxParticles: 600, sink: batch });
      const a = { x: 200, y: 700, w: 120, h: 160 };
      const b = { x: 800, y: 300, w: 116, h: 146 };
      for (const kind of SKILL_ORDER) {
        if (kind === "contact") w.contact({ at: b, tier: 2 });
        else if (MELEE[kind] || kind === "arrow" || kind === "spear" || kind === "bolt" || kind === "breath") {
          w.attack(kind, { from: a, to: b, tier: 2 });
        } else w.cast(kind, { from: a, targets: kind === "frost-field" ? [b, a] : [b], tier: 2 });
      }
      w.impulse({ at: b, tier: 3, cinematic: true });
      for (let i = 0; i < 48 && w.busy(); i++) {
        w.step(FIXED_DT);
        batch.reset();
        w.collect();
        w.evalPost();
      }
      batch.reset();
    }

    // ------------------------------------------------------------- 外部时钟

    function drawAt(now) {
      if (!state.ready || state.destroyed || state.paused || state.manual) return;
      let dt = state.lastRafAt ? now - state.lastRafAt : FIXED_DT;
      state.lastRafAt = now;
      if (!core.busy() && !state.dirty) return;
      dt = clamp(dt, 0, 64) * state.globalTimeScale;
      core.step(dt);
      render();
    }

    // ------------------------------------------------------------------- 加载

    function compile(type, src, label) {
      const sh = gl.createShader(type);
      gl.shaderSource(sh, src);
      gl.compileShader(sh);
      if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS)) {
        const log = gl.getShaderInfoLog(sh);
        gl.deleteShader(sh);
        throw new Error(label + " 编译失败：" + log);
      }
      return sh;
    }

    function link(vsSrc, fsSrc, label) {
      const vs = compile(gl.VERTEX_SHADER, vsSrc, label + " 顶点");
      const fs = compile(gl.FRAGMENT_SHADER, fsSrc, label + " 片元");
      const p = gl.createProgram();
      gl.attachShader(p, vs);
      gl.attachShader(p, fs);
      gl.linkProgram(p);
      if (!gl.getProgramParameter(p, gl.LINK_STATUS)) {
        throw new Error(label + " 链接失败：" + gl.getProgramInfoLog(p));
      }
      gl.deleteShader(vs);
      gl.deleteShader(fs);
      return p;
    }

    function uniforms(p, names) {
      const u = {};
      names.forEach((n) => (u[n] = gl.getUniformLocation(p, n)));
      return u;
    }

    function makeImageTexture(img, repeat, mipmap) {
      const tex = gl.createTexture();
      gl.bindTexture(gl.TEXTURE_2D, tex);
      gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
      gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, img);
      const wrap = repeat ? gl.REPEAT : gl.CLAMP_TO_EDGE;
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, wrap);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, wrap);
      if (mipmap) gl.generateMipmap(gl.TEXTURE_2D);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER,
        mipmap ? gl.LINEAR_MIPMAP_LINEAR : gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      return tex;
    }

    const ready = Promise.all(
      TEXTURE_KEYS.map((k) => loadImage(TEXTURE_SRC[k].src)),
    ).then((imgs) => {
      if (state.destroyed) return api;
      // 片元着色器同时绑 TEXTURE_KEYS.length 个纹理单元。WebGL1 规范保证的下限是 8，
      // 掉到需要值以下时直接报错，而不是让驱动静默返回黑贴图。
      state.texUnits = gl.getParameter(gl.MAX_TEXTURE_IMAGE_UNITS);
      if (state.texUnits < TEXTURE_KEYS.length) {
        throw new Error("GPU 只给 " + state.texUnits + " 个片元纹理单元，fx2 需要 "
          + TEXTURE_KEYS.length + "（见 TEXTURE_SRC）");
      }
      const atoms = SPRITE_ATOMS.map(shader);
      const spriteFrag = atoms.join("\n");

      const fullVert = shader("fullscreen.vert.glsl");
      programs = {
        scene: { p: link(fullVert, shader("scene-blit.frag.glsl"), "场景") },
        sprite: { p: link(shader("sprite.vert.glsl"), spriteFrag, "特效") },
        bright: { p: link(fullVert, shader("post-bright.frag.glsl"), "bloom 提亮") },
        blur: { p: link(fullVert, shader("post-blur.frag.glsl"), "高斯模糊") },
        composite: { p: link(fullVert, shader("post-composite.frag.glsl"), "合成") },
        final: { p: link(fullVert, shader("post-final.frag.glsl"), "收尾") },
      };
      programs.scene.aPos = gl.getAttribLocation(programs.scene.p, "aPos");
      programs.scene.u = uniforms(programs.scene.p, ["uScene", "uHasScene"]);
      programs.sprite.u = uniforms(programs.sprite.p, [
        "uStage", "uTime", "uGradRows",
        ...TEXTURE_KEYS.map((k) => TEXTURE_SRC[k].uniform),
      ]);
      ["bright", "blur", "composite", "final"].forEach((k) => {
        programs[k].aPos = gl.getAttribLocation(programs[k].p, "aPos");
      });
      programs.bright.u = uniforms(programs.bright.p, ["uTex", "uThreshold", "uKnee", "uTexel"]);
      programs.blur.u = uniforms(programs.blur.p, ["uTex", "uTexel", "uDir", "uScale"]);
      programs.composite.u = uniforms(programs.composite.p, [
        "uScene", "uFx", "uDistort", "uBloom1", "uBloom2",
        "uDistortPx", "uStage", "uBloom1W", "uBloom2W", "uFxGain",
      ]);
      programs.final.u = uniforms(programs.final.p, ["uTex", "uTone"]);

      quadBuffer = gl.createBuffer();
      gl.bindBuffer(gl.ARRAY_BUFFER, quadBuffer);
      gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);

      const black = gl.createTexture();
      gl.bindTexture(gl.TEXTURE_2D, black);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, 1, 1, 0, gl.RGBA, gl.UNSIGNED_BYTE,
        new Uint8Array([0, 0, 0, 255]));
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);

      textures = { host: null, black, gradRows: 4 };
      TEXTURE_KEYS.forEach((k, i) => {
        const spec = TEXTURE_SRC[k];
        textures[k] = makeImageTexture(imgs[i], !!spec.repeat, !!spec.mipmap);
        if (k === "grad") textures.gradRows = imgs[i].naturalHeight || 4;
      });

      gl.useProgram(programs.sprite.p);
      TEXTURE_KEYS.forEach((k, unit) => {
        gl.uniform1i(programs.sprite.u[TEXTURE_SRC[k].uniform], unit);
      });
      batch = createBatcher(gl, programs.sprite.p);
      core.setSink(batch);
      warmup();
      sizeCanvas();
      allocRTs();
      state.ready = true;
      render();
      return api;
    });

    // -------------------------------------------------------------------- API

    const api = {
      ready,
      SKILLS,
      plan,

      /** 法术：一个目标一个实例，群体按 plan 错开。返回 plan 的结果。 */
      cast(kind, o) { return core.cast(kind, o); },
      /** 平砍的点缀与弹道。近战在碰撞那一刻调，远程在后坐结束时调。 */
      attack(family, o) { return core.attack(family, o); },
      /** 无来源的通用接触点（疲劳、亡语伤害）。 */
      contact(o) { return core.contact(o); },
      /** 震屏 / 顿帧 / 局部边缘闪 / 推镜。 */
      impulse(o) { return core.impulse(o); },
      /** 丢掉所有在飞的实例、粒子与冲击（导演层取消一幕时调）。下一帧清屏、复位 DOM 变换。 */
      clear() {
        core.reset();
        state.dirty = true;
        applyStage({ ox: 0, oy: 0, scale: 1, focus: null });
      },

      /** 施法开始时把宿主世界画布上传一次，供折射采样。 */
      uploadScene(source) {
        if (state.destroyed || !state.ready || !source) return false;
        if (!textures.host) {
          textures.host = gl.createTexture();
          gl.bindTexture(gl.TEXTURE_2D, textures.host);
          gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
          gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
          gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
          gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
        }
        gl.bindTexture(gl.TEXTURE_2D, textures.host);
        gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
        try {
          gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, source);
        } catch (err) {
          gl.deleteTexture(textures.host);
          textures.host = null;
        }
        gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
        return !!textures.host;
      },

      /** 每帧由宿主 tick 调用。空闲时不产生任何 draw call。 */
      draw(now) {
        drawAt(now);
      },

      /** 舞台尺寸（桌面 1600×940；手机是视口 CSS 像素）。变了就重配画布与 RT。 */
      setStage(w, h) {
        if (!(w > 0 && h > 0)) return;
        if (w === state.stageW && h === state.stageH) return;
        state.stageW = w;
        state.stageH = h;
        sizeCanvas();
        if (state.ready) render();
      },

      /** 低档：renderScale 0.5、跳过 1/8 bloom、关折射、粒子减半。 */
      setQuality(q) {
        const low = !!(q && q.low);
        state.low = low;
        sim.low = low;
        sim.lite = low || highDpr;
        const scale = low || highDpr ? 0.5 : 1;
        if (scale !== state.renderScale) {
          state.renderScale = scale;
          sizeCanvas();
        }
      },

      debugReset() {
        state.lastRafAt = 0;
        core.reset();
        state.jsMsPeak = 0;
        state.manual = true;
        (opts.cameraTargets || []).forEach((t) => {
          if (!t.el) return;
          t.el.style.transform = "";
          t.el.style.transformOrigin = "";
        });
        if (state.ready) render();
      },

      /** 推进到外部时钟 ms（含顿帧）并渲染一帧。固定步长 + 定种随机 ⇒ 可复现。 */
      debugSeek(ms) {
        state.manual = true;
        state.lastRafAt = 0;
        let guard = 0;
        while (sim.outer + 1e-6 < ms && guard++ < 40000) {
          core.step(Math.min(FIXED_DT, ms - sim.outer));
        }
        render();
        return sim.outer;
      },

      /** 只画场景、不画特效，读回画布像素：验证空闲时这一层完全透明。 */
      debugScenePixels(override) {
        state.manual = true;
        core.reset();
        state.postOverride = override || null;
        state.dirty = true;
        forceChainRender();
        const w = canvas.width;
        const h = canvas.height;
        const buf = new Uint8Array(w * h * 4);
        gl.bindFramebuffer(gl.FRAMEBUFFER, null);
        gl.readPixels(0, 0, w, h, gl.RGBA, gl.UNSIGNED_BYTE, buf);
        state.postOverride = null;
        return { width: w, height: h, data: buf };
      },

      /** 读回当前画布像素（量化探针用）。 */
      debugPixels() {
        const w = canvas.width;
        const h = canvas.height;
        const buf = new Uint8Array(w * h * 4);
        gl.bindFramebuffer(gl.FRAMEBUFFER, null);
        gl.readPixels(0, 0, w, h, gl.RGBA, gl.UNSIGNED_BYTE, buf);
        return { width: w, height: h, data: buf, stageW: state.stageW, stageH: state.stageH };
      },

      /** 只画某一层（"path" / "cast" / "contact" / "ground" / "flash"），null = 全画。 */
      set debugLayer(v) { sim.debugLayer = v || null; },
      get debugLayer() { return sim.debugLayer; },
      /** 打开后记录接触帧与路径几何（数组），null 关闭。 */
      set trace(v) { sim.trace = v || null; },
      get trace() { return sim.trace; },

      debugResume() {
        state.manual = false;
        state.lastRafAt = 0;
      },

      setRenderScale(s) {
        state.renderScale = s;
        sizeCanvas();
        render();
      },

      setTimeScale(s) {
        state.globalTimeScale = s;
      },

      setToggle(name, on) {
        if (!(name in sim.toggles)) throw new Error("未知开关 " + name);
        sim.toggles[name] = !!on;
        render();
      },

      get toggles() {
        return Object.assign({}, sim.toggles);
      },

      pause() {
        state.paused = true;
        state.lastRafAt = 0;
      },

      resume() {
        state.paused = false;
        state.lastRafAt = 0;
      },

      destroy() {
        state.destroyed = true;
        if (batch) batch.destroy();
        Object.keys(rts).forEach((k) => dropRT(rts[k]));
        if (textures) Object.keys(textures).forEach((k) => {
          if (textures[k] && textures[k].constructor !== Number) gl.deleteTexture(textures[k]);
        });
        if (quadBuffer) gl.deleteBuffer(quadBuffer);
        if (programs) Object.keys(programs).forEach((k) => gl.deleteProgram(programs[k].p));
      },

      get stats() {
        return {
          ready: state.ready,
          time: sim.time,
          outer: sim.outer,
          effects: core.effects.length,
          particles: core.particles.count,
          texUnits: state.texUnits,
          textures: TEXTURE_KEYS.length,
          drawCalls: state.drawCalls,
          passes: state.passes,
          quads: state.quads,
          jsMs: state.jsMs,
          jsMsLast: state.jsMsLast,
          jsMsPeak: state.jsMsPeak,
          collectMsLast: state.collectMsLast || 0,
          renderScale: state.renderScale,
          canvasWidth: canvas.width,
          canvasHeight: canvas.height,
          stageW: state.stageW,
          stageH: state.stageH,
          overflow: batch ? batch.overflow : 0,
          rtFormat: state.rtFormat,
          halfFloat: state.halfFloat,
          devicePixelRatio: deviceDpr,
          low: state.low,
          lowTier: state.low || (state.highDpr && state.renderScale <= 0.5),
          busy: core.busy(),
          freeze: sim.freeze,
          post: lastPost,
          camera: lastCam,
        };
      },

      resetPeaks() {
        state.jsMsPeak = 0;
      },
    };

    return api;
  }

  return {
    create,
    createSim,
    plan,
    STAGE_W,
    STAGE_H,
    SKILL_ORDER,
    SKILLS,
    MODES: M,
    GRADIENTS: G,
    skillLabel: (k) => (SKILLS[k] ? SKILLS[k].label : k),
  };
})();
if (typeof module !== "undefined") module.exports = EmberFx2Engine;
